(window.GIM_TS=window.GIM_TS||{})["Shabbat.10"]={"from":240,"a":[["\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אבא בר כהנא: \u0003כאותן של בית אביך\u0004 שהיו גדולים (תוספות).","\u0003ו\u0004בדומה לזה מסופר ש\u0003אמר ר' אבא בר כהנא\u0004 שכך \u0003אמר ר' חנינא: קרונות של בית רבי מותר לטלטלן בשבת. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא\u0004 לר' אבא בר כהנא: קרונות אלה שאמרת האם מדובר \u0003בניטלין\u0004 ומיטלטלים על ידי \u0003אדם אחד או בשני בני אדם? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כאותן של בית אביך.\u0004","\u0003ואמר ר' אבא בר כהנא: התיר להם ר' חנינא לבית רבי לשתות יין בקרונות של גוי\u0004 המביאים יין, ואפילו לא היו כדי היין חתומים אלא \u0003בחותם אחד\u0004 בלבד, ולא חשש שמא פתח הגוי את הכד וניסך ממנו יין או נגע בו, ואסרו בשתיה. והוסיף ר' אבא בר כהנא: \u0003ולא ידענא אי\u0004 \u0005[ואיני יודע אם]\u0006 \u0003משום דסבר לה\u0004 \u0005[שסבור]\u0006 ר' חנינא \u0003כ\u0004שיטת \u0003ר' אליעזר\u0004 המתיר יין שהיה בידי גוי בחותם אחד, \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום אימתא דבי נשיאה\u0004 \u0005[אימת בית הנשיא],\u0006 שוודאי לא יעז הגוי לפתוח חבית יין שנועדה בשביל בית הנשיא, ואין זה היתר כללי.","\u0003גוי שהדליק את הנר\u0004 בשבת לצורך עצמו — \u0003משתמש לאורו\u0004 זה גם ה\u0003ישראל. ואם\u0004 הדליקו הגוי \u0003בשביל ישראל\u0004 — \u0003אסור\u0004 מדברי חכמים. וכן אם \u0003מילא\u0004 הגוי בשבת מבור שהיה ברשות הרבים \u0003מים\u0004 כדי \u0003להשקות\u0004 את \u0003בהמתו\u0004 שלו — \u0003משקה אחריו ישראל\u0004 מאותם מים, \u0003ואם\u0004 מילא מלכתחילה \u0003בשביל ישראל\u0004 — \u0003אסור\u0004 לישראל להשקות לבהמתו מאותם מים. וכן אם \u0003עשה גוי\u0004 בשבת \u0003כבש\u0004 כדי \u0003לירד בו\u0004 מן הספינה — \u0003יורד אחריו ישראל, ואם בשביל ישראל\u0004 עשאו — \u0003אסור.\u0004 ומסופר \u0003מעשה ברבן גמליאל וזקנים שהיו באין בספינה ועשה נכרי כבש\u0004 בשבת כדי \u0003לירד בו\u0004 מן הספינה, \u0003וירדו בו רבן גמליאל וזקנים.\u0004","ומעירים בגמרא: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 לחזור וללמדנו אותה הלכה בכל המקרים, \u0003דאי אשמעינן\u0004 \u0005[שאילו היה משמיע לנו]\u0006 הלכה זו ב\u0003נר\u0004 בלבד, הייתי אומר שהדין כך \u0003משום\u0004 ש\u0003נר לאחד נר למאה,\u0004 שאין צורך להרבות בנרות לצורך הרבים, ודי בנר אחד להרבה אנשים ולכן מותר להשתמש בנר שהדליק גוי, \u0003אבל מים ליגזר דילמא אתי לאפושי\u0004 \u0005[\u0006יש מקום \u0005לגזור שמא יבוא להרבות]\u0006 \u0003בשביל ישראל\u0004 אף שלא אמר במפורש שנתכוון לעשות עבורו. ושואלים: \u0003ו\u0004היתר ההליכה ב\u0003כבש למה לי?\u0004 ומשיבים: את ה\u0003מעשה\u0004 של \u0003רבן גמליאל וזקנים קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ללמדנו שכך נהגו למעשה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003גוי שליקט עשבים\u0004 בשבת בשביל עצמו — \u0003מאכיל אחריו ישראל, ואם בשביל ישראל\u0004 ליקטם — \u0003אסור. מילא מים להשקות\u0004 את \u0003בהמתו\u0004 — \u0003משקה אחריו ישראל, ואם בשביל ישראל\u0004 מילא — \u0003אסור. במה דברים אמורים\u0004 שאם עשה כן לצורך עצמו מותר לישראל \u0003— כשאין\u0004 הגוי \u0003מכירו, אבל\u0004 כאשר הגוי \u0003מכירו\u0004 — \u0003אסור,\u0004 שבודאי נתכוון גם לתועלת חבירו הישראל.","ומקשים: \u0003איני\u0004 \u0005[וכי כן הוא]?!\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב הונא\u0004 שכך \u0003אמר ר' חנינא: מעמיד אדם בהמתו על גבי עשבים בשבת\u0004 אף שהם מחוברים לקרקע, ואינו חושש שמא יבוא לסייע לבהמה ולתלוש. \u0003אבל לא\u0004 מעמידה \u0003על גבי מוקצה בשבת,\u0004 שיש לחשוש שמא יטול בידו מן המוקצה. ואולם הלא העשבים שתלש הגוי לעצמו אף הם מוקצה, ומדוע מותר להאכילם לבהמתו. ומתרצים: אכן לא הותר להעמיד את בהמתו ממש על העשבים שתלש הגוי, אלא \u0003רק באופן דקאים\u0004 \u0005[שעומד]\u0006 \u0003לה באפה\u0004 \u0005[בפניה],\u0006 \u0003ואזלא\u0004 \u0005[והולכת]\u0006 \u0003היא\u0004 מעצמה \u0003ואכלה\u0004 \u0005[ואוכלת].\u0006","שנינו מקודם ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003במה דברים אמורים\u0004 שהותר לישראל להשתמש במה שעשה הגוי לצורך עצמו בשבת — כ\u0003שאין\u0004 הגוי \u0003מכירו\u0004 לאותו ישראל, \u0003אבל\u0004 כאשר \u0003מכירו\u0004 — \u0003אסור.\u0004 ומקשים: \u0003הא\u0004 \u0005[\u0006ו\u0005הרי]\u0006 אותו מעשה של \u0003רבן גמליאל\u0004 בספינה \u0003מכירו הוה\u0004 \u0005[היה],\u0006 שהרי נסע עמו בספינה! \u0003אמר אביי: שלא בפניו הוה\u0004 \u0005[היה\u0006 מעשה\u0005],\u0006 וכיון שלא ראה אותו ודאי נתכוין הגוי רק לצורך עצמו. \u0003רבא אמר: אפילו תימא\u0004 \u0005[תאמר,\u0006 תפרש\u0005]\u0006 שהיה זה \u0003בפניו,\u0004 ואולם אין להקפיד בכך, כיון ש\u0003נר לאחד נר למאה,\u0004 וכן כבש, כיון שעשאו לצורך עצמו אינו צריך להוסיף בו מאומה כשזה גם לצורך אחרים.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דברי רבא ממה ששנינו בתוספתא, \u0003אמר להן רבן גמליאל: הואיל ושלא בפנינו עשאו\u0004 — \u0003נרד בו.\u0004 נמצא שהנימוק הוא שלא היה בפניהם, ושלא כדברי רבא! ודוחים: \u0003אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]\u0006 כך, אמר להן \u0003רבן גמליאל: הואיל ועשאו נרד בו.\u0004","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ברייתא אחרת שמתוכה ניתן להכריע במחלוקת אביי ורבא. ששנינו: \u0003עיר שישראל וגוים דרין בתוכה, והיתה בה מרחץ המרחצת בשבת, אם רוב גוים\u0004 בעיר — \u0003מותר לרחוץ בה\u0004 במרחץ \u0003מיד\u0004 לאחר צאת השבת, שהרי הוסק המרחץ בשבת לצורך הגויים. \u0003אם רוב ישראל\u0004 בעיר — \u0003ימתין\u0004 במוצאי שבת \u0003בכדי\u0004 זמן \u0003שיחמו חמין,\u0004 כדי שלא יימצא מרוויח ממלאכת שבת. נמצא שאפילו שלא בפניו יש לחוש שעושה לטובת ישראל! ודוחים: \u0003התם, כי מחממי\u0004 \u0005[שם\u0006 בברייתא, \u0005כאשר מחממים]\u0006 — \u0003אדעתא דרובא מחממי\u0004 \u0005[על דעת רוב\u0006 בני העיר \u0005מחממים],\u0006 ולפי הרוב קובע בעל המרחץ את זמני החימום.","ועוד \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 הוכחה אחרת ממה ששנינו בברייתא: \u0003נר הדלוק במסיבה\u0004 שיושבים בה כמה אנשים, \u0003אם רוב גוים\u0004 במסיבה זו — \u0003מותר\u0004 גם לישראל \u0003להשתמש לאורה,\u0004 ו\u0003אם רוב ישראל\u0004 — \u0003אסור,\u0004 שודאי הדליקו את הנר בשבילם. \u0003מחצה על מחצה\u0004 — \u0003אסור.\u0004 והרי מאחר שהם יושבים במסיבה אחת ודאי מכיר הגוי את הישראל, ומדוע אם כן כשהגויים הם הרוב מותר לישראל להשתמש באור הנר? ודוחים: \u0003התם נמי, כי מדלקי\u0004 \u0005[שם גם כן, כאשר מדליקים]\u0006 —"],["\u0003אדעתא דרובא מדלקי\u0004 \u0005[על דעת הרוב מדליקים],\u0006 ולכן כאשר הגוים הם הרוב — מותר.","ומסופר: \u0003שמואל איקלע לבי\u0004 \u0005[הזדמן לבית]\u0006 \u0003אבין תורן. אתא ההוא גוי אדליק שרגא\u0004 \u0005[בא גוי אחד\u0006 ו\u0005הדליק נר].\u0006 \u0003אהדרינהו\u0004 \u0005[החזיר]\u0006 \u0003שמואל לאפיה\u0004 \u0005[את פניו]\u0006 לצד אחר שלא להנות מנר זה. \u0003כיון דחזא דאייתי\u0004 \u0005[שראה\u0006 שמואל \u0005שהביא]\u0006 הגוי \u0003שטר וקא קרי\u0004 \u0005[וקרא\u0006 בו\u0005]\u0006 \u0003אמר: אדעתא דנפשיה\u0004 \u0005[על דעת\u0006 ולצורך \u0005עצמו]\u0006 \u0003הוא דאדליק\u0004 \u0005[שהדליק].\u0006 \u0003אהדרינהו איהו לאפיה גבי שרגא\u0004 \u0005[והחזיר הוא פניו אצל,\u0006 לעבר, \u0005הנר].\u0006","","\u0003כל הכלים ניטלין בשבת, ודלתותיהן\u0004 של אותם כלים \u0003עמהן, אף על פי שנתפרקו בשבת. שאינן דומין\u0004 דלתות הכלים \u0003לדלתות הבית\u0004 שאסור להשתמש בהן בשבת אם נתפרקו מן הפתח, \u0003לפי ש\u0004דלתות הבית \u0003אינן מן המוכן\u0004 מבעוד יום. שהדלת עצמה כשהיא מפורקת אינה ברת שימוש ולכך אינה נחשבת ככלי, אבל הכלים על כל חלקיהם מוכנים לשימוש, ובכלל זה דלתותיהן.","וכן \u0003נוטל אדם קורנס\u0004 המשמש למלאכה שאסור לעשותה בשבת, כדי \u0003לפצע\u0004 (לפצח) \u0003בו את האגוזין.\u0004 וכן נוטל \u0003קרדום,\u0004 שהוא כלי המשמש לחטיבת עצים, כדי \u0003לחתוך בו את הדבילה\u0004 (גוש גדול של תאנים מיובשות מחוברות יחד). וכן \u0003מגירה\u0004 (משור), כדי \u0003לגור\u0004 (לחתוך) \u0003בה את הגבינה.\u0004 וכן \u0003מגריפה,\u0004 כדי \u0003לגרוף בה את הגרוגרות.\u0004","וכן נוטל \u0003את הרחת ואת המלגז\u0004 שהם גדולים מאד ונועדים לטיפול בתבואה שבגורן — כדי \u0003לתת עליו לקטן\u0004 מזונו, כדי לשעשעו על ידי כך. וכן מותר לקחת \u0003את הכוש\u0004 (פלך) \u0003ואת הכרכר\u0004 המשמשים לאריגה, כדי \u0003לתחוב בו\u0004 בתוך מאכלים כעין מזלג. ומותר לקחת \u0003מחט של יד\u0004 (מחט בגדים רגילה), כדי \u0003ליטול בו את הקוץ. ו\u0004מחט \u0003של סקאים\u0004 (תופרי שקים) שהיא גסה יותר, כדי \u0003לפתוח בו את הדלת,\u0004 כאשר אין בידו המפתח הרגיל.","שנינו במשנה ש\u0003כל הכלים ניטלין, ואף על פי שנתפרקו בשבת,\u0004 והאם נלמד מכך: שנתפרקו בשבת, \u0003ולא מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר אם נתפרקו \u0003בחול,\u0004 שודאי מותרים בטלטל בשבת.","ואולם \u0003אדרבה\u0004 (להיפך), אם נתפרקו \u0003בשבת\u0004 אפשר לומר ש\u0003מוכנין\u0004 היו אותם חלקי הכלים בכניסת השבת \u0003על גבי\u0004 (משום) \u0003אביהן,\u0004 כלומר, משום הכלי השלם. אבל אם נתפרקו \u0003בחול\u0004 הרי נמצא שכניסת השבת כבר \u0003אין\u0004 הם \u0003מוכנין\u0004 לשימוש \u0003על גבי אביהן!\u0004","\u0003אמר אביי, הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך יש לפרש\u0005]:\u0006 \u0003כל הכלים ניטלין בשבת ודלתותיהן עמהן.\u0004 ו\u0003אף על פי שנתפרקו בחול\u0004 — \u0003ניטלין בשבת.\u0004 \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003דלת של שידה ושל תיבה ושל מגדל\u0004 (ארון) — \u0003נוטלין\u0004 ומורידים אותן מציריהן בשבת \u0003אבל לא מחזירין\u0004 אותן למקומן. \u0003ו\u0004דלת \u0003של לול של תרנגולים\u0004 — \u0003לא נוטלין ולא מחזירין.\u0004","","ומעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 בענין \u0003של לול של תרנגולים, קסבר\u0004 \u0005[סבור הוא]:\u0006 כי \u0003כיון דמחברי בארעא\u0004 \u0005[שמחובר\u0006 הלול \u0005בארץ]\u0006 \u0003יש בנין בקרקע\u0004 ו\u0003יש סתירה בקרקע,\u0004 והמוריד דלת או מחזירה הרי זה כבונה. \u0003אלא\u0004 לענין דלת \u0003של שידה ושל תיבה ושל מגדל, מאי קסבר\u0004 \u0005[מה סבור הוא]?\u0006","\u0003אי קסבר\u0004 \u0005[אם סבור הוא]\u0006 כי \u0003יש בנין בכלים\u0004 — הלא גם \u0003יש סתירה בכלים\u0004 ואסור להסיר את הדלת, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003אין סתירה בכלים\u0004 ומותרת הדלת בהורדה, הלא גם \u0003אין בנין בכלים,\u0004 ומדוע אם כן אסור להחזירן?","\u0003אמר אביי: לעולם קסבר\u0004 \u0005[סבור הוא]\u0006 כי \u0003יש בנין בכלים ויש סתירה בכלים\u0004 ויש לתקן את הגירסה ולא לשנות \"נוטלין\", אלא ללמוד כך: \"דלת של שידה ושל תיבה \u0003ושניטלו\u0004 כבר\" \u0003קאמר\u0004 \u0005[אמר]\u0006 והן שאסור להחזירן למקומן. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: שתי תשובות בדבר\u0004 לדחות דבריך. \u0003חדא\u0004 \u0005[אחת],\u0006 שבמפורש \u0003\"נוטלין\" קתני\u0004 \u0005[שנינו],\u0006 ומשמע — לכתחילה! \u0003ועוד: מאי\u0004 \u0005[מה\u0006 איך תפרש\u0005]\u0006 \u0003\"אבל לא מחזירין\",\u0004 מה מובן המלה \"אבל\" כאן? \u0003אלא אמר רבא\u0004 כי \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 אותו תנא כי \u0003אין בנין בכלים ואין סתירה בכלים, ו\u0004משום מה אסר להחזיר דלת — \u0003גזירה שמא יתקע\u0004 בדוחק וכדרך מלאכה גמורה, ונמצא שעבר משום מכה בפטיש שהוא עשיית גמר מלאכה.","","שנינו במשנה ש\u0003נוטל אדם קורנס\u0004 בשבת כדי לפצע בו אגוזים. \u0003אמר רב יהודה:\u0004 מדובר כאן ב\u0003קורנס של אגוזין\u0004 כדי \u0003לפצע בו את האגוזין, אבל של נפחין\u0004 — \u0003לא.\u0004","ו\u0003קסבר\u0004 \u0005[סבור]\u0006 אותו תנא כי \u0003דבר שמלאכתו\u0004 כרגיל \u0003ל\u0004מלאכה שיש בה \u0003איסור\u0004 בשבת, \u0003אפילו לצורך\u0004 שימוש ב\u0003גופו\u0004 להיתר — \u0003אסור.\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה: אלא מעתה, סיפא, דקתני\u0004 \u0005[הסוף\u0006 של המשנה \u0005ששנינו]:\u0006 \u0003ואת הרחת ואת המלגז לתת עליו לקטן\u0004 מזונו, \u0003רחת ומלגז מי מייחדי ליה\u0004 \u0005[האם מיוחדים\u0006 הם \u0005לו]\u0006 \u0003ל\u0004שימושו של ה\u0003קטן?! אלא אמר רבה:\u0004 יש לפרש שמדובר ב\u0003קורנס של נפחין\u0004 שמותר לו ליטלו בשבת כדי \u0003לפצע בו\u0004 את \u0003האגוזין,\u0004 ו\u0003קסבר\u0004 \u0005[סבור]\u0006 אותו תנא","",""],["\u0003דבר שמלאכתו לאיסור לצורך גופו\u0004 — \u0003מותר.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי לרבה\u0004 ממה ששנינו בתוספתא: \u0003מדוכה, אם יש בה\u0004 עדיין \u0003שום\u0004 — \u0003מטלטלין אותה\u0004 בשבת, \u0003ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אין מטלטלין אותה.\u0004 נמצא שאסור להשתמש כלל במדוכה אף למלאכת היתר, כיון שעיקר מלאכתה לאיסור.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הא מני\u0004 \u0005[\u0006תוספתא \u0005זו\u0006 של \u0005מי היא]\u0006 — כדעת \u0003ר' נחמיה היא,\u0004 ש\u0003אמר: אין כלי ניטל\u0004 בשבת \u0003אלא לצורך תשמישו\u0004 המיוחד לו, ולא לכל שימוש אחר.","ועוד \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 אביי: למדנו במשנה ש\u0003בית שמאי אומרים: אין נוטלין את העלי\u0004 הגדול של מכתשת שמלאכתו לאיסור כדי \u0003לקצב\u0004 (לחתוך) \u0003עליו בשר\u0004 ביום טוב. \u0003ובית הלל מתירין\u0004 משום שמחת החג. \u0003ושוין\u0004 (הכל מסכימים) \u0003שאם קצב עליו בשר\u0004 לצורך החג \u0003ש\u0004שוב \u0003אסור לטלטלו,\u0004 לפי שאין בו עוד צורך יום טוב. הרי שדבר שמלאכתו לאיסור אסור בטלטול אף לצורך היתר!","\u0003סבר לשנויי ליה\u0004 \u0005[סבור היה\u0006 רבה בתחילה \u0005לתרץ לו]\u0006 שמשנה זו \u0003כ\u0004שיטת \u0003ר' נחמיה\u0004 שאין כלי מיטלטל אלא לצורך המלאכה המיוחדת לו, ואולם \u0003כיון\u0004 ש\u0003שמעה להא\u0004 \u0005[ל\u0006הלכה \u0005זו]\u0006 ש\u0003אמר רב חיננא בר שלמיא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: הכל מודים בסיכי זיירי ומזורי\u0004 \u0005[ביתדות הכובסים, במכבשים, ובמחבטי בגדים\u0006 (ערוך)\u0005]\u0006 ש\u0003כיון דקפיד עלייהו\u0004 \u0005[ש\u0006הוא \u0005מקפיד עליהם]\u0006 שלא יתקלקלו, והריהו \u0003מייחד להו\u0004 \u0005[להם]\u0006 \u0003מקום,\u0004 ואינו מטלטלם לכל צורך אחר, ולכך הריהם אסורים בטלטול לכל הדעות, \u0003הני נמי\u0004 \u0005[אלה גם כן]\u0006 העלי והמדוכה \u0003המיוחדים למלאכה מדוייקת מייחד להו\u0004 \u0005[להם]\u0006 \u0003מקום\u0004 ולכך הריהם אסורים בטלטול.","בנושא דומה \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים אחרים. \u0003ר' חייא בר אבא אמר\u0004 בשם \u0003ר' יוחנן:\u0004 קורנס שאמרו כאן \u0003קורנס של זהבים\u0004 (צורפי זהב) \u0003שנינו,\u0004 שאף שמקפיד עליו הצורף שישאר חלק ומדוייק ומשתדל לא לעשות בו מלאכות שאינם לצורך ייעודו, מכל מקום לא נאסר בטלטול לצורך מלאכת היתר. ו\u0003רב שמן בר אבא אמר: קורנס של בשמים שנינו\u0004 שמשתמשים בו לשחיקת בשמים.","ומפרשים: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שמותר לפצע בשבת אגוזים בקורנס של \u0003בשמים\u0004 — \u0003כל שכן\u0004 שמותר ב\u0003של זהבים.\u0004 ואולם \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שמותר ב\u0003של זהבים, אבל\u0004 לדעתו בשל \u0003בשמים קפיד עלייהו\u0004 \u0005[מקפיד עליהם]\u0006 שאם משתמשים בהם לצורך אחר קולט הקורנס ריח ויקלקל את הבשמים.","\u0003ו\u0004עוד שנינו במשנה שמטלטלים \u0003את הכוש ואת הכרכר\u0004 לתחוב בהם. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003פגה\u0004 (תאנה בלתי בשלה) \u0003שטמנה בתבן\u0004 שתתבשל \u0003ו\u0004כן \u0003חררה\u0004 (עוגה) \u0003שטמנה בגחלים\u0004 להתחמם, \u0003אם מגולה מקצתה\u0004 — \u0003מותר לטלטלה\u0004 בשבת, \u0003ואם לאו\u0004 \u0005[לא]\u0006 אלא שמכוסה כולה — \u0003אסור לטלטלה,\u0004 שמא יטלטל אגב כך את התבן או הגחלים שהם מוקצה ואסור אף לגרום לטלטול מוקצה.","\u0003ר' אלעזר בן תדאי אומר: תוחבין בכוש או בכרכר,\u0004 כלומר את הכוש או הכרכר בפגה וכך מוציאים אותה ממקומה, \u0003והן\u0004 התבן או הגחלים \u0003מנערות מאיליהם. אמר רב נחמן: הלכה\u0004 בענין זה \u0003כר' אלעזר בן תדאי!\u0004","ושואלים: \u0003למימרא דסבר\u0004 \u0005[האם נאמר שסבור]\u0006 \u0003רב נחמן\u0004 ש\u0003טלטול מן הצד,\u0004 כלומר, טלטול שאיננו כדרכו ממש, ואיננו נעשה במישרין, \u0003לא שמיה\u0004 \u0005[אין שמו,\u0006 אינו נחשב\u0005]\u0006 ל\u0003טלטול\u0004 ומותר בשבת? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב נחמן: האי פוגלא\u0004 \u0005[צנון זה]\u0006 שהטמינו בעפר לשמירה, אם היה זה \u0003מלמעלה למטה,\u0004 כלומר, שחלקו הרחב למעלה וחלקו הצר למטה — \u0003שרי\u0004 \u0005[מותר]\u0006 להוציאו מהעפר. אבל \u0003ממטה למעלה,\u0004 שהיה חלקו הרחב מונח למטה — \u0003אסיר\u0004 \u0005[אסור]\u0006 משום שמטלטל עפר, אף שטלטול זה הוא מן הצד בלבד, ונמצא שאסר רב נחמן טלטול מן הצד! ומשיבים: \u0003הדר ביה\u0004 \u0005[חזר בו]\u0006 \u0003רב נחמן מ\u0004ההלכה \u0003ההיא\u0004 בענין הצנון.","שנינו במשנה ש\u0003מחט של יד\u0004 מותרת בטלטול בשבת כדי \u0003ליטול בה\u0004 את הקוץ. \u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003רבא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבה לרב יוסף\u0004 שאלה זו: \u0003ילמדנו רבינו, מחט שניטל חררה\u0004 (החור שבה) \u0003או עוקצה\u0004 (חודה), \u0003מהו\u0004 הדין, האם מותר לטלטלה בשבת?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: כבר \u0003תניתוה\u0004 \u0005[שניתם אותה,\u0006 את התשובה\u0005]\u0006 שכן שנינו במשנתנו: \u0003מחט של יד\u0004 מיטלטלת בשבת כדי \u0003ליטול בה את הקוץ,\u0004 ויש להעיר: \u0003וכי מה איכפת ליה\u0004 \u0005[לו]\u0006 \u0003לקוץ\u0004 התחוב בבשרו \u0003בין\u0004 מחט \u0003נקובה לבין שאינה נקובה?\u0004 וכיון שראויה המחט לצורך זה הריהי מותרת לטלטול.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ממה ששנינו במשנה: \u0003מחט\u0004 טמאה \u0003שניטל\u0004 ממנה \u0003חררה או עוקצה\u0004 — \u0003טהורה,\u0004 משום שבטלה מתורת כלי, וכיון שאיננה כלי עוד, מדוע תהיה מותרת בטלטול?","\u0003אמר אביי:\u0004 וכי מדין \u0003טומאה\u0004 על דין \u0003שבת קרמית\u0004 \u0005[אתה מקשה]?\u0006 והלא לענין \u0003טומאה כלי מעשה בעינן\u0004 \u0005[צריכים אנו]\u0006 כדי לטמאו או להעמידו בטומאתו, ומה שאינו כלי מעשה גמור — נטהר מטומאתו, ואילו \u0003לענין שבת מידי דחזי בעינן\u0004 \u0005[דבר הראוי\u0006 לשימוש \u0005צריכים אנו],\u0006 \u0003והא נמי חזיא למשקלא\u0004 \u0005[וזו גם כן ראויה ליטול]\u0006 \u0003בה\u0004 את ה\u0003קוץ,\u0004 ונחשבת אם כן לענין זה ככלי וממילא מותרת היא בטלטול.","\u0003אמר רבא: מאן דקמותיב, שפיר קמותיב\u0004 \u0005[מי שמקשה\u0006 בענין זה \u0005יפה מקשה],\u0006 כיון \u0003שלענין טומאה לאו מנא\u0004 \u0005[לא כלי]\u0006 \u0003הוא\u0004 נחשב — \u0003לענין שבת נמי לאו מנא\u0004 \u0005[לא כלי]\u0006 \u0003הוא,\u0004 ודבר שאינו כלי הריהן מוקצה בשבת.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על רבא ממה ששנינו: \u0003מחט בין\u0004 שהיא \u0003נקובה בין שאינה נקובה\u0004 — \u0003מותר לטלטלה בשבת. ולא אמרו\u0004 שיש דין מיוחד במחט \u0003נקובה אלא לענין טומאה בלבד!\u0004","\u0003תרגמא\u0004 \u0005[הסבירה]\u0006 \u0003אביי אליבא\u0004 \u0005[לפי שיטת]\u0006 \u0003רבא:\u0004 במשנה זו \u0003בגולמי עסקינן\u0004 \u0005[ב\u0006מחטים \u0005גולמיות עוסקים אנו],\u0006 \u0003זימנין דמימלך עלייהו, ומשוי להו מנא\u0004 \u0005[\u0006ש\u0005פעמים שנמלך עליהן, ועושה אותן כלי]\u0006 לשימושים אחרים בלא לנקוב את חורן כלל. \u0003אבל היכא\u0004 \u0005[במקום]\u0006 ש\u0003ניטל חררה או עוקצה\u0004 של מחט שלמה — בטלה מתורת כלי, שכן \u0003אדם זורקה לבין גרוטאות.\u0004","לענין ההיתר ל\u0003אסובי ינוקא\u0004 \u0005[ליישר את\u0006 אברי \u0005התינוק]\u0006 עם לידתו, כשצריך ליישרם, \u0003רב נחמן אסיר\u0004 \u0005[אוסר]\u0006 לעשות זאת בשבת, שהוא חושש משום איסור מתקן, \u0003ורב ששת שרי\u0004 \u0005[התיר].\u0006 \u0003אמר רב נחמן: מנא אמינא לה\u0004 \u0005[מנין אומר,\u0006 לומד \u0005אני אותה\u0006 הלכה\u0005]\u0006 — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו במשנה]:\u0006 \u0003אין עושין\u0004"],["\u0003אפיקטויזין\u0004 (סם הקאה) \u0003בשבת.\u0004 והרי שאסרו בשבת דברים שיש בהם משום תיקון הגוף! \u0003ורב ששת\u0004 מסביר: \u0003התם\u0004 \u0005[שם]\u0006 בענין סם הקאה — \u0003לאו אורחיה\u0004 \u0005[אין זו דרכו]\u0006 לשתותו, והרי זה ודאי לרפואה, ואולם \u0003הכא\u0004 \u0005[כאן]\u0006 ביישור התינוק — \u0003אורחיה\u0004 \u0005[\u0006זו \u0005דרכו]\u0006 ואין זו רפואה.","\u0003אמר רב ששת: מנא אמינא לה\u0004 \u0005[מנין אומר,\u0006 לומד \u0005אני אותה\u0006 הלכה\u0005]\u0006 — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו במשנה]:\u0006 \u0003מחט של יד\u0004 — מותרת בטלטול בשבת \u0003ליטול בה את הקוץ,\u0004 ואין אנו חוששים משום התיקון שבדבר, ונמצא אם כן שלא כל דבר של ריפוי נאסר! \u0003ורב נחמן\u0004 אומר: אין זו ראיה, כי \u0003התם\u0004 \u0005[שם]\u0006 בקוץ — \u0003פקיד\u0004 \u0005[שמור\u0006 הוא\u0005]\u0006 במקומו ואינו חלק מן הגוף, ואין בהוצאת גוף זר משום תיקון ושינוי יסודי בו, ואולם \u0003הכא\u0004 \u0005[כאן]\u0006 ביישור האיברים — \u0003לא פקיד\u0004 \u0005[אינו שמור]\u0006 אלא עושה בכך מלאכת תיקון וריפוי.","\u0003קנה של זיתים\u0004 שהוא קנה שמשתמשים בו כדי להפוך את הזיתים שבערימה, \u0003אם יש קשר בראשו\u0004 כעין פקק — הריהו \u0003מקבל טומאה\u0004 משום כלי, \u0003ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אין\u0004 הוא \u0003מקבל טומאה,\u0004 שאינו כלי. \u0003בין כך ובין כך\u0004 — \u0003ניטל בשבת\u0004 לצורך מלאכת היתר.","ושואלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 יקבל קנה זה טומאה? והלא מ\u0003פשוטי כלי עץ הוא,\u0004 שאין בו בית קיבול, \u0003ו\u0004כלל בידינו ש\u0003פשוטי כלי עץ אינן מקבלין טומאה, מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003שק בעינן\u0004 \u0005[אנו צריכים],\u0006 שלמדנו דיני טומאה משק המוזכר בתורה כדוגמה, ואם אין בו בית קיבול אינו דומה לשק האמור בתורה ואינו מקבל טומאה. כדי להסביר זאת מביאים את מה ש\u0003תנא משמיה\u0004 \u0005[\u0006ש\u0005שנה החכם\u0006 בברייתא \u0005משמו]\u0006 של \u0003ר' נחמיה: בשעה שמהפך בזיתים הופכו ורואה בו,\u0004 שהרי יש חלל קטן בקצה הקנה ליד הקשר, והופך ורואה אם התמלא קשר זה בשמן וראויה כבר הערימה לכבישה. וכיון שיש בו כעין כלי קיבול קטן הרי הוא ראוי לקבל טומאה בשל כך.","\u0003ר' יוסי אומר: כל הכלים ניטלין\u0004 בשבת \u0003חוץ מן המסר\u0004 (משור) \u0003הגדול ויתד\u0004 (להב) \u0003של מחרישה,\u0004 שכיון שדרוש שיהיו חדים ומוכנים למלאכתם וחוששים להם שמא יפגמו, אדם מקצה אותם מדעתו, ואינו מוכן להשתמש בהם למלאכה אחרת.","\u0003אמר רב נחמן: האי אוכלא דקצרי\u0004 \u0005[מזלף הכובסים]\u0006 — \u0003כיתד של מחרישה דמיא\u0004 \u0005[\u0006הוא \u0005נחשב]\u0006 ואסור לטלטלו בשבת שכן חוששים לו שמא יתקלקל ומקצים אותו משימוש.","\u0003אמר אביי: חרבא דאושכפי\u0004 \u0005[סכין הסנדלרים]\u0006 \u0003וסכינא דאשכבתא\u0004 \u0005[וסכין השוחטים]\u0006 \u0003וחצינא דנגרי\u0004 \u0005[ומעצד הנגרים]\u0006 — \u0003כיתד של מחרישה דמי\u0004 \u0005[\u0006הם \u0005נחשבים],\u0006 שבעליהם מקפידים עליהם שלא יפגמו, ומקצים אותם מכל שימוש.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003בראשונה היו אומרים\u0004 ש\u0003שלשה כלים\u0004 בלבד \u0003ניטלין בשבת,\u0004 והם: \u0003מקצוע של דבילה\u0004 המיוחד לחתוך בו את התאנים היבשות, \u0003וזוהמא ליסטרן\u0004 (כף ומזלג יחד) (גאונים) \u0003של קדרה, וסכין קטנה שעל גבי שלחן,\u0004 שכל אלה נחוצים לאוכל ומשתמשים בהן, אבל אסור לטלטל כל כלי אחר. ואולם במשך הדורות, כשראו שישראל מדקדקים באיסורי שבת, \u0003התירו, וחזרו והתירו, וחזרו והתירו, עד שאמרו\u0004 במשנה אחרונה: \u0003כל הכלים ניטלין בשבת, חוץ מן\u0004 ה\u0003מסר הגדול ויתד של מחרישה.\u0004","ומעתה דנים בפירושה של תוספתא זו: \u0003מאי\u0004 \u0005[מהו\u0006 בדיוק\u0005]\u0006 \u0003התירו, וחזרו והתירו, וחזרו והתירו,\u0004 מה היו שלבי ההיתר?","\u0003אמר אביי: התירו\u0004 מתחילה \u0003דבר שמלאכתו להיתר\u0004 להשתמש בו \u0003לצורך גופו,\u0004 למלאכה מותרת. \u0003וחזרו והתירו דבר שמלאכתו להיתר\u0004 לטלטל אותו \u0003לצורך מקומו\u0004 אם רוצה לשבת או להשתמש באותו מקום, \u0003וחזרו והתירו דבר שמלאכתו לאיסור, לצורך גופו\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 ואולם \u0003לצורך מקומו\u0004 — \u0003לא. ועדיין בידו אחת\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 התירו לטלטל, אבל \u0003בשתי ידיו\u0004 — \u0003לא,\u0004 כדי לעשות היכר בדבר, שיש מקצת איסור בטלטול, \u0003עד שאמרו\u0004 היתר גמור: \u0003כל הכלים ניטלין בשבת, ואפילו בשתי ידים.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: מכדי\u0004 \u0005[הרי]\u0006 \u0003\"התירו\" קתני\u0004 \u0005[שנינו]\u0006 ו\u0003מה לי לצורך גופו,\u0004 ו\u0003מה לי לצורך מקומו,\u0004 ולמה לחלק בדבר שאינו מפורש? \u0003אלא אמר רבא\u0004 כך יש לפרש: \u0003התירו דבר שמלאכתו להיתר\u0004 מתחילה \u0003בין לצורך גופו ובין לצורך מקומו, וחזרו והתירו\u0004 לטלטלו אפילו \u0003מחמה לצל\u0004 כשאינו זקוק למקום הכלי או לשימוש בו אלא רוצה לשמור את הכלי עצמו שלא יתקלקל בחמה וכיוצא בזה. \u0003וחזרו והתירו דבר שמלאכתו לאיסור, לצורך גופו ולצורך מקומו\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 \u0003מחמה לצל\u0004 — \u0003לא. ועדיין\u0004 אם החפץ מיטלטל על ידי \u0003אדם אחד\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003בשני בני אדם\u0004 — \u0003לא, עד שאמרו כל הכלים ניטלין בשבת אפילו\u0004 היו כבדים כמשא \u0003שני בני אדם.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי\u0004 ממה ששנינו: \u0003מדוכה, אם יש בה שום\u0004 — \u0003מטלטלין אותה\u0004 בשבת, \u0003ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אין מטלטלין אותה.\u0004 ולשיטת רבא שהכל הותר בטלטול, מדוע אין מטלטלים אותה? ענה לו: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — בטלטול המדוכה \u0003מחמה לצל\u0004 וכיוצא בזה. ועוד \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ממה ששנינו: \u0003ושוין\u0004 בית שמאי ובית הלל \u0003ש\u0004אם כבר \u0003קצב\u0004 (חתך) \u0003עליו,\u0004 על העלי \u0003בשר\u0004 די צורכו \u0003ליום טוב שאסור לטלטלו,\u0004 והרי לדעת רבא הכל מותר בטלטול! ענה לו: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בטלטול \u0003מחמה לצל.\u0004","\u0003אמר ר' חנינא: בימי נחמיה בן חכליה נשנית משנה זו,\u0004 ובאותם הימים החמירו וגזרו הרבה באיסורי שבת, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"בימים ההמה ראיתי ביהודה דרכים גתות בשבת ומביאים הערמות\u0004 ועומסים על החמורים ואף יין ענבים ותאנים וכל משא ומביאים ירושלים ביום השבת ואעיד ביום מיכרם ציד\" \u0005(נחמיה יג, טו)\u0006, וכיון שזלזלו בקדושת השבת עשה נחמיה כמה וכמה תקנות להחמיר בכל דיני השבת, כדי לחנך את העם לשמירת השבת.","\u0003אמר ר' אלעזר:\u0004 המשניות בענין \u0003קנין, ומקלות, גלוסטרא\u0004 (קצהו העב של הנגר, שהוא יתד המיועד לנעילת הדלת), \u0003ומדוכה\u0004 — \u0003כולן קודם התרת\u0004 טלטול \u0003כלים נשנו\u0004, ונאמרו באותם דורות שעדיין אסרו לטלטל את רוב הכלים בשבת והתירו רק כלים מעטים שמלאכתם להיתר.","ומעתה מפרטים אותן עניינים כפי שנשנו במשניות השונות: \u0003קנין,\u0004 שבבית המקדש היו שמים בין לחם ללחם בלחם הפנים קנים עשויים זהב להחזיק את הלחמים ולאווררם, ובאותם דורות אסרו לטלטל את הקנים כיון שחששו בהם משום מוקצה. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003לא סידור הקנין ולא נטילתן דוחה את השבת.\u0004","ומקור לענין ה\u0003מקלות\u0004 — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מקלות דקין חלקין היו שם,\u0004 בבית המקדש, \u0003ו\u0004בכל ערב פסח \u0003מניחו\u0004 את המקל \u0003על כתפו ועל כתף חבירו, ותולה\u0004 בו את קרבן הפסח \u0003ומפשיט\u0004 את עורו. ו\u0003אמר ר' אלעזר:\u0004 ביום \u0003ארבעה עשר\u0004 בניסן שהוא יום הקרבת קרבן פסח \u0003שחל להיות בשבת\u0004 היו עושים שינוי ולא השתמשו אף במקלות אלה, אלא \u0003מניח\u0004"],["\u0003ידו על כתף חבירו ויד חבירו על כתיפו, ותולה ומפשיט.\u0004","ומקור לענין \u0003גלוסטרא\u0004 — \u0003דתנן: נגר\u0004 (יתד שמכניסים בדלת כדי לנעלה) \u0003שיש בראשו גלוסטרא\u0004 (קצה מעובה), \u0003ר' יהושע אומר: שומטה מן פתח זה ותולה בחבירו בשבת,\u0004 אבל אינו מטלטל אותה בידים ממש, מחשש מוקצה. ואילו \u0003ר' טרפון אומר: הרי הוא ככל\u0004 שאר \u0003הכלים ומיטלטל בחצר.\u0004","ו\u0003מדוכה\u0004 — \u0003הא דאמרן\u0004 \u0005[זו שאמרנו].\u0006 \u0003אמר רבה: ממאי\u0004 \u0005[ממה\u0006 אתה מסיק שהדבר כן\u0005],\u0006 \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003לעולם אימא\u0004 \u0005[\u0006יכול \u0005אני לומר]\u0006 \u0003לך\u0004 כי \u0003לאחר התרת כלים נשנו\u0004 משניות אלה, ויש להן ביאור אפילו לפי שיטת אחרונים. כיצד: \u0003קנים\u0004 אלה של לחם הפנים \u0003טעמא מאי\u0004 \u0005[מה טעם]\u0006 משתמשים בהם — \u0003משום\u0004 חשש \u0003איעפושי\u0004 \u0005[לעיפוש],\u0006 \u0003בהאי פורתא לא מיעפש\u0004 \u0005[במעט\u0006 זמן זה עד ליציאת השבת \u0005אינו מתעפש].\u0006 \u0003מקלות\u0004 מדוע לא התירו להשתמש בהם בערב פסח, משום ש\u0003אפשר\u0004 לעשות את מלאכת ההפשטה \u0003כ\u0004דרך שאמר \u0003ר' אלעזר,\u0004 וכיון שכך אין צורך להשתמש בדבר שיש בו מחשש מוקצה.","ואילו \u0003גלוסטרא\u0004 מדוע לא התירו להשתמש בהם בערב פסח — יש להבין זאת \u0003כ\u0004דברי \u0003ר' ינאי,\u0004 ש\u0003אמר ר' ינאי: בחצר שאינה מעורבת עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003ר' יהושע סבר\u0004 \u0005[סבור]\u0006 כי \u0003תוך הפתח כלפנים דמי\u0004 \u0005[\u0006הוא \u0005נחשב]\u0006 \u0003וקמטלטל מנא\u0004 \u0005[ו\u0006נמצא ש\u0005הוא מטלטל כלי]\u0006 של ה\u0003בתים בחצר,\u0004 והרי לא עירבו בחצר ואסור להוציא חפץ מן הבית לחצר. \u0003ור' טרפון סבר\u0004 \u0005[סבור]\u0006 כי \u0003תוך הפתח כלחוץ דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 \u0003ו\u0004נמצא שאותו נגר והגלוסטרא שבראשו \u0003מנא\u0004 של ה\u0003חצר\u0004 הוא ו\u0003בחצר קא\u0004 \u0005[הוא]\u0006 ש\u0003מטלטל\u0004 אותו, ומותר הדבר.","ולענין \u0003מדוכה\u0004 — הלכה זו כ\u0003ר' נחמיה היא,\u0004 שהוא סבור \u0003שכל הכלים אינם ניטלים בשבת אלא לצורך השימוש להם הם מיועדים בדרך כלל, אם הוא מלאכה מותרת.\u0004","\u0003כל הכלים ניטלין לצורך ושלא לצורך. ר' נחמיה אומר: אין\u0004 הכלים \u0003ניטלין אלא לצורך.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה,\u0006 פירוש\u0005]\u0006 \u0003\"לצורך\" ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"שלא לצורך\"?\u0004","\u0003אמר רבה: \"לצורך\"\u0004 משמעו — \u0003דבר שמלאכתו להיתר\u0004 שמותר לטלטלו \u0003לצורך גופו,\u0004 כלומר שצריך לגופו של אותו כלי לצורך מלאכת היתר. \u0003\"שלא לצורך\"\u0004 משמעו לענין זה — שלא לצורך גופו, אלא \u0003דבר שמלאכתו להיתר לצורך מקומו, ו\u0004אולם \u0003דבר שמלאכתו לאיסור, לצורך גופו\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 הותר לטלטלו, ואולם \u0003לצורך מקומו\u0004 — \u0003לא. ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' נחמיה למימר\u0004 \u0005[לומר]\u0006 כי \u0003אפילו דבר שמלאכתו להיתר, לצורך גופו\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003לצורך מקומו\u0004 — \u0003לא. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: לצורך מקומו, \"שלא לצורך\" קרית ליה\u0004 \u0005[קורא אתה לו]?!\u0006 הרי לצורך הוא!","\u0003אלא אמר רבא:\u0004 כך יש לפרש: \u0003\"לצורך\"\u0004 משמעו — \u0003דבר שמלאכתו להיתר,\u0004 והותר לטלטלו \u0003בין לצורך גופו בין לצורך מקומו. \"שלא לצורך\"\u0004 משמעו — שאין צורך בו לא לגופו ולא למקומו, \u0003ו\u0004אולם שכוונתו לטלטלו ממקומו \u0003אפילו מחמה לצל\u0004 כדי לשמור על שלימותו. \u0003ודבר שמלאכתו לאיסור, לצורך גופו ולצורך מקומו\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 מותר לטלטלו, אבל \u0003מחמה לצל\u0004 — \u0003לא. ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' נחמיה למימר\u0004 \u0005[לומר]:\u0006 \u0003ואפילו דבר שמלאכתו להיתר, לצורך גופו ולצורך מקומו\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 הותר לטלטלו, ואולם \u0003מחמה לצל\u0004 — \u0003לא.\u0004","ומסופר כי \u0003יתיב\u0004 \u0005[ישבו]\u0006 \u0003רב ספרא ורב אחא בר הונא ורב הונא בר חנינא, ויתבי וקאמרי\u0004 \u0005[וישבו ואמרו]:\u0006 \u0003ל\u0004פירוש \u0003רבה אליבא\u0004 \u0005[על פי שיטת]\u0006 \u0003ר' נחמיה\u0004 האומר כי אפילו דבר שמלאכתו ליתר לצורך מקומו אסור לטלטלו, אם כן \u0003הני\u0004 \u0005[אלה]\u0006 ה\u0003קערות\u0004 הריקות \u0003היכי מטלטלינן\u0004 \u0005[כיצד מטלטלים אנו]\u0006 אותן? \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב ספרא: מידי דהוה\u0004 \u0005[כשם\u0006 \u0003שהוא]\u0004 ב\u0003גרף של רעי\u0004 (כלי של אשפה) שמטלטלים אותו מפני שהוא מאוס.","מסופר ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרבה\u0004 אותו ענין עצמו, \u0003למר אליבא\u0004 \u0005[ל\u0006פירוש \u0005אדוני לשיטת]\u0006 \u0003ר' נחמיה, הני\u0004 \u0005[אלה]\u0006 ה\u0003קערות\u0004 הריקות \u0003היכי מטלטלינן להו\u0004 \u0005[כיצד מטלטלים אנו אותן]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003רב ספרא חברין תרגמה\u0004 \u0005[חברנו הסבירה]:\u0006 \u0003מידי דהוה\u0004 \u0005[כשם שהוא]\u0006 ב\u0003גרף של רעי.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי לרבא\u0004 על ההסבר שלו במשנתנו, מן הברייתא: \u0003מדוכה, אם יש בה שום\u0004 — \u0003מטלטלין אותה\u0004 בשבת, \u0003ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אין מטלטלין אותה.\u0004 נמצא שיש כלי האסור בשבת בכל טילטול! ענה לו: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — בטלטול \u0003מחמה לצל\u0004 שהוא אסור אף לפירוש רבא לדעת הכל. ועוד \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ממה ששנינו במשנה: \u0003ושוין\u0004 בית שמאי ובית הלל בעלי, \u0003שאם קיצב\u0004 (חתך) ביום טוב \u0003עליו\u0004 כבר \u0003בשר\u0004 שזקוק לו בחג \u0003שאסור לטלטלו\u0004 יותר בחג! והשיב רבא: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר בטלטול \u0003מחמה לצל.\u0004","והקשה עוד: \u0003והא דתנן\u0004 \u0005[וזו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003אין סומכין את הקדירה בבקעת\u0004 (חתיכת עץ) \u0003וכן בדלת\u0004 אין סומכים אותה בבקעת. \u0003והא\u0004 \u0005[והרי]\u0006 \u0003בקעת\u0004 ש\u0003ביום טוב דבר שמלאכתו להיתר הוא,\u0004 שהרי מותרת בטלטול כדי להסיק בה את התנור, \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003דבר שמלאכתו להיתר\u0004 יש מי שסבור ש\u0003בין לצורך גופו בין לצורך מקומו\u0004 — \u0003אסור\u0004 לטלטלו, ולשיטת רבא אף ר' נחמיה אינו סבור כן! ענה רבא: \u0003התם, מאי טעמא\u0004 \u0005[שם, מהו טעם\u0006 הדבר\u0005]\u0006 — \u0003כיון\u0004 ש\u0003בשבת דבר שמלאכתו לאיסור הוא,\u0004 והבקעת מוקצה משימוש, \u0003גזירה\u0004 הוא שגזרו \u0003שתהא אסורה בטלטול אף ביום טוב אטו\u0004 \u0005[משום]\u0006 \u0003שבת.\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 ב\u0003שבת גופיה תישתרי\u0004 \u0005[עצמה תותר]\u0006 הבקעת בטלטול, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003דבר שמלאכתו לאיסור, לצורך גופו ולצורך מקומו שרי\u0004 \u0005[מותר]\u0006 — אפשר לענות על כך: \u0003הני מילי היכא דאיכא\u0004 \u0005[דברים אלה\u0006 שהותר בכגון זה לטלטל \u0005אמורים\u0006 דווקא \u0005היכן שיש]\u0006 \u0003תורת כלי עליו,\u0004 ואולם \u0003היכא דליכא\u0004 \u0005[במקום שאין]\u0006 \u0003תורת כלי עליו\u0004 — \u0003לא.\u0004","ושואלים: \u0003ומי גזרינן\u0004 \u0005[והאם גוזרים אנו]\u0006 ביום טוב משום שבת? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003משילין\u0004 (משליכים) \u0003פירות\u0004 מן הגג \u0003דרך ארובה ביום טוב, אבל לא בשבת,\u0004 והרי שאין גוזרים ואומרים שכל האסור בשבת יהא אסור ביום טוב!","ומקשים לצד שני: \u0003ומי לא גזרינן\u0004 \u0005[והאם אין אנו גוזרים]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003אין בין יום טוב לשבת אלא\u0004 היתר הכנת \u0003אוכל נפש בלבד,\u0004 נמצא שבכל דבר אחר מקפידים להשוות את דיני שבת ויום טוב!","\u0003אמר רב יוסף: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 ויש לומר כי \u0003הא\u0004 \u0005[זו,\u0006 המשנה האוסרת\u0005]\u0006 — שיטת \u0003ר' אליעזר\u0004 היא, ואילו \u0003הא\u0004 \u0005[זו\u0006 המשנה המתירה\u0005]\u0006 — \u0003ר' יהושע. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 שתי בהמות שהן אם ובת, ויש בהן איסור \u0003\"אותו ואת בנו\u0004 לא תשחטו ביום אחד \u0003\"שנפלו לבור\u0004 ביום טוב, \u0003ר' אליעזר אומר: מעלה את הראשון\u0004 — \u0003על מנת לשוחטו, ושוחטו. והשני\u0004 — \u0003עושה לו פרנסה\u0004 (נותן לו מזון) \u0003במקומו בשביל שלא ימות. ר' יהושע אומר: מעלה את הראשון\u0004 — \u0003על מנת לשוחטו, ואינו שוחטו, ומערים\u0004 ואומר שנמלך בדעתו והחליט לשחוט את השני \u0003ומעלה את השני, רצה\u0004 — את \u0003זה שוחט. רצה\u0004 — את \u0003זה שוחט.\u0004 נמצא שהתיר ר' יהושע דברים ביום טוב משום הפסד, ולא גזר בהם.","ודוחים: \u0003ממאי\u0004 \u0005[ממה]\u0006 סבור אתה שכן הוא? \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' אליעזר התם\u0004 \u0005[שם]\u0006 \u0003אלא\u0004 במקום ש\u0003אפשר\u0004 להציל את הבהמה במקומה על \u0003ידי פרנסה, אבל היכא דלא\u0004 \u0005[שאי]\u0006 \u0003אפשר ל\u0004הצילה על ידי \u0003פרנסה\u0004 במקומה — \u0003לא.\u0004","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' יהושע התם\u0004 \u0005[שם]\u0006 אלא במקום ש\u0003אפשר בהערמה, אבל היכא\u0004 \u0005[היכן,\u0006 במקום\u0005]\u0006 \u0003דלא\u0004 \u0005[שאי]\u0006 \u0003אפשר בהערמה\u0004 — \u0003לא\u0004 התיר!","\u0003אלא אמר רב פפא: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 ויש לומר כי \u0003הא\u0004 \u0005[זו,\u0006 משנה אחת\u0005]\u0006 — כדעת \u0003בית שמאי,\u0004 ו\u0003הא\u0004 \u0005[זו,\u0006 האחרת\u0005]\u0006 — כדעת \u0003בית הלל. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003בית שמאי אומרים:\u0004"],["\u0003אין מוציאין את הקטן ואת הלולב ואת ספר תורה לרשות הרבים\u0004 ביום טוב, \u0003ובית הלל מתירין.\u0004 הרי שהתירו בית הלל ביום טוב הוצאה שלא לצורך אוכל נפש.","ודוחים: \u0003אימר דשמעת להו\u0004 \u0005[אמור ששמעת אותם]\u0006 את \u0003בית שמאי\u0004 שהם אוסרים, רק לענין \u0003הוצאה\u0004 מרשות לרשות שאומרים כן, ואולם בענין איסור \u0003טלטול מי שמעת להו\u0004 \u0005[האם שמעת אותם]?\u0006 נימוק זה נדחה מיד: \u0003וטלטול גופיה לאו\u0004 \u0005[עצמו האם לא]\u0006 גזירה \u0003משום\u0004 איסור \u0003הוצאה היא?!\u0004 והאוסר בהוצאה, ודאי אוסר בטלטול.","ומוסיפים: \u0003ואף רב סבר לה להא\u0004 \u0005[סבור כ\u0006הלכה \u0005זו]\u0006 של \u0003רבא.\u0004 ש\u0003אמר רב:\u0004 לטלטל \u0003מר\u0004 (מעדר) על מנת \u0003שלא יגנב\u0004 — \u0003זהו טלטול שלא לצורך, ואסור.\u0004 ונדייק מכאן: \u0003טעמא\u0004 \u0005[הטעם\u0006 דווקא\u0005]\u0006 \u0003שלא יגנב, אבל לצורך גופו ו\u0004כן \u0003לצורך מקומו\u0004 — \u0003מותר.\u0004","ומקשים: \u0003איני\u0004 \u0005[וכי כן הוא]?!\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב כהנא איקלע לבי\u0004 \u0005[הזדמן לבית]\u0006 \u0003רב ואמר: אייתו ליה שותא\u0004 \u0005[הביאו לו רשת]\u0006 \u0003לכהנא ליתיב עליה\u0004 \u0005[\u0006ש\u0005ישב עליה].\u0006 \u0003לאו למימרא\u0004 \u0005[האם אין זה לומר]\u0006 ש\u0003דבר שמלאכתו לאיסור, לצורך גופו\u0004 — \u0003אין,\u0004 \u0005[כן],\u0006 מותר לטלטלו, ו\u0003לצורך מקומו\u0004 — \u0003לא!\u0004","ומתרצים: \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003שקולו שותא מקמי\u0004 \u0005[הוציאו\u0006 את ה\u0005רשת מלפני]\u0006 \u0003כהנא.\u0004 ונמצא אם כן שהיה זה טלטול לצורך מקומה. \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 היתה זו הוצאה \u0003מחמה לצל,\u0004 שהיתה מונחת במקום שעלולה היתה להינזק שם, וכיון שאפשר היה לחשוב שבשל כך טילטלוה, והרואה היה עלול ללמוד שבכגון זה הותר הטלטול, לכך פירש רב שמטלטלים את הרשת לצורך מקומה.","ומסופר: \u0003רב מרי בר רחל הוה ליה ההיא בי סדיותא בשמשא\u0004 \u0005[היו לו כרי לבד מונחים בשמש]\u0006 בשבת. \u0003אתא לקמיה\u0004 \u0005[בא\u0006 רב מרי \u0005לפני]\u0006 \u0003רבא. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מהו\u0004 הדין לענין ההיתר \u0003לטלטולינהו\u0004 \u0005[לטלטלם]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003שרי\u0004 \u0005[מותר].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב מרי: \u0003אית\u0004 \u0005[יש]\u0006 \u0003לי\u0004 גם \u0003אחרינא\u0004 \u0005[אחרים],\u0006 ואיני זקוק לכרים אלה דווקא. אמר לו רבא: בכל אופן \u0003חזו\u0004 \u0005[ראויים]\u0006 הכרים \u0003לאורחים.\u0004 אמר לו רב מרי: \u0003אית\u0004 \u0005[יש]\u0006 \u0003לי נמי\u0004 \u0005[גם כן]\u0006 אחרים \u0003ל\u0004צורך ה\u0003אורחים.\u0004 ונמצא שאינו מטלטל אלא לצורך הכרים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003גלית אדעתך\u0004 \u0005[גילית דעתך]\u0006 ש\u0003כ\u0004שיטת \u0003רבה סבירא לך\u0004 \u0005[סבור אתה],\u0006 ומאחר וכן \u0003לכולי עלמא\u0004 — \u0003שרי\u0004 \u0005[לכל העולם\u0006 — \u0005מותר]\u0006 לטלטל בכגון זה, ואולם \u0003לדידך\u0004 — \u0003אסיר\u0004 \u0005[\u0006\u0005לך\u0006 — \u0005אסור],\u0006 שאין אומרים לאדם לעשות דבר שלדעתו יש בו איסור.","\u0003אמר ר' אבא\u0004 שכך \u0003אמר ר' חייא בר אשי\u0004 שכך \u0003אמר רב: מכבדות\u0004 (מטאטאים) \u0003של מילתא\u0004 (בגדים) — \u0003מותר לטלטלן בשבת,\u0004 מפני שמותר להשתמש בהן, \u0003אבל של\u0004 כפות ענפי \u0003התמרה\u0004 — \u0003לא.\u0004 מפני שאסור לטאטא בהן מחשש השוואת גומות.","\u0003ר' אלעזר אומר: אף של תמרה\u0004 הותרו בטלטול. ושואלים: \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 כי רוצה לטלטלן \u0003לצורך גופו ו\u0004כן \u0003לצורך מקומו\u0004 — האם \u0003בהא לימא\u0004 \u0005[בזה יאמר]\u0006 \u0003רב\u0004 כי \u0003של תמרה לא\u0004 יטלטל? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב כ\u0004שיטת \u0003רבא סבירא ליה\u0004 \u0005[סבור הוא]\u0006 לענין זה. \u0003אלא\u0004 יש לפרש שמדובר בטלטול \u0003מחמה לצל,\u0004 שאותם מטאטאים נמצאים במקום שהם עלולים להינזק. ואולם עדיין יש לתמוה: \u0003בהא לימא\u0004 \u0005[בזו יאמר]\u0006 \u0003ר' אלעזר\u0004 כי \u0003אף של תמרה\u0004 מותר? ומתרצים: \u0003לעולם\u0004 מדובר בטלטול \u0003מחמה לצל,\u0004 ו\u0003אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]:\u0006 \u0003וכן אמר ר' אלעזר,\u0004 כדברי רב, שאסור.","\u0003כל הכלים הניטלין בשבת\u0004 — אף \u0003שבריהן,\u0004 אם נשברו, \u0003ניטלין עמהן, ובלבד שיהו עושין\u0004 (ראויים לעשות) \u0003מעין מלאכה\u0004 כלשהי.","כגון: \u0003שברי עריבה\u0004 (קערה גדולה) שנוטלים \u0003לכסות בהן את פי החבית,\u0004 או \u0003שברי\u0004 כלי \u0003זכוכית לכסות בהן את פי הפך.\u0004","ואילו \u0003ר' יהודה אומר: בלבד שיהו עושין מעין מלאכתן\u0004 הראשונה ולא מלאכה אחרת, כגון: \u0003שברי עריבה\u0004 צריך שיהיו ראויים \u0003לצוק לתוכן מקפה\u0004 (מרק), \u0003ושל זכוכית\u0004 שיהיו ראויים \u0003לצוק לתוכן שמן.\u0004","\u0003אמר רב יהודה\u0004 שכך \u0003אמר שמואל: מחלוקת\u0004 זו ששנינו במשנה ב\u0003שנשברו\u0004 הכלים \u0003מערב שבת, דמר סבר\u0004 \u0005[שחכם זה,\u0006 ר' יהודה, \u0005סבור]\u0006 אם \u0003מעין מלאכתן\u0004 הקודמת עושים — \u0003אין\u0004 \u0005[כן,\u0006 מותר\u0005],\u0006 \u0003מעין מלאכה אחרת\u0004 — \u0003לא. ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים \u0005סבור]:\u0006 \u0003אפילו\u0004 אם עושים רק \u0003מעין מלאכה אחרת\u0004 גם כן מותר.","\u0003אבל\u0004 אם \u0003נשברו בשבת\u0004 — \u0003דברי הכל מותרין.\u0004 וטעם הדבר: \u0003הואיל ומוכנין\u0004 היו לפני שבירתם \u0003על גבי\u0004 (אגב, בגלל) \u0003אביהן\u0004 (הכלי השלם) — \u0003מותר\u0004 לטלטל אף את שבריו.","\u0003מותיב\u0004 \u0005[מקשה]\u0006 \u0003רב זוטראי\u0004 ממה ששנינו: \u0003מסיקין\u0004 אש ביום טוב \u0003בכלים\u0004 שלמים, \u0003ואין מסיקין בשברי כלים.\u0004","ויש לברר: ש\u0003נשברו אימת\u0004 \u0005[מתי]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003נשברו מערב יום טוב\u0004 — מדוע אסור להסיק בהם? הלא \u0003עצים בעלמא נינהו\u0004 \u0005[סתם הם]!\u0006 \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר באופן שנשברו \u0003ביום טוב, וקתני\u0004 \u0005[ושנינו]:\u0006 \u0003מסיקין בכלים ואין מסיקים בשברי כלים!\u0004 הרי שבדבר שנשבר ביום טוב, וכל שכן בשבת, יש בו צד חומרה יתירה!","\u0003אלא אי איתמר, הכי איתמר\u0004 \u0005[אם נאמר, כך נאמר],\u0006 \u0003אמר רב יהודה\u0004 שכך \u0003אמר שמואל: מחלוקת שנשברו בשבת, דמר סבר\u0004 \u0005[שחכם זה,\u0006 חכמים, \u0005סבור]\u0006 \u0003מוכן הוא\u0004 מבעוד יום אגב הכלי השלם, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' יהודה \u0005סבור]\u0006 ש\u0003נולד הוא,\u0004 שכיון שלא היו שברים אלה קודם לכן הריהם כמציאות חדשה שנולדה עתה, ומוקצים משימוש, \u0003אבל\u0004 אם נשברו \u0003מערב שבת\u0004 — ל\u0003דברי הכל\u0004 הם \u0003מותרין\u0004 בטלטול, \u0003הואיל והוכנו למלאכה\u0004 כלשהי \u0003מבעוד יום.\u0004","באותו ענין בדיני יום טוב \u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003מסיקין בכלים, ואין מסיקין בשברי כלים. ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003כשם שמסיקין בכלים, כך מסיקין בשברי כלים. ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003אין מסיקין לא בכלים ולא בשברי כלים.\u0004","ואת הסתירה בין הברייתות מסבירים כך: \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 המבדילה בין כלים לשברי כלים — כדעת \u0003ר' יהודה\u0004 הסובר שיש דין מוקצה. \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 המתירה הכל — כדברי \u0003ר' שמעון\u0004 שאינו מקבל איסור מוקצה. \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 האוסרת הכל — כ\u0003ר' נחמיה,\u0004 האוסר לטלטל בשבת כלי שלא לצורכו המיוחד לו.","\u0003אמר רב נחמן: הני ליבני דאישתיור מבניינא\u0004 — \u0003שרי לטלטולינהו, דחזו למיזגא עלייהו\u0004 \u0005[לבנים אלה שנשארו מן הבנין\u0006 — \u0005מותר לטלטלן\u0006 בשבת, משום \u0005ש\u0006הן \u0005ראויות לשבת עליהם].\u0006 ואם \u0003שרגינהו\u0004 \u0005[סידרן\u0006 בערימה \u0003]\u0004 — \u0003ודאי אקצינהו\u0004 \u0005[\u0006\u0005הקצה אותן]\u0006 מדעתו, ואסורות בטלטול משום מוקצה.","\u0003אמר רב נחמן\u0004 שכך \u0003אמר שמואל:\u0004 חתיכת \u0003חרס קטנה\u0004 — \u0003מותר לטלטל\u0004 אותה בשבת \u0003בחצר,\u0004 לפי שהיא רשות היחיד, \u0003אבל בכרמלית\u0004 — \u0003לא.\u0004 שכרגיל אין מה לעשות בחרס זה. \u0003ורב נחמן דידיה\u0004 \u0005[\u0006מדעתו \u0005שלו]\u0006 \u0003אמר: אפילו בכרמלית\u0004 מותר, \u0003אבל ברשות הרבים\u0004 — \u0003לא. ורבא אמר: אפילו ברשות הרבים\u0004 מותר.","\u0003ואזדא\u0004 \u0005[והלך]\u0006 \u0003רבא לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005].\u0006 ש\u0003רבא הוה קאזיל בריתקא\u0004 \u0005[היה הולך ברחוב]\u0006 ב\u0003מחוזא, אתווסאי מסאניה טינא\u0004 \u0005[\u0006ו\u0005נתלכלכו נעליו בטיט].\u0006 \u0003אתא שמעיה, שקל חספא וקא מכפר ליה\u0004 \u0005[בא שמשו, לקח חרס\u0006 מן הרחוב \u0005וגירד אותו\u0006 את הטיט\u0005].\u0006 \u0003רמו ביה רבנן קלא\u0004 \u0005[הרימו בו חכמים קול\u0006 לגעור בו\u0005].\u0006 \u0003אמר\u0004 רבא: \u0003לא מיסתייא\u0004 \u0005[די]\u0006 להם ש\u0003לא גמירי\u0004 \u0005[למדו],\u0006 \u0003מיגמר נמי מגמרי\u0004 \u0005[ללמד\u0006 לאחרים \u0005הם גם כן מלמדים]?!\u0006 \u0003אילו בחצר הוה\u0004 \u0005[היה]\u0006 החרס \u0003— מי\u0004 \u0005[האם]\u0006 \u0003לא הוה חזיא לכסויי ביה מנא\u0004 \u0005[היה ראוי לכסות בו כלי]?\u0006 \u0003הכא נמי\u0004 — \u0003חזיא לדידי\u0004 \u0005[כאן גם כן ראוי\u0006 היה החרס \u0005בשבילי],\u0006 ואין לאסור את טלטולו.","\u0003אמר רב יהודה\u0004 שכך \u0003אמר שמואל: מגופת חבית שנכתתה\u0004 (נשברה) — \u0003מותר לטלטל\u0004 אותה \u0003בשבת. תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003מגופה שנכתתה\u0004 — \u0003היא ושבריה מותר לטלטלה בשבת. ו\u0004אולם \u0003לא יספות\u0004 (ישבור) \u0003ממנה שבר לכסות בה את הכלי ו\u0004כן \u0003לסמוך בה\u0004 את \u0003כרעי המטה. ואם זרקה באשפה\u0004 — \u0003אסור\u0004 לטלטלה עוד, לפי שהקצה אותה מדעתו.","\u0003מתקיף לה\u0004 \u0005[על כך]\u0006 \u0003רב פפא: אלא מעתה,\u0004 אם \u0003זריק ליה לגלימיה\u0004 \u0005[יזרוק אותה את גלימתו]\u0006 באשפה \u0003האם הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר ש\u0003אסור\u0004 לטלטלה משום מוקצה?! והלא הגלימה ראויה עדיין לשימוש, והרי שלא בדעתו תלוי הדבר. \u0003אלא אמר רב פפא\u0004"],["\u0003אם זרקה\u0004 לגלימה בערב שבת \u0003מבעוד יום לאשפה\u0004 — \u0003אסורה\u0004 בטלטול בשבת, שגילה דעתו מאתמול שמבטלה ומקצה אותה מן השימוש.","\u0003אמר בר המדורי\u0004 שכך \u0003אמר שמואל: קרומיות\u0004 (שיירים) \u0003של מחצלת\u0004 — \u0003מותר לטלטלם בשבת.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003אמר רבא: בר המדורי אסברא\u0004 \u0005[הסביר]\u0006 \u0003לי\u0004 את טעם הדבר, והוא: ה\u0003מחצלת גופא למאי חזיא\u0004 \u0005[עצמה למה\u0006 היא \u0005ראויה]\u0006 — \u0003לכסויי ביה עפרא\u0004 \u0005[לכסות בה עפר],\u0006 \u0003הני נמי חזיין לכסויי בהו\u0004 \u0005[אלה\u0006 השברים \u0005גם כן ראויים לכסות בהם]\u0006 את ה\u0003טינופת.\u0004","\u0003אמר ר' זירא\u0004 שכך \u0003אמר רב: שירי פרוזמיות\u0004 (מיני בגדים) — אסור \u0003לטלטלן בשבת. אמר אביי:\u0004 מדובר כאן \u0003במטלניות\u0004 (מטליות קטנות) \u0003שאין בהן שלש על שלש\u0004 אצבעות, \u0003דלא חזיין\u0004 \u0005[שאינן ראויות]\u0006 לשימוש \u0003לא לעניים ולא לעשירים.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003שברי תנור ישן הרי הן\u0004 ניטלים בשבת בחצר, \u0003ככל\u0004 שאר \u0003הכלים הניטלין\u0004 בשבת \u0003בחצר,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר: אין ניטלין. העיד ר' יוסי משום\u0004 (בשם) \u0003ר' אליעזר בן יעקב על שברי תנור ישן שניטלין בשבת, ועל כיסויו שאינו צריך בית יד.\u0004","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון \u0005הם חולקים]?\u0006 \u0003אמר אביי: בעושין מעין מלאכה, ו\u0004אולם \u0003אין עושין מעין מלאכתן\u0004 הראשונה \u0003קמיפלגי\u0004 \u0005[נחלקו],\u0006 אם מותר שבר כלי כזה בשימוש. \u0003ואזדא\u0004 \u0005[והלך]\u0006 \u0003ר' יהודה לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 \u0003ור' מאיר לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 כשם שנחלקו במשנתנו.","\u0003מתקיף לה\u0004 \u0005[הקשה על כך]\u0006 \u0003רבא: אי הכי, אדמיפלגי\u0004 \u0005[עד ש\u0006הם \u0005נחלקים]\u0006 \u0003בשברי תנור, ליפלגו\u0004 \u0005[שיחלקו]\u0006 \u0003בשברי כלים בעלמא\u0004 \u0005[בכלל]\u0006 ומדוע דווקא בתנור?","\u0003אלא אמר רבא: בשברי דהאי\u0004 \u0005[זה]\u0006 ה\u0003תנור\u0004 המיוחד \u0003קמיפלגי\u0004 \u0005[חלוקים הם].\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 תנור של חרס שלא הדביקו, כרגיל בתנורים, בטיט לאדמה, אלא \u0003נתנו על פי הבור או על פי הדות\u0004 (בור שקירותיו בנויים) \u0003ונתן שם אבן\u0004 בין קיר הבור לתנור להחזיק את התנור במקומו, \u0003ר' יהודה אומר: אם מסיק מלמטה\u0004 בתוך הבור \u0003והוא\u0004 התנור \u0003נסוק\u0004 על ידי כך \u0003מלמעלה\u0004 — \u0003טמא,\u0004 שכן התנור משמש לצורכו וכלי שלם הוא, הראוי לקבל טומאה. \u0003ואם לאו\u0004 \u0005[לא],\u0006 שאינו מהודק עד כדי כך ובשל כך אף אינו ניסוק למעלה — \u0003טהור,\u0004 שהוא כתנור שלא נגמרה מלאכתו. \u0003וחכמים אומרים: הואיל והוסק מכל מקום\u0004 — \u0003טמא,\u0004 שכן הוא משמש לתפקידו.","\u0003ובמאי קמיפלגי\u0004 \u0005[ובמה,\u0006 באיזה ענין \u0005נחלקו]\u0006 — \u0003בהאי קרא\u0004 \u0005[בפסוק זה]:\u0006 \u0003\"\u0004וכל אשר יפול מנבלתם עליו יטמא \u0003תנור וכירים יתץ טמאים הם וטמאים יהיו לכם\"\u0004 (ויקרא יא, לה). \u0003שר' יהודה סבר\u0004 \u0005[סבור]:\u0006 תנור ה\u0003מחוסר נתיצה,\u0004 כלומר, שהוא שלם, ואפשר לשבור אותו — \u0003טמא,\u0004 זהו המקבל טומאה. ואילו \u0003שאין מחוסר נתיצה,\u0004 אלא אינו עומד במקום ראוי כל צרכו והריהו כבר כשבור ממילא — \u0003טהור\u0004 הוא, אינו מקבל טומאה. \u0003ורבנן סברי\u0004 \u0005[ו\u0006אילו \u0005חכמים סבורים]\u0006 שבא הפסוק להוסיף: \u0003\"טמאים יהיו לכם\"\u0004 — \u0003מכל מקום\u0004 ובכל דרך.","ושואלים: \u0003ורבנן נמי, הכתיב\u0004 \u0005[ו\u0006לדעת \u0005חכמים\u0006 גם כן \u0005הרי נאמר]\u0006 \u0003\"יתץ\",\u0004 ומדוע אינם מפרשים כר' יהודה? ומסבירים: את הפסוק \u0003ההוא\u0004 הם מבינים \u0003לאידך גיסא\u0004 \u0005[לצד אחר],\u0006 \u0003דסלקא דעתך אמינא\u0004 \u0005[שיעלה על דעתך לומר]:\u0006 \u0003כיון דחבריה בארעא\u0004 \u0005[שחיברו בארץ]\u0006 — \u0003כגופא דארעא דמי\u0004 \u0005[כגוף הארץ נחשב],\u0006 וכל דבר המחובר לארץ חיבור של קבע אינו מקבל טומאה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 כי כיון שאפשר לנתקו הריהו טמא.","ושואלים: \u0003ואידך נמי, הכתיב\u0004 \u0005[ו\u0006הצד \u0005האחר,\u0006 ר' יהודה, \u0005גם כן, הלא נאמר]\u0006 \u0003\"טמאים יהיו לכם \"!\u0004 ומתרצים: \u0003ההיא,\u0004 דבר זה מבין הוא \u0003כ\u0004דברי \u0003רב יהודה\u0004 ש\u0003אמר\u0004 בשם \u0003שמואל.\u0004 ש\u0003אמר רב יהודה\u0004 שכך \u0003אמר שמואל : מחלוקת\u0004 ר' יהודה וחכמים היא דווקא \u0003בהיסק ראשון.\u0004 כלומר, שהיה התנור עדיין חרס שלא נתייבש כל צרכו ולא הוסק מעולם, והיסקו הראשון הוא העושה אותו כלי, \u0003אבל בהיסק שני\u0004 אין הם חולקים, ו\u0003אפילו תלוי בצואר גמל\u0004 — טמא.","\u0003אמר עולא: והיסק ראשון לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים],\u0006 \u0003אפילו תלוי בצואר גמל,\u0004 כיון שניסוק הריהו תנור לכל דבר, וטמא.","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 על סברה זו \u0003רב אשי: אי הכי, אדמיפלגי\u0004 \u0005[אם כך, עד שנחלקו]\u0006 \u0003בשברי תנור, ליפלגו\u0004 \u0005[שיחלקו]\u0006 \u0003בתנור גופה\u0004 \u0005[עצמו].\u0006 \u0003השתא\u0004 \u0005[עכשיו]\u0006 הרי \u0003תנור גופה\u0004 \u0005[עצמו]\u0006 \u0003ל\u0004שיטת \u0003ר' יהודה לא הוי מנא\u0004 \u0005[אין הוא\u0006 נחשב \u0005כלי],\u0006 אם כן \u0003שבריו מיבעיא\u0004 \u0005[נצרך לומר\u0006 שאינם כלי\u0005]?!\u0006","\u0003אלא אמר רב אשי: לעולם\u0004 יש לפרש \u0003כדאמרן מעיקרא\u0004 \u0005[כמו שאמרנו מתחילה]\u0006 שמדובר בשברי כל תנור שהוא \u0003ו\u0004משברי תנור אלה \u0003עושה מעשה טפקא\u0004 (כעין רעף חרס שצולים עליו), \u0003ו\u0004כך יש להבין: \u0003ר' מאיר לדבריו\u0004 של \u0003ר' יהודה קאמר\u0004 \u0005[אמר],\u0006 וכך אמר: \u0003לדידי\u0004 \u0005[לשיטתי]\u0006 \u0003אפילו ב\u0004שברים ה\u0003עושין מעין מלאכה\u0004 כלשהי יש לומר שהם מותרים בטלטול, \u0003אלא לדידך, אודי\u0004 \u0005[לשיטתך,\u0006 \u0003הודה] לי מיהא\u0004 \u0005[לפחות]\u0006 \u0003דכהאי גוונא\u0004 \u0005[שבכגון זה]\u0006 \u0003מלאכתו הוא!\u0004 שהרי אף השברים עשויים לשמש לאפייה!","\u0003ור' יהודה\u0004 דוחה: \u0003לא דמי\u0004 \u0005[אינו דומה],\u0006 שכן \u0003התם\u0004 \u0005[שם]\u0006 בתנור שלם — \u0003הסקו מבפנים,\u0004 ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 בשבר — \u0003הסקו מבחוץ,\u0004 וכן \u0003התם\u0004 \u0005[שם]\u0006 כשהתנור שלם — החלק הוא \u0003מעומד,\u0004 ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 — השבר \u0003לאו\u0004 \u0005[לא]\u0006 \u0003מעומד\u0004 הוא ולכן אינו משמש מעין מלאכתו.","באותה תוספתא הובא ש\u0003העיד ר' יוסי משום\u0004 (בשם) \u0003ר' אליעזר בן יעקב על שברי תנור ישן שניטלין בשבת, ועל כיסויו\u0004 של תנור \u0003שאינו צריך בית יד,\u0004 שהוא נחשב ככלי ראוי לטלטול כמות שהוא. \u0003אמר רבינא: כמאן מטלטלינן האידנא כיסוי דתנורי\u0004 \u0005[כ\u0006שיטת \u0005מי מטלטלים אנו עתה כיסויי תנורים]\u0006 של \u0003מתא מחסיא\u0004 ש\u0003אין להם בית אחיזה? כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 — \u0003כ\u0004שיטת \u0003ר' אליעזר בן יעקב.\u0004","\u0003האבן שבקירויה\u0004 (דלעת ששואבים בה מים), \u0003אם ממלאין בה\u0004 בדלעת מים, \u0003ו\u0004האבן \u0003אינה נופלת\u0004 — \u0003ממלאין בה\u0004 בשבת, \u0003ואם לאו\u0004 \u0005[לא],\u0006 שהאבן נופלת — \u0003אין ממלאין בה.\u0004"],["\u0003זמורה\u0004 של גפן \u0003שהיא קשורה בטפיח\u0004 (כעין דלי לשאיבה) — \u0003ממלאין בה בשבת,\u0004 שהזמורה נעשתה חלק מן הכלי.","\u0003פקק החלון, ר' אליעזר אומר: בזמן שהוא קשור\u0004 בחלון, \u0003ותלוי,\u0004 שאיננו נוגע בארץ — \u0003פוקקין בו\u0004 את החלון, שאין בכך משום בניה, \u0003ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אין פוקקין בו. וחכמים אומרים: בין כך ובין כך\u0004 — \u0003פוקקין בו.\u0004","\u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005]:\u0006 \u0003אבן שעל פי החבית\u0004 וברצונו לפתוח את החבית — \u0003מטה\u0004 את החבית \u0003על צידה, והיא,\u0004 האבן, \u0003נופלת. אמר רבה\u0004 שכך \u0003אמר ר' אמי\u0004 שכך \u0003אמר ר' יוחנן: לא שנו אלא בשוכח,\u0004 שהניח את האבן על החבית בלא משים, \u0003אבל במניח\u0004 את האבן על פי חבית בכוונה — \u0003נעשה\u0004 החבית \u0003בסיס לדבר האסור\u0004 (האבן) ואסור לטלטל אף את החבית. \u0003ו\u0004אילו \u0003רב יוסף אמר\u0004 בשם \u0003ר' אסי\u0004 שכך \u0003אמר ר' יוחנן: לא שנו\u0004 דין זה בחבית \u0003אלא בשוכח, אבל במניח\u0004 — \u0003נעשה\u0004 האבן \u0003כיסוי להחבית\u0004 ומותר להשתמש בה כבשאר כיסויי חבית.","\u0003אמר רבה: מותבינן אשמעתין\u0004 \u0005[מקשים אנו על ההלכה שלנו]\u0006 מן המשנה כאן, שהלא שנינו: \u0003האבן שבקירויה\u0004 (דלעת) \u0003אם ממלאין בה\u0004 בקרויה מים \u0003ו\u0004האבן \u0003אינה נופלת\u0004 ממנה — \u0003ממלאין בה,\u0004 ונמצא שאם מייחדים את האבן לצורך, היא מפסיקה להיות מוקצה! והוא עצמו מתרץ: \u0003ולא היא,\u0004 אין להשוות את הדברים. \u0003התם\u0004 \u0005[שם]\u0006 באבן שבקרויה, \u0003כיון\u0004 ש\u0003הדקה\u0004 לאבן אל הדלעת — \u0003שויא\u0004 \u0005[עשה]\u0006 את האבן \u0003דופן,\u0004 ונעשתה כחלק מן הכלי, מה שאין כך בכיסוי חבית.","\u0003אמר רב יוסף: ומותבינן אשמעתין\u0004 \u0005[ומקשים אנו על ההלכה שלנו]\u0006 ממה ששנינו במשנתנו: \u0003\"אם לאו\u0004 \u0005[לא]\u0006 הידקה לאותה אבן אל הדלעת — \u0003אין ממלאין בה\"\u0004 נמצא שאבן שאינה מהודקת אינה נחשבת ככלי והריהי מוקצה! והוא עצמו מסביר: \u0003ולא היא,\u0004 אין להשוות את הדברים. \u0003התם\u0004 \u0005[שם],\u0006 \u0003כיון\u0004 ש\u0003לא הדקה\u0004 — משמע ש\u0003בטולי בטלה\u0004 \u0005[ביטלה]\u0006 ואינו מחשיבה ככלי, והריהי אם כן כשאר מוקצה.","ומסבירים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון \u0005נחלקו]?\u0006 \u0003מר סבר בעינן\u0004 \u0005[חכם זה,\u0006 רבה, \u0005סבור\u0006 כי \u0005צריכים אנו]\u0006 \u0003מעשה\u0004 כדי להפוך אבן או חומר אחר ולהחשיבו ככלי, \u0003ומר סבר לא בעינן\u0004 \u0005[וחכם זה\u0006 במשנתנו \u0005סבור\u0006 כי \u0005אין אנו צריכים]\u0006 \u0003מעשה.\u0004","\u0003ואזדו לטעמייהו\u0004 \u0005[והלכו לטעמיהם]\u0006 ר' אמי ור' אסי, \u0003דכי אתא\u0004 \u0005[שכאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' חנינא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003ר' זירא\u0004 שכך \u0003אמר ר' חנינא: פעם אחת הלך רבי למקום אחד ומצא נדבך של אבנים, ואמר לתלמידיו: צאו וחשבו\u0004 שאתם מכינים את האבנים לצורך שבת \u0003כדי שנשב עליהן למחר\u0004 בשבת, \u0003ולא הצריכן רבי למעשה\u0004 באותן אבנים, והסתפק במחשבה.","\u0003ו\u0004אילו \u0003ר' יוחנן אמר:\u0004 לא כך היה המעשה, אלא \u0003הצריכן רבי למעשה\u0004 להכין את האבנים. ושאלו לשיטה זו: \u0003מאי\u0004 \u0005[מה],\u0006 איזה מעשה \u0003אמר להו\u0004 \u0005[להם]\u0006 לעשות? \u0003ר' אמי אמר: \"צאו ולמדום\"\u0004 (סדרו אותם) \u0003אמר להו\u0004 \u0005[להם]\u0006 רבי לתלמידיו. \u0003ר' אסי אמר: \"צאו ושפשפום\u0004 מן הטיט\" \u0003אמר להו\u0004 \u0005[להם].\u0006 הרי שר' אמי מצריך מעשה חשוב יותר באבן כדי להחשיבה ככלי.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו תנאים בענין זה, \u0003ר' יוסי בן שאול אמר: סואר\u0004 (ערימה) חדשה \u0003של קורות הוה\u0004 \u0005[היה].\u0006 \u0003ור' יוחנן בן שאול אמר: גשוש של ספינה\u0004 (המוט המשמש בספינה לדעת את עומק המים) \u0003הוה\u0004 \u0005[היה\u0006 זה\u0005].\u0006 \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שהתיר רבי לשבת על \u0003גשוש\u0004 — \u0003כל שכן\u0004 התיר ב\u0003סואר,\u0004 ואולם \u0003מאן דאמר\u0004 שהתיר ב\u0003סואר, אבל\u0004 אצל \u0003גשוש קפיד עליה\u0004 \u0005[מקפיד עליו]\u0006 שהוא מוקצה מחמת חסרון כיס, שמא יתעקם ויפגם.","שנינו במשנה ש\u0003זמורה\u0004 של גפן \u0003שהיא קשורה\u0004 בדלי ממלאים בה בשבת. ומדייקים: רק אם היא \u0003קשורה\u0004 — \u0003אין\u0004 \u0005[כן,\u0006 מותר\u0005],\u0006 ואולם כאשר \u0003היא לא קשורה\u0004 — \u0003לא. לימא מתניתין\u0004 \u0005[האם נאמר שמשנתנו]\u0006 ש\u0003לא כ\u0004שיטת \u0003רבן שמעון בן גמליאל.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003חריות של דקל שגדרן\u0004 (קצצן) \u0003ל\u0004צורך \u0003עצים\u0004 להסקה \u0003ונמלך עליהן\u0004 להשתמש בהן \u0003לישיבה\u0004 — \u0003צריך לקשור\u0004 אותן יחד בערב שבת כדי להוציאן מגדר מוקצה להשתמש בהן בשבת. \u0003רבן שמעון בן גמליאל אומר: אין צריך לקשור\u0004 והריהן כמוכנות מבעוד יום, נמצא שלדעת רבן שמעון בן גמליאל עץ קצוץ אין צורך להכינו במיוחד לצורך שבת.","\u0003אמר רב ששת: אפילו תימא\u0004 \u0005[תאמר]\u0006 שמשנתנו כשיטת \u0003רבן שמעון בן גמליאל,\u0004 ואולם יש לומר כי \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה עוסקים]\u0006 — \u0003ב\u0004אופן שזמורה זו עדיין \u0003מחוברת באביה\u0004 (בגפן). ומקשים: \u0003אי הכי, קא משתמש\u0004 \u0005[אם כך, הריהו משתמש]\u0006 \u0003ב\u0004דבר ה\u0003מחובר לקרקע,\u0004 והרי יודעים אנו שגזרו חכמים שלא להשתמש בכל דבר צומח בהיותו עדיין מחובר לקרקע! ומתרצים: שהיה זה מחובר \u0003למטה משלשה\u0004 טפחים, וכל המחובר בפחות משלשה טפחים אין דינו כאילן, כפי שמותר להשתמש בשורשי האילן הסמוכים לקרקע. \u0003רב אשי אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 כי מדובר \u0003ב\u0004זמורה \u0003תלושה,\u0004 ואולם החידוש שבדבר שיש לחשוש \u0003גזירה שמא יקטום\u0004 (יחתוך, יישר) זמורה ויכשירנה לשימוש בדלי, על כן השמיע לנו רבן שמעון שאין אנו חוששים לכך.","שנינו במשנה שנחלקו ר' אליעזר וחכמים בענין \u0003פקק החלון\u0004 באיזה אופן מותר לפקוק בו את החלון בשבת. \u0003אמר רבה בר בר חנה\u0004 שכך \u0003אמר ר' יוחנן: הכל מודים שאין עושין אהל,\u0004 אפילו הוא \u0003עראי, בתחלה ביום טוב, ואין צריך לומר\u0004 שאין עושים \u0003בשבת. לא נחלקו\u0004 חכמי המשנה \u0003אלא\u0004 ב\u0003להוסיף\u0004 על אהל קיים. \u0003שר' אליעזר אומר: אין מוסיפין ביום טוב, ואין צריך לומר\u0004 שאין מוסיפים \u0003בשבת. וחכמים אומרים: מוסיפין\u0004 על אהל ארעי \u0003בשבת, ואין צריך לומר\u0004 שמותר \u0003ביום טוב. \u0004","ועוד שנינו במשנה ש\u0003חכמים אומרים: בין כך ובין כך פוקקין בו\u0004 בפקק זה את החלון. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 הפירוש המדוייק\u0005]\u0006 של \u0003\"בין כך ובין כך\"\u0004 בענייננו? \u0003אמר ר' אבא\u0004 שכך \u0003אמר רב כהנא:\u0004"],["\u0003בין קשור בין שאינו קשור, והוא שמתוקן,\u0004 כלומר, הוכן מראש לצורך זה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ירמיה\u0004 לר' אבא: \u0003ולימא מר\u0004 \u0005[ויאמר אדוני]\u0006 בנוסח זה: \u0003בין תלוי ובין שאינו תלוי, והוא שקשור!\u0004 שכן \u0003אמר רבה בר בר חנה\u0004 שכך \u0003אמר ר' יוחנן: כמחלוקת כאן\u0004 בפקק החלון \u0003כך\u0004 יש \u0003מחלוקת\u0004 מקבילה ודומה \u0003בנגר הנגרר,\u0004 שהוא בריח שתוקעים בחור הדלת ובקרקע כדי להחזיק את הדלת במקומה. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003נגר הנגרר,\u0004 שאינו חלק מן הדלת אלא קשור בה ונגרר בארץ \u0003נועלין בו\u0004 בשבת \u0003במקדש,\u0004 שלא גזרו חכמים על דין שבות במקדש \u0003אבל לא במדינה\u0004 (בשאר חלקי הארץ). \u0003ו\u0004הנגר \u0003המונח,\u0004 שאיננו קשור כלל בדלת \u0003כאן וכאן,\u0004 בין במקדש בין במדינה \u0003אסור\u0004 לנעול בו בשבת. \u0003ר' יהודה אומר : המונח\u0004 מותר \u0003במקדש והנגרר\u0004 אף \u0003במדינה.\u0004","\u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003איזהו נגר הנגרר שנועלין בו במקדש אבל לא במדינה?\u0004 — \u0003כל שקשור ותלוי\u0004 בדלת \u0003וראשו\u0004 האחד \u0003מגיע לארץ. ר' יהודה אומר: זה אף במדינה מותר. אלא איזהו שבמדינה אסור\u0004 — \u0003כל שאינו לא קשור ולא תלוי, ושומטו\u0004 מן הדלת לאחר שימוש \u0003ומניחו בקרן זוית.\u0004","\u0003ואמר ר' יהושע בר אבא משמיה\u0004 \u0005[משמו]\u0006 של \u0003עולא : מאן תנא\u0004 \u0005[מיהו\u0006 התנא \u0005ששנה]\u0006 בהלכות\u0003 נגר הנגרר\u0004 — \u0003ר' אליעזר היא,\u0004 ששיטתו בענין זה זהה לדעתו במשנתנו בענין פקק החלון. הרי שודאי מדובר בפקק קשור, שאם אינו קשור — הלא סבור ר' אליעזר שאף במקדש אסור להשתמש בו!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא דאמרי כי האי תנא\u0004 \u0005[אני שאני אומר\u0006 זאת הרי זה \u0005כדעת תנא זה]\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בתוספתא\u0005]:\u0006 \u0003קנה שהתקינו בעל הבית להיות פותח ונועל בו\u0004 כבנגר, \u0003בזמן שקשור ותלוי בפתח\u0004 — \u0003פותח ונועל בו\u0004 בשבת, \u0003אין קשור ותלוי\u0004 — \u0003אין פותח ונועל בו. רבן שמעון בן גמליאל אומר:\u0004 אם היה \u0003מתוקן\u0004 לכך, מותר לפתוח בו \u0003אף על פי שאינו קשור.\u0004 נמצא שיש שיטה כי נגר אינו חייב להיות קשור, ודיו בתיקון בלבד.","\u0003אמר רב יהודה בר שילת\u0004 שכך \u0003אמר רב אסי\u0004 שכך \u0003אמר ר' יוחנן: הלכה\u0004 בענין זה \u0003כרבן שמעון בן גמליאל.\u0004","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003כל כסויי הכלים\u0004"],["\u0003שיש להם בית אחיזה ניטלין בשבת. ואמר רב יהודה בר שילא\u0004 שכך \u0003אמר רב אסי\u0004 שכך \u0003אמר ר' יוחנן: והוא\u0004 דווקא כ\u0003שיש תורת כלי עליהן,\u0004 שהכיסוי עצמו ראוי לשימוש ככלי, ולא כדברי רבן שמעון בן גמליאל המסתפק בהכנה בלבד.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בדברי רבן שמעון בן גמליאל מדובר באופן \u0003דאיכא\u0004 \u0005[שיש]\u0006 לאותו קנה \u0003תורת כלי עליו,\u0004 ואולם \u0003ומי בעי\u0004 \u0005[והאם מצריך,\u0006 דורש\u0005]\u0006 \u0003רבן שמעון בן גמליאל\u0004 שתהיה \u0003תורת כלי עליו? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003חריות של דקל שגדרן\u0004 (קצצן) \u0003לשם עצים\u0004 להסקה, \u0003ונמלך עליהן\u0004 להשתמש בהם \u0003לישיבה\u0004 — \u0003צריך לקשר\u0004 אותן לפני השבת, להתיר לו לשבת עליהם. ואילו \u0003רבן שמעון בן גמליאל אומר: אין צריך לקשר.\u0004 ונמצא שלדעתו אין צורך לעשות מעשה בעץ להכשירו למלאכה ודי ההכנה במחשבה בלבד! ומשיבים: \u0003ר' יוחנן סבירא ליה כוותיה בחדא ופליג עליה בחדא\u0004 \u0005[סבור כמותו ב\u0006דבר \u0005אחד ונחלק עליו באחד].\u0006 \u0003דרש ר' יצחק נפחא אפתחא דריש גלותא\u0004 \u0005[על פתחו של\u0006 בית \u0005ראש הגולה]:\u0006 \u0003הלכה כר' אליעזר,\u0004 בדין פקק החלון. \u0003מתיב\u0004 \u0005[מקשה]\u0006 רב \u0003עמרם\u0004 ממה ששנינו במשנה מפורשת: \u0003ומדבריהם למדנו שפוקקין ומודדין וקושרין בשבת,\u0004 ומכאן נלמד שפוקקים בכל אופן, ולאו דווקא בפקק המוכן לכך כדברי ר' אליעזר! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: מאי דעתיך\u0004 \u0005[מה,\u0006 מדוע \u0005דעתך]\u0006 כן — \u0003משום דקתני סתמא\u0004 \u0005[ששנינו סתם],\u0006 שבמשנה לא נתפרש שם חכם ולכן הלכה כמותה, ואולם המשנה בדין \u0003נגר הנגרר נמי סתמא\u0004 \u0005[גם כן סתם\u0006 משנה\u0005]\u0006 \u0003היא,\u0004 והיה צריך ואפשר לפסוק כשיטה זו. \u0003ו\u0004אולם מסכמים: \u0003אפילו הכי\u0004 \u0005[כך]\u0006 — \u0003מעשה רב,\u0004 שאף כשיש שתי משניות חולקות זו על זו, מעשה גדול ונחשב יותר. וכיון שמסופר באותה משנה שנהגו ועשו חכמים לפקוק את החלון — סומכים יותר על פסק הלכה זו.","","","","\u0003כל כיסוי הכלים שיש להם בית אחיזה\u0004 — \u0003ניטלין בשבת. אמר ר' יוסי: במה דברים אמורים\u0004 — \u0003בכיסוי קרקעות,\u0004 כגון כיסוי של בור. \u0003אבל בכיסוי הכלים\u0004 — \u0003בין כך ובין כך,\u0004 גם אם אין להם בית אחיזה — \u0003ניטלין בשבת.\u0004","\u0003אמר רב יהודה בר שילא\u0004 שכך \u0003אמר ר' אסי\u0004 שכך \u0003אמר ר' יוחנן: והוא\u0004 דווקא כ\u0003שיש תורת כלי עליהן\u0004 וראויים הכיסויים לשימוש כלשהו. ומוסיפים: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003כסוי קרקעות, אם יש להן בית אחיזה\u0004 — \u0003אין\u0004 \u0005[כן,\u0006 מותר לטלטלם\u0005],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא\u0004 — \u0003לא. כסוי הכלים, אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003אין להם בית אחיזה\u0004 — מותרים בטלטול.","\u0003כי פליגי\u0004 \u0005[כאשר נחלקו\u0006 במשנתנו\u0005]\u0006 הרי זה \u0003בכלים דחברינהו בארעא\u0004 \u0005[שחיברם בקרקע].\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 תנא קמא \u0005סבור]\u0006 כי \u0003גזרינן\u0004 \u0005[גוזרים אנו]\u0006 על כיסוי כלי המחובר בקרקע משום כיסוי קרקע עצמה, \u0003ומר סבר לא גזרינן\u0004 \u0005[וחכם זה,\u0006 ר' יוסי, \u0005סבור\u0006 ש\u0005אין אנו גוזרים].\u0006","\u0003לישנא אחרינא\u0004 \u0005[לשון אחרת]:\u0006 \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 היה זה רק \u0003בכיסוי תנור, מר מדמי ליה\u0004 \u0005[חכם זה מדמה אותו]\u0006 \u0003לכיסוי קרקע, ומר מדמי ליה\u0004 \u0005[וחכם זה מדמה אותו]\u0006 \u0003לכיסוי כלים.\u0004","","\u0003מפנין\u0004 בשבת \u0003אפילו ארבע וחמש קופות\u0004 (סלים) \u0003של תבן ו\u0004כן \u0003של תבואה מפני האורחים\u0004 הצריכים לשבת במקום ההוא, \u0003ומפני בטול בית המדרש\u0004 כשצריכים להושיב את התלמידים במקום. \u0003אבל לא\u0004 מפנים \u0003את האוצר\u0004 (המחסן).","ומה עוד הם הדברים שמותר לפנות? \u0003מפנין תרומה טהורה\u0004 אף על פי שראויה היא לאכילה רק לכהן, \u0003ודמאי\u0004 (תבואה שנקנתה מעם הארץ וספק אם עישר אותה) שכרגיל אסור לאוכלו עד שיפרישו ממנו מעשר מספק, \u0003ו\u0004כן \u0003מעשר ראשון שניטלה\u0004 כבר \u0003תרומתו\u0004 (תרומת מעשר) וניתנה לכהנים, \u0003ומעשר שני והקדש שנפדו, ו\u0004אף את \u0003התורמוס היבש\u0004 שאין אדם אוכלו \u0003מפני שהוא מאכל לעזים.\u0004","\u0003אבל\u0004 אין מפנים את הדברים שאינם ראויים כלל לאכילה, משום שהם בגדר מוקצה, \u0003לא את הטבל, ולא את מעשר ראשון שלא נטלה תרומתו, ולא את מעשר שני והקדש שלא נפדו, ולא את הלוף, ולא את החרדל\u0004 שאינו מתוקן. \u0003רבן שמעון בן גמליאל מתיר בלוף, מפני שהוא מאכל עורבין.\u0004","\u0003חבילי קש וחבילי עצים וחבילי זרדים, אם התקינן\u0004 מבעוד יום \u0003למאכל בהמה\u0004 — \u0003מטלטלין אותן. ואם לאו\u0004 \u0005[לא]\u0006 התקינם מבעוד יום — \u0003אין מטלטלין אותן.\u0004","שנינו במשנה שמפנים אפילו ארבע וחמש קופות. ושואלים: \u0003השתא\u0004 \u0005[עכשיו]\u0006 הרי שנינו כי \u0003חמש מפנין\u0004 ואם כן \u0003ארבע מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר?!","\u0003אמר רב חסדא:\u0004 הכוונה היא שמותר לפנות \u0003ארבע מ\u0004תוך \u0003חמש\u0004 קופות שנמצאות שם, אבל לא את כל הקופות כולן. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003ארבע מאוצר קטן וחמש מאוצר גדול.\u0004","ושואלים: \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"אבל לא את האוצר\"\u0004 — הכוונה היא \u0003שלא יתחיל באוצר תחלה,\u0004 כלומר, שאם יש לו מקום אחר, שעדיין לא התחילו להשתמש באוצר זה — לא יפנהו, \u0003ומני\u0004 \u0005[ו\u0006משנה זו \u0005של מי היא\u0006\u0005]\u0006 — שיטת \u0003ר' יהודה\u0004 היא \u0003דאית ליה\u0004 \u0005[שיש לו,\u0006 מקבל\u0005]\u0006 דין \u0003מוקצה.\u0004 ואוצר זה שלא התחילו בו מוקצה הוא מן השימוש.","\u0003ושמואל אמר:\u0004 יש לפרש את הקושי במשנה בדרך לשונית: \u0003ארבע וחמש\u0004"],["\u0003כדאמרי אינשי\u0004 \u0005[כפי שאומרים בני אדם]\u0006 שאינם מדקדקים כל כך, ואומרים ארבע או חמש או יותר, \u0003ואי בעי\u0004 \u0005[ואם רוצה]\u0006 \u0003אפילו טובא נמי\u0004 \u0005[יותר גם כן]\u0006 \u0003מפנין. ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"אבל לא את האוצר\"\u0004 — \u0003שלא יגמור\u0004 לפנותו \u0003כולו, דילמא אתי לאשוויי\u0004 \u0005[שמא יבוא להשוות,\u0006 ליישר\u0005]\u0006 את ה\u0003גומות\u0004 שבקרקעו. \u0003אבל אתחולי מתחיל\u0004 \u0005[מתחיל]\u0006 מן האוצר. \u0003ומני\u0004 \u0005[ו\u0006משנה זו של \u0005מי היא]\u0006 — שיטת \u0003ר' שמעון היא, דלית ליה\u0004 \u0005[שאין לו,\u0006 אינו מקבל\u0005]\u0006 דין \u0003מוקצה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003אין מתחילין\u0004 לפנות \u0003באוצר תחילה,\u0004 שאם עדיין לא השתמש באוצר זה, אלא מאחר, הרי מה שבתוכו מוקצה ואסור לפנותו. \u0003אבל עושה בו שביל כדי שיכנס ויצא.\u0004 ותוהים: \u0003עושה בו שביל?! והא\u0004 \u0005[והרי]\u0006 \u0003אמרת\u0004 ש\u0003אין מתחילין!\u0004 ומשיבים, \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003עושה בו שביל ברגליו\u0004 בדרך הליכתו \u0003בכניסתו\u0004 לתוכו \u0003וביציאתו\u0004 ממנו, אבל אינו מטלטל בידים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003תבואה צבורה, בזמן שהתחיל בה\u0004 להשתמש ממנה עוד \u0003מערב שבת\u0004 — \u0003מותר להסתפק\u0004 (ליהנות, להשתמש) \u0003ממנה בשבת, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אסור להסתפק ממנה בשבת,\u0004 אלו \u0003דברי ר' שמעון.\u0004 ואילו \u0003ר' אחא מתיר\u0004 בכל מקרה. ותוהים: \u0003כלפי לייא\u0004 \u0005[הפוכים הדברים],\u0006 והלוא ר' שמעון הוא שמתיר בדיני מוקצה! \u0003אלא אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]\u0006 כך: אלו \u0003דברי ר' אחא, ור' שמעון מתיר.\u0004","\u0003תנא\u0004 \u0005[שנינו]:\u0006 \u0003כמה שיעור תבואה צבורה\u0004 שאמרו שהיא אוצר — \u0003לתך\u0004 (חצי כור). \u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רב נחומי בר זכריה מאביי: שיעור תבואה צבורה בכמה?\u0004 אמר לו: \u0003הרי\u0004 כבר \u0003אמרו: שיעור תבואה צבורה\u0004 — \u0003לתך.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003הני\u0004 \u0005[אלה]\u0006 \u0003ארבע וחמש קופות דקאמר\u0004 \u0005[שאמר],\u0006 האם \u0003בארבע וחמש קופות\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 מותר להוציאן, אבל \u0003טפי\u0004 \u0005[יותר]\u0006 — \u0003לא, אלמא למעוטי בהילוכא\u0004 \u0005[מכאן שלמעט בהילוך]\u0006 \u0003עדיף, או דילמא\u0004 \u0005[שמא]\u0006 \u0003למעוטי\u0004 \u0005[למעט]\u0006 ב\u0003משוי\u0004 (משא) \u0003עדיף,\u0004 ולכן, אם יכול לטלטל בכלים קטנים יותר — מותר לו, ובלבד שלא יטלטל יותר משיעור ארבע קופות.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה \u0003דתני חדא\u0004 \u0005[ששנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003מפנין אפילו ארבע וחמש קופות של כדי שמן ושל כדי יין. ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003בעשר ובחמש עשרה. מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא בזה נחלקו\u0006 שתי הברייתות\u0005],\u0006 \u0003דמר סבר מעוטי בהילוכא\u0004 \u0005[שחכם זה,\u0006 בברייתא הראשונה \u0005סבור\u0006 כי \u0005למעט בהילוך]\u0006 \u0003עדיף,\u0004 ומוטב להכביד במשא מאשר ללכת כמה פעמים. \u0003ומר סבר מעוטי במשוי\u0004 \u0005[וחכם זה,\u0006 בברייתא השניה, \u0005סבור\u0006 כי \u0005למעט במשא]\u0006 \u0003עדיף,\u0004 ומוטב ללכת פעמים אחדות במקום לשאת משא כבד בפעם אחת.","ודוחים: \u0003לא, דכולי עלמא מעוטי בהילוכא\u0004 \u0005[לדעת הכל למעט בהילוך]\u0006 \u0003עדיף, ומי סברת\u0004 \u0005[והאם סבור אתה]\u0006 כי \u0003\"בעשר ובחמש עשרה\"\u0004 על \u0003קופות\u0004 (סלים) \u0003קאי\u0004 \u0005[\u0006הוא \u0005עומד,\u0006 דן\u0005]?\u0006 לא, \u0003אכדין קאי\u0004 \u0005[על הכדים\u0006 הוא \u0005עומד,\u0006 דן\u0005],\u0006 ואין כלל מחלוקת בין הברייתות, \u0003ולא קשיא\u0004 \u0005[ואין\u0006 זה \u0005קשה],\u0006 אלא: \u0003הא\u0004 \u0005[זה]\u0006 שדיבר בחמש קופות — הרי זה באופן \u0003דמשתקלי חד חד\u0004 \u0005[שנלקחים\u0006 הכדים \u0005אחד אחד]\u0006 \u0003ב\u0004כל \u0003קופה, והא\u0004 \u0005[וזה]\u0006 שבעשר — הרי זה באופן \u0003דמישתקלי תרי תרי\u0004 \u0005[שנלקחים\u0006 הכדים \u0005שנים שנים]\u0006 בכל קופה, \u0003והא\u0004 — \u0003דמשתקלי תלתא תלתא\u0004 \u0005[וזו\u0006 — \u0005שנלקחים\u0006 הכדים \u0005שלושה שלושה],\u0006 \u0003ובדקורי\u0004 \u0005[ו\u0006כגון \u0005הכדים הקטנים]\u0006 מ\u0003הרפניא.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003הני\u0004 \u0005[אותן]\u0006 \u0003ארבע וחמש\u0004 קופות \u0003דקאמר\u0004 \u0005[שאמר]\u0006 שמותר לפנות, האם מספר זה הוא \u0003אף על גב דאית ליה אורחין טובא\u0004 \u0005[אף על פי שיש לו אורחים הרבה],\u0006 \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003הכל לפי\u0004 מספר \u0003האורחין,\u0004 ואם יש אורחים רבים מפנה יותר? \u0003ואם תמצי לומר\u0004 \u0005[תרצה לומר]\u0006 \u0003הכל לפי האורחין,\u0004 האם \u0003חד גברא מפני לכולהו\u0004 \u0005[אדם אחד מפנה לכל]\u0006 האנשים, \u0003או דילמא גברא גברא מפני לנפשיה\u0004 \u0005[שמא\u0006 כל \u0005אדם ואדם מפנה לעצמו]?\u0006","ואומרים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה ש\u0003אמר רבה\u0004 שכך \u0003אמר ר' חייא: פעם אחת הלך רבי למקום אחד, וראה\u0004 שה\u0003מקום דחוק לתלמידים, ויצא לשדה, ומצא שדה מלאה עומרים ועימר\u0004 (פינה מן העומרים) \u0003רבי\u0004 את \u0003כל השדה כולה. שמע מינה\u0004 \u0005[למד ממנה]\u0006 כי \u0003הכל לפי האורחין. ו\u0004כן","\u0003רב יוסף אמר\u0004 בשם \u0003ר' הושעיא: פעם אחת הלך ר' חייא למקום אחד וראה\u0004 שה\u0003מקום דחוק לתלמידים, ויצא לשדה ומצא שדה מלאה עומרים ועימר ר' חייא\u0004 את \u0003כל השדה כולה. שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003הכל לפי האורחין.\u0004","ומוסיפים: \u0003ועדיין תבעי\u0004 \u0005[תישאל]\u0006 \u0003לך:\u0004 האם \u0003חד גברא מפני ליה לכולא\u0004 \u0005[האם אדם אחד מפנה את הכל],\u0006 \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003כל גברא וגברא מפני לנפשיה\u0004 \u0005[אדם ואדם מפנה לעצמו]?\u0006","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה ששנינו: \u0003ועימר רבי.\u0004 הרי שאדם אחד עימר מעמר עבור אחרים! ודוחים מיד: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 וכי סבור אתה כי \u0003רבי\u0004 נשיא הדור \u0003בדנפשיה\u0004 \u0005[בעצמו]\u0006 \u0003עימר?! אלא\u0004 ודאי הכוונה ש\u0003צוה ועימר, ולעולם\u0004 יכול אתה לפרש ש\u0003כל חד וחד מפני לנפשיה\u0004 \u0005[אחד ואחד מפנה לעצמו].\u0006","שנינו במשנה שמפנים קופות של תבואה \u0003מפני האורחין\u0004 ולצורך בית המדרש. \u0003אמר ר' יוחנן: גדולה הכנסת אורחין כהשכמת בית המדרש.\u0004 שהרי השוותה אותם המשנה, \u0003דקתני\u0004 \u0005[ש\u0006הרי \u0005שנינו]\u0006 במשנה: \u0003\"מפני האורחין ומפני בטול בית המדרש\". ורב דימי מנהרדעא אמר:\u0004 גדולה הכנסת אורחים אפילו \u0003יותר מהשכמת בית המדרש, דקתני\u0004 \u0005[ש\u0006הרי \u0005שנינו]\u0006 במשנה קודם \u0003\"מפני האורחין\" והדר\u0004 \u0005[ו\u0006רק \u0005אחר כך]\u0006 \u0003\"ומפני בטול בית המדרש\".\u0004 וכיון שמדובר בהכנסת אורחים מביאים את מה ש\u0003אמר רב יהודה\u0004 שכך \u0003אמר רב: גדולה הכנסת אורחין\u0004 יותר \u0003מהקבלת פני\u0004 ה\u0003שכינה, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 כאשר ראה אברהם את אורחיו: \u0003\"ויאמר\u0004 אדוני \u0003אם נא מצאתי חן בעיניך אל נא תעבר\u0004 מעל עבדך\u0003\"\u0004 (בראשית יח, ג), ומפרשים שביקש מה' (מהשכינה) שימתין לו כביכול עד שיטפל באורחים כראוי. בענין זה \u0003אמר ר' אלעזר: בא וראה שלא כמדת הקדוש ברוך הוא מדת בשר ודם.\u0004 שהרי \u0003מדת בשר ודם אין קטן יכול לומר לגדול \"המתן עד שאבא אצלך\", ואילו בהקדוש ברוך הוא כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ויאמר\u0004 אדני \u0003אם נא מצאתי חן\u0004 בעיניך אל נא תעבור מעל עבדך\u0003\",\u0004 שבקש מה' שימתין לו מפני האורחים.","\u0003אמר רב יהודה בר שילא\u0004 שכך \u0003אמר ר' אסי\u0004 שכך \u0003אמר ר' יוחנן: ששה דברים אדם אוכל פירותיהן\u0004 (רווחיהם) \u0003בעולם הזה והקרן\u0004 (גוף ועיקר שכרו) \u0003קיימת לו לעולם הבא, ואלו הן: הכנסת אורחין, וביקור חולים, ועיון תפלה\u0004 בכוונה, \u0003והשכמת בית המדרש, והמגדל בניו\u0004 ומחנכם \u0003לתלמוד תורה, והדן את חברו לכף זכות.\u0004","ומקשים: \u0003איני\u0004 \u0005[וכן הוא]?!\u0006 \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]:\u0006 \u0003אלו דברים שאדם עושה אותם ואוכל פירותיהן בעולם הזה, והקרן קיימת לו לעולם הבא, ואלו הן: כיבוד אב ואם, וגמילות חסדים, והבאת שלום שבין אדם לחברו, ותלמוד תורה כנגד כולם.\u0004 ומכאן נסיק: \u0003הני\u0004 \u0005[אלה]\u0006 — \u0003אין\u0004 \u0005[כן],\u0006 ואולם \u0003מידי אחרינא\u0004 \u0005[דבר אחר]\u0006 — \u0003לא!\u0004"],["ומשיבים: \u0003הני נמי\u0004 \u0005[אלה גם כן],\u0006 הכנסת אורחים וביקור חולים, \u0003בגמילות חסדים שייכי\u0004 \u0005[שייכים,\u0006 נכללים\u0005].\u0006 \u0003לישנא אחרינא\u0004 \u0005[לשון אחר]:\u0006 \u0003הני בהני שייכי\u0004 \u0005[אלה באלה\u0006 הם \u0005שייכים],\u0006 כלומר, הדברים המרובים יותר כלולים מבחינת תוכנם בתוך הרשימה המצומצמת.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003הדן\u0004 את \u0003חבירו לכף זכות\u0004 — \u0003דנין אותו לזכות. ומעשה באדם אחד שירד מגליל העליון ונשכר\u0004 למלאכה \u0003אצל בעל הבית בדרום\u0004 ל\u0003שלש שנים. ערב יום הכפורים אמר לו\u0004 לבעל הבית: \u0003תן לי שכרי, ואלך ואזון את אשתי ובני. אמר לו\u0004 בעל הבית: \u0003אין לי מעות. אמר לו:\u0004 אם כן \u0003תן לי פירות\u0004 בשכרי. \u0003אמר לו: אין לי.\u0004 אמר לו השכיר: אם כן \u0003תן לי קרקע\u0004 בשכרי. ענה לו: \u0003אין לי.\u0004 אמר לו השכיר: \u0003תן לי בהמה\u0004 בשכרי. אמר לו: \u0003אין לי. תן לי כרים וכסתות\u0004 — \u0003אין לי. הפשיל\u0004 השכיר \u0003כליו לאחוריו, והלך לביתו בפחי נפש\u0004 (בצער).","\u0003לאחר הרגל\u0004 (סוכות) \u0003נטל בעל הבית\u0004 את \u0003שכרו\u0004 של השכיר \u0003בידו, ועמו משוי שלשה חמורים, אחד\u0004 טעון דברים \u0003של מאכל, ואחד של משתה, ואחד של מיני מגדים\u0004 (ממתקים), \u0003והלך לו לביתו\u0004 של הפועל. \u0003אחר שאכלו ושתו נתן לו\u0004 בעל הבית את \u0003שכרו.\u0004","\u0003אמר לו\u0004 בעל הבית לשכיר: \u0003בשעה שאמרת לי \"תן לי שכרי\" ואמרתי \"אין לי מעות\", במה חשדתני?\u0004 כלומר, כיצד הבנת את דברי, ומפני מה לא חשדתני שאני משתמט מלשלם לך? ענה לו, \u0003אמרתי: שמא פרקמטיא\u0004 (סחורה) \u0003בזול נזדמנה לך, ולקחת\u0004 (וקנית) אותה \u0003בהן\u0004 בכספים המגיעים לי ואין בידך כסף. שאל אותו: \u0003ובשעה שאמרת לי \"תן לי בהמה\", ואמרתי \"אין לי בהמה\", במה חשדתני?\u0004 ענה לו הפועל, \u0003אמרתי: שמא מושכרת\u0004 הבהמה \u0003ביד אחרים.\u0004 והוסיף ושאלו: \u0003בשעה שאמרת לי \"תן לי קרקע\", ואמרתי לך \"אין לי קרקע\", במה חשדתני?\u0004 ענה לו, \u0003אמרתי: שמא מוחכרת\u0004 הקרקע \u0003ביד אחרים היא,\u0004 ואין בעל הבית יכול להוציא את הקרקע מן החוכרים. ושאל עוד: \u0003ובשעה ש\u0004אמרת לי \"תן לי פירות ו\u0003אמרתי לך \"אין לי פירות\" במה חשדתני?\u0004 ענה לו, \u0003אמרתי: שמא אינן מעושרות\u0004 ולפי שעה אי אפשר לתת אותן. ושאלו: \u0003ובשעה שאמרתי לך \"אין לי כרים וכסתות\" במה חשדתני?\u0004 ענה לו, \u0003אמרתי: שמא הקדיש כל נכסיו לשמים\u0004 מסיבה כלשהי ולכן אין בידו כעת דבר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 בעל הבית: \u0003העבודה,\u0004 כלומר, נשבע בעבודת בית המקדש שבאמת \u0003כך היה\u0004 שלא היה אז כסף ברשותו, כי \u0003הדרתי\u0004 כלומר, נדרתי והקדשתי \u0003כל נכסי בשביל הורקנוס בני שלא עסק בתורה,\u0004 שנדר שלא להשאיר ביד בנו כל נכסים. \u0003וכשבאתי אצל חבירי בדרום\u0004 שהיו חכמי הדור \u0003התירו לי כל נדרי,\u0004 ואז יכול היה לבוא ולשלם מיד לפועלו. \u0003ואתה כשם שדנתני לזכות,\u0004 אף \u0003המקום\u0004 (השם) \u0003ידין אותך לזכות.\u0004","מעשה דומה מסופר \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003מעשה בחסיד אחד שפדה ריבה\u0004 (נערה) \u0003אחת בת ישראל\u0004 מן השבי, \u0003ו\u0004כשהגיעו \u0003למלון השכיבה תחת מרגלותיו.\u0004 ו\u0003למחר ירד וטבל\u0004 להיטהר לפני לימוד תורה ותפילה \u0003ושנה לתלמידיו.\u0004 והדבר למראית העין מעורר חשד כאילו שמר את הנערה לעצמו, ומה גם כשטבל בבוקר כדרך שטובלים לאחר ביאה.","\u0003ואמר להם\u0004 לתלמידיו: \u0003בשעה שהשכבתיה תחת מרגלותי, במה חשדתוני?\u0004 אמרו לו: \u0003אמרנו שמא יש בנו תלמיד שאינו בדוק לרבי\u0004 בהתנהגויותיו, ואין הרב רוצה להשאיר את הנערה בין התלמידים שאינו בטוח בהגינותם לענין זה.","אמר להם: \u0003בשעה שירדתי וטבלתי במה חשדתוני?\u0004 ענו לו: \u0003שמא מפני טורח הדרך אירע קרי לרבי. אמר להם: העבודה! כך היה. ואתם כשם שדנתוני לכף זכות\u0004 אף \u0003המקום ידין אתכם לכף זכות.\u0004","ועוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא בדומה לזה: \u0003פעם אחת הוצרך דבר אחד לתלמידי חכמים\u0004 שילכו וידונו בו \u0003אצל מטרוניתא אחת שכל גדולי רומי מצויין אצלה.\u0004 שרצו לברר דברים בעניני הכלל ולבקש דבר הנוגע לכלל ישראל מן השלטונות. \u0003אמרו: מי ילך? אמר להם ר' יהושע: אני אלך.\u0004","\u0003הלך ר' יהושע ותלמידיו\u0004 אליה. \u0003כיון שהגיע\u0004 עם תלמידיו \u0003לפתח ביתה חלץ תפיליו ברחוק ארבע אמות\u0004 מן הפתח, \u0003ונכנס ונעל הדלת בפניהן. אחר שיצא ירד וטבל ושנה לתלמידיו.\u0004 ולכאורה הדברים נראים כאילו היה כאן מעשה שאינו מהוגן.","\u0003ואמר להן\u0004 לתלמידיו: \u0003בשעה שחלצתי תפילין, במה חשדתוני?\u0004 אמרו לו, \u0003אמרנו: כסבור רבי, לא יכנסו דברי קדושה במקום טומאה\u0004 ומשום כך אין ראוי להכניס לשם תפילין.","שוב שאל: ו\u0003בשעה שנעלתי\u0004 את הדלת, \u0003במה חשדתוני?\u0004 אמרו לו, \u0003אמרנו: שמא דבר מלכות יש בינו לבינה,\u0004 שאין ראוי לגלותו.","ושאלם: ו\u0003בשעה שירדתי וטבלתי במה חשדתוני,\u0004 אמרו לו, \u0003אמרנו: שמא ניתזה צינורא\u0004 (טיפת רוק) \u0003מפיה על בגדיו של רבי,\u0004 וכיון שגזרו שיהיו הנכרים כזבים הרי הם מטמאים אף ברוק. \u0003אמר להם\u0004 ר' יהושע: \u0003העבודה! כך היה.\u0004 ו\u0003כשם שדנתוני לזכות\u0004 כך \u0003המקום\u0004 (השם) \u0003ידין אתכם לזכות.\u0004","שנינו במשנה ש\u0003מפנין תרומה טהורה\u0004 בשבת. ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה כגון \u0003דמנחה\u0004 \u0005[שמונחת]\u0006 \u0003ביד ישראל. מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003כיון דלא חזיא ליה\u0004 \u0005[שאינה ראויה לו]\u0006 לישראל לאכילה \u0003אסור\u0004 אף לטלטלה בשבת, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 כי \u0003כיון דחזיא\u0004 \u0005[שראויה]\u0006 לאכילה \u0003לכהן\u0004 — \u0003שפיר דמי\u0004 \u0005[יפה הדבר],\u0006 מותר לטלטלה בשבת.","\u0003ו\u0004עוד שנינו במשנה שמותר לטלטל \u0003דמאי.\u0004 ושואלים: \u0003דמאי, הא לא חזי ליה\u0004 \u0005[הרי אינו ראוי לו]\u0006 לאכילה! ומשיבים: \u0003כיון דאי בעי מפקר ליה לנכסיה, והוה\u0004 \u0005[שאם ירצה יפקיר את נכסיו, ויהיה]\u0006 \u0003עני, וחזיא ליה\u0004 \u0005[ו\u0006יהיה \u0005הדמאי\u0006 \u0005ראוי לו],\u0006 \u0003השתא נמי חזי ליה\u0004 \u0005[עכשיו גם כן ראוי לו].\u0006 ומנין שהעני מותר באכילת דמאי? — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מאכילין את העניים דמאי ואת האכסניא\u0004 (אנשי הצבא) \u0003דמאי. ואמר רב הונא: תנא\u0004 \u0005[שנינו],\u0006 \u0003בית שמאי אומרים: אין מאכילין את העניים דמאי ואת האכסניא דמאי. ובית הלל אומרים: מאכילין את העניים דמאי ואת האכסניא דמאי,\u0004 וכידוע הלכה כבית הלל.","\u0003ו\u0004עוד שנינו במשנה שמותר לטלטל \u0003מעשר ראשון שניטלה תרומתו.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 והלא חולין גמורים הם! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא לאופן \u0003שהקדימו\u0004 הלוי לכהן \u0003בשבולים\u0004 שמיד כשהביאו את התבואה לגורן, ולפני שדשו אותה לקח הלוי מעשר ראשון, \u0003ונטלה הימנו\u0004 (ממנו, ממעשר זה) \u0003תרומת מעשר\u0004 וניתנה לכהן, \u0003ו\u0004אולם עדיין \u0003לא נטלה הימנו,\u0004 מן התבואה, \u0003תרומה גדולה\u0004 שהרי הכהן לא בא עדיין.","\u0003וכי הא\u0004 \u0005[וכמו זה]\u0006 ש\u0003אמר ר' אבהו\u0004 שכך \u0003אמר ריש לקיש: מעשר ראשון שהקדימו\u0004 הלוי לכהן \u0003בשבולין\u0004 — \u0003פטור מ\u0004להפריש \u0003תרומה גדולה, ש\u0004כן \u0003נאמר: \"והרמתם ממנו תרומת ה' מעשר מן המעשר\"\u0004 (במדבר יח, כו), ומלשון הכתוב נלמד: \u0003מעשר מן המעשר\u0004 (תרומת מעשר) \u0003אמרתי לך, ו\u0004אולם \u0003לא תרומה גדולה ו\u0004גם \u0003תרומת מעשר מן המעשר.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: אי הכי\u0004 \u0005[אם כך]\u0006 שאנו סומכים על לימוד זה, \u0003אפילו הקדימו\u0004 הלוי \u0003בכרי\u0004 לאחר דישת התבואה \u0003נמי ליפטר\u0004 \u0005[גם כן שיפטר]\u0006 הלוי מלתת תרומה גדולה! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עליך אמר קרא\u0004 \u0005[המקרא]\u0006 \u0003\"מכל מתנתיכם תרימו\u0004 את כל תרומת ה' מכל חלבו את מקדשו ממנו\u0003\"\u0004 (במדבר יח, כט), כלומר, יש ריבוי נוסף (מכל מתנותיכם) והוא המחייב לתת תרומה גדולה אף ממתנות הלויים.","ושאל רב פפא: \u0003ומה ראית\u0004 לומר שאם הקדימו בכרי — חייב לתת תרומה גדולה, ואם הקדימו בגורן — אינו חייב בה? ותירץ לו: \u0003האי\u0004 \u0005[זה\u0006 שבכרי\u0005]\u0006 — \u0003אידגן\u0004 \u0005[נעשה דגן],\u0006 ובדגן מפורשת חובת הפרשת תרומה גדולה, \u0003והאי\u0004 \u0005[וזה]\u0006 — עדיין \u0003לא אידגן\u0004 \u0005[נעשה דגן],\u0006 ועדיין לא חלה עליו חובה זו.","שנינו במשנה ש\u0003מעשר שני\u0004 שנפדה מותר בטלטול. ושואלים: והלא זהו \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו אלא לאופן \u0003שנתן את הקרן\u0004 (דמי המעשר) \u0003ו\u0004עדיין \u0003לא נתן את החומש\u0004 שצריך להוסיף עליו בשעת פדיון. ו\u0003הא קא משמע לן\u0004 \u0005[ו\u0006דבר \u0005זה השמיע לנו]\u0006 ש\u0003אין חומש מעכב,\u0004 והמעשר נעשה חולין משעת נתינת הקרן.","\u0003ו\u0004עוד שנינו במשנה שמטלטלים בשבת את \u0003התורמס היבש\u0004 שהוא מאכל בהמה. ומעירים: \u0003דווקא\u0004 כשהוא \u0003יבש, אבל\u0004 כאשר הוא \u0003לח\u0004 — \u0003לא\u0004 הותר לטלטלו. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003כיון דמריר\u0004 \u0005[ש\u0006הוא \u0005מר]\u0006 ביותר \u0003לא אכלה\u0004 \u0005[אוכלת]\u0006 אותו בהמה."],["שנינו במשנה: \u0003אבל לא\u0004 מטלטלים בשבת \u0003את הטבל.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו אלא \u0003בטבל טבול\u0004 (האסור משום טבל) רק \u0003מדרבנן\u0004 \u0005[מדברי סופרים],\u0006 וכגון \u0003שזרעו\u0004 את הצמח \u0003בעציץ שאינו נקוב\u0004 שאין דינו כקרקע.","\u0003ו\u0004עוד שנינו במשנה ש\u0003לא\u0004 מטלטלים בשבת \u0003מעשר ראשון\u0004 שלא ניטלה ממנו תרומתו. ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו אלא לאופן \u0003שהקדימו\u0004 למעשר הראשון \u0003בכרי, שנטל ממנו\u0004 בעליו \u0003מעשר ו\u0004אולם עדיין \u0003לא נטלה ממנו תרומה גדולה.\u0004 ו\u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003כדאמר ליה\u0004 \u0005[כפי שאמר לו]\u0006 קודם \u0003רב פפא לאביי\u0004 שבאופן כזה ייפטר בכלל מלהפריש תרומה גדולה, על כן \u0003קא משמע לן כדשני ליה\u0004 \u0005[השמיע לנו\u0006 שהוא \u0005כמו שתירץ לו]\u0006 \u0003אביי\u0004 שיש ריבוי נוסף לחייב אף באופן זה.","\u0003ו\u0004עוד שנינו במשנה ש\u0003לא\u0004 מטלטלים בשבת \u0003את מעשר שני\u0004 והקדש שלא נפדו. ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו אלא לאופן ש\u0003נפדו\u0004 המעשר שני או ההקדש, \u0003ו\u0004אולם \u0003לא נפדו כהלכתן.\u0004 ומפרטים: \u0003מעשר\u0004 — כגון \u0003שפדאו על גבי\u0004 (אגב, על) \u0003אסימון\u0004 (מטבע ללא צורה), \u0003דרחמנא אמר\u0004 \u0005[ש\u0006הרי \u0005התורה אמרה]\u0006 \"ונתת בכסף \u0003וצרת הכסף בידך\u0004 והלכת אל המקום אשר יבחר ה' אלהיך בו\" (דברים יד, כה), ומהלשון \"וצרת הכסף\" דרשו חכמים שצריך הכסף לפדיון המעשר להיות \u0003דבר שיש בו צורה,\u0004 אבל מטבעות ללא צורה — פסולים. ו\u0003הקדש\u0004 שלא פדאו כראוי — \u0003שחיללו על גבי קרקע, דרחמנא אמר\u0004 \u0005[ש\u0006הרי \u0005התורה אמרה]\u0006 \u0003\"ונתן הכסף וקם לו\",\u0004 אבל אם לא נתן בפדיון ההקדש כסף אלא קרקע — אין זה מועיל לפדות את ההקדש.","\u0003ו\u0004עוד שנינו במשנה ש\u0003לא\u0004 מטלטלים בשבת \u0003את הלוף. תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003מטלטלין\u0004 בשבת \u0003את החצב מפני שהוא מאכל לצביים, ואת החרדל מפני שהוא מאכל ליונים. רבן שמעון בן גמליאל אומר: אף מטלטלין שברי זכוכית מפני שהוא מאכל לנעמיות\u0004 (בנות היענה).","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' נתן\u0004 לרבן שמעון בן גמליאל: \u0003אלא מעתה\u0004 אף \u0003חבילי זמורות יטלטלו מפני שהוא מאכל לפילין!\u0004 ומשיבים, \u0003רבן שמעון בן גמליאל\u0004 היה מתרץ: \u0003נעמיות\u0004 — \u0003שכיחי\u0004 \u0005[מצויות],\u0006 ואילו \u0003פילין\u0004 — \u0003לא שכיחי\u0004 \u0005[אינם מצויים].\u0006","\u0003אמר אמימר: ו\u0004מה שהתיר רבן שמעון בן גמליאל טלטול שברי זכוכית \u0003הוא\u0004 דווקא באופן \u0003דאית ליה\u0004 \u0005[שיש לו]\u0006 \u0003נעמיות. אמר רב אשי לאמימר: אלא\u0004 מה \u0003דקאמר ליה\u0004 \u0005[שאמר לו]\u0006 \u0003ר' נתן לרבן שמעון בן גמליאל\u0004 ש\u0003חבילי זמורות\u0004 גם כן \u0003יטלטל מפני שהוא מאכל לפילין,\u0004 ומה חידש בכך, והלא \u0003אי אית ליה\u0004 \u0005[אם יש לו]\u0006 \u0003פילין\u0004 — \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא\u0004 יתן להם את מזונם? \u0003אלא\u0004 ודאי עליך לפרש שדיבר ב\u0003ראוי\u0004 למאכל פילים ואין לו פילים, \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 בשברי זכוכית מדובר ב\u0003ראוי\u0004 ואין לו נעמיות.","\u0003אמר אביי: רבן שמעון בן גמליאל ור' שמעון ור' ישמעאל ור' עקיבא כולהו סבירא להו\u0004 \u0005[כולם סבורים הם]\u0006 כי \u0003כל ישראל בני מלכים הם,\u0004 ואין לומר על אדם מישראל שאין ראוי לו דבר של הידור יתר.","\u0003רבן שמעון בן גמליאל\u0004 — \u0003הא דאמרן\u0004 \u0005[זו שאמרנו]\u0006 במשנתנו שהותר הלוף בטלטול משום שהוא מאכל עורבים, וכאילו לכל אדם מישראל יש עורבים ברשותו.","\u0003ר' שמעון\u0004 — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003בני מלכים סכין\u0004 בשבת \u0003על גבי מכותיהן שמן וורד, שכן דרכן של בני מלכים לסוך בחול\u0004 אפילו שלא על גבי מכה. \u0003ר' שמעון אומר: כל ישראל בני מלכים הם\u0004 וכולם יכולים לסוך בשמן זה בשבת.","\u0003ר' ישמעאל ור' עקיבא\u0004 — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הרי שהיו נושין בו\u0004 באדם \u0003אלף מנה, ולבוש איצטלא\u0004 (מעיל) \u0003בת\u0004 (ששווה) \u0003מאה מנה\u0004 — \u0003מפשיטין אותו\u0004 את האיצטלא הזאת ומוכרים אותה, \u0003ומלבישין אותו איצטלא הראויה לו\u0004 לפי עושרו. ו\u0003תנא\u0004 \u0005[ושנינו]\u0006 \u0003משום\u0004 (בשם) \u0003ר' ישמעאל, ותנא\u0004 \u0005[ו\u0006כן \u0005שנינו]\u0006 \u0003משום ר' עקיבא: כל ישראל ראויין לאותה איצטלא\u0004 ואין לומר שאינה ראויה לאדם זה. ונוהגים בה כבשאר מלבוש החיוני לאדם, וכלל בידינו שאין מוכרים מלבושים חיוניים על מנת לשלם חוב.","שנינו במשנה ש\u0003חבילי קש וחבילי עצים\u0004 אם התקינם למאכל בהמה — מטלטלים אותם, ואם לא התקינם לכך — אין מטלטלים אותם\u0003. תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003חבילי קש וחבילי עצים וחבילי זרדים, אם התקינן למאכל בהמה\u0004 — \u0003מטלטלין אותן\u0004 בשבת, \u0003ואם לאו\u0004 \u0005[לא]\u0006 התקינם — \u0003אין מטלטלין אותן. רבן שמעון בן גמליאל אומר: חבילין הניטלין ביד אחד\u0004 — \u0003מותר לטלטלן\u0004 שאין זו טירחה יתירה, ואם אינם מיטלטלים אלא \u0003בשתי ידים\u0004 — \u0003אסור לטלטלן.\u0004","הכניס \u0003חבילי סיאה אזוב וקורנית\u0004 שהם צמחים ריחניים הראויים גם למאכל אדם, אם \u0003הכניסן לעצים\u0004 (לצורך הסקה) — \u0003אין מסתפק\u0004 (משתמש) \u0003מהן בשבת\u0004 לאכילה, ואם הכניסם \u0003למאכל בהמה\u0004 — \u0003מסתפק\u0004 אף הוא \u0003מהן בשבת.\u0004","\u0003וקוטם\u0004 (קוטף) \u0003ביד ואוכל, ובלבד שלא יקטום בכלי. ומולל\u0004 ומוציא את הגרעינים בידו \u0003ואוכל, ובלבד שלא ימלול בכלי הרבה,\u0004 שנראה הדבר כמלאכה מרובה, אלו \u0003דברי ר' יהודה. וחכמים אומרים: מולל בראשי אצבעותיו\u0004 בדרך שינוי \u0003ואוכל, ובלבד שלא ימלול בידו הרבה כדרך שהוא עושה בחול.\u0004","\u0003וכן\u0004 הדין \u0003באמיתא וכן בפיגם וכן בשאר מיני תבלין.\u0004 ושאלו חכמים: \u0003מאי\u0004 \u0005[מהי]\u0006 \u0003אמיתא\u0004 זו? ואמרו שהוא הקרוי בארמית \u0003\"ניניא\".\u0004 ומהי \u0003סיאה? אמר רב יהודה:\u0004 הוא הצמח הקרוי \u0003\"צתרי\". אזוב\u0004 — הקרוי בארמית \u0003\"אברתא\". קורנית\u0004 — \u0003\"קורניתא\" שמה\u0004 בארמית.","ומקשים: \u0003והא ההוא\u0004 \u0005[והרי אותו\u0006 אדם\u0005]\u0006 שבא למכור ו\u0003אמר להו\u0004 \u0005[להם]\u0006 לשומעים: \u0003מאן בעי קורניתא\u0004 \u0005[מי רוצה קורנית]?\u0006 \u0003ואישתכח\u0004 \u0005[ונמצא]\u0006 שהוא מוכר \u0003חשי,\u0004 והרי שקורניתא איננה קורנית! \u0003אלא\u0004 יש לפרש: \u0003סיאה\u0004 היא \u0003צתרי, אזוב\u0004 הוא \u0003אברתא,\u0004 ו\u0003קורניתא\u0004 הוא \u0003חשי.\u0004","\u0003איתמר\u0004 \u0005[נאמר]\u0006 בשם חכמים: \u0003בשר מליח מותר לטלטלו בשבת\u0004 שכן ראוי הוא לאכילה. \u0003בשר תפל\u0004 שלא נמלח עדיין, \u0003רב הונא אמר: מותר לטלטלו,\u0004 ו\u0003רב חסדא אמר: אסור לטלטלו.\u0004","ושואלים: ו\u0003רב הונא\u0004 האם \u0003אמר\u0004 כי \u0003מותר לטלטלו? והא\u0004 \u0005[והרי]\u0006 \u0003רב הונא תלמיד\u0004 של \u0003רב הוה\u0004 \u0005[היה],\u0006 \u0003ורב\u0004 הלא \u0003כ\u0004שיטת \u0003ר' יהודה סבירא ליה\u0004 \u0005[סבור הוא]\u0006 \u0003דאית ליה\u0004 \u0005[שיש לו,\u0006 מקבל\u0005]\u0006 ר' יהודה את דין \u0003מוקצה,\u0004 וכשיטה זו \u0005תהא\u0006 אם כן \u0005אף דעתו של רב, ואיך אומר רב הונא תלמידו שמותר לטלטלו?!\u0006","ומשיבים: \u0003במוקצה לאכילה,\u0004 כלומר, לענין הקצאת דבר מאכל מן הדעת, \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 רב \u0003כ\u0004שיטת \u0003ר' יהודה,\u0004 שאסור באכילה ואילו \u0003במוקצה\u0004 לענין האיסור \u0003לטלטל סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כ\u0004שיטת \u0003ר' שמעון\u0004 שאינו סובר את דין מוקצה ומתיר בטלטול.","שנינו ש\u0003רב חסדא אמר\u0004 בענין בשר תפל ש\u0003אסור לטלטלו\u0004 בשבת. ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב יצחק בר אמי איקלע לבי\u0004 \u0005[הזדמן לבית]\u0006 \u0003רב חסדא, וחזא ההוא בר אווזא דהוו קא מטלטלו ליה משמשא לטולא\u0004 \u0005[וראה\u0006 בשר \u0005ברווז אחד שהיו מטלטלים אותו משמש לצל]\u0006 שלא יתקלקל, \u0003ואמר רב חסדא\u0004 לבני ביתו: \u0003חסרון כיס קא חזינן הכא\u0004 \u0005[רואה אני כאן],\u0006 כלומר, עליכם לדאוג שלא ימצא זמן מרובה בשמש שלא ייפסד. נמצא שמותר לדעתו לטלטל בשר שאינו ראוי לאכילה! ומשיבים: \u0003שאני בר אווזא, דחזי לאומצא\u0004 \u0005[שונה ברווז, הראוי\u0006 להיאכל \u0005בשר חי,\u0006 כמות שהוא ללא בישול\u0005].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003דג מליח\u0004 — \u0003מותר לטלטלו\u0004 בשבת, \u0003דג תפל\u0004 — \u0003אסור לטלטלו. בשר, בין\u0004 שהוא \u0003תפל ובין\u0004 שהוא \u0003מליח\u0004 — \u0003מותר לטלטלו, וסתמא\u0004 \u0005[סתם\u0006 ברייתא \u0005זו]\u0006 \u0003כ\u0004שיטת \u0003ר' שמעון.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מטלטלין\u0004 בשבת \u0003את העצמות מפני שהוא מאכל לכלבים.\u0004"],["\u0003בשר תפוח\u0004 (שמתחיל להסריח) — מותר לטלטלו, \u0003מפני שהוא מאכל לחיה, מים מגולין\u0004 שיש לחשוש ששתה מהן נחש והטיל בהן ארס — מותר לטלטלם, \u0003מפני שהן ראויין לחתול,\u0004 שאינו ניזוק כל כך מארס נחשים. \u0003רבן שמעון בן גמליאל אומר: כל עצמן\u0004 של מים מגולים אלה \u0003אסור לשהותן מפני הסכנה,\u0004 שמא ישכח אדם וישתה מהן ויסתכן.","\u0003כופין\u0004 (הופכים) בשבת \u0003את הסל לפני האפרוחים כדי שיעלו וירדו\u0004 בו. וכן \u0003תרנגולת שברחה\u0004 מהבית ורוצים להחזירה — \u0003דוחין\u0004 (דוחפים) \u0003אותה\u0004 אפילו בידים \u0003עד שתכנס\u0004 חזרה לתוכו.","ו\u0003מדדין\u0004 (מסייעים ללכת) \u0003עגלין וסייחין.\u0004 וכן \u0003אשה מדדה את בנה. אמר ר' יהודה: אימתי\u0004 מותר — \u0003בזמן שהוא,\u0004 התינוק בעצמו \u0003נוטל\u0004 רגל \u0003אחת ומניח אחת, אבל אם היה גורר\u0004 את שתי רגליו — \u0003אסור,\u0004 מפני שהיא כנושאת אותו ברשות הרבים.","\u0003אמר רב יהודה\u0004 שכך \u0003אמר רב: בהמה שנפלה לאמת\u0004 (תעלת) \u0003המים\u0004 — \u0003מביא כרים וכסתות\u0004 וזורקם לאמת המים \u0003ומניח תחתיה, ואם עלתה\u0004 באמצעותם — \u0003עלתה.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים על כך]\u0006 ממה ששנינו בתוספתא: \u0003בהמה שנפלה\u0004 בשבת \u0003לאמת המים\u0004 — \u0003עושה לה פרנסה\u0004 (מזון) \u0003במקומה בשביל שלא תמות.\u0004 נמצא אם כן ש\u0003פרנסה\u0004 — \u0003אין\u0004 \u0005[כן,\u0006 מותר\u0005],\u0006 ואולם \u0003כרים וכסתות\u0004 — \u0003לא!\u0004","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 שיש לחלק ולומר כי \u0003הא\u0004 \u0005[זו]\u0006 ששנינו שעושה לה פרנסה — הרי זה במקרה ש\u0003אפשר בפרנסה,\u0004 ואילו \u0003הא\u0004 \u0005[זו]\u0006 ששנינו שיכול אפילו להניח לה כרים וכסתות — הרי זה כש\u0003אי אפשר בפרנסה,\u0004 אם \u0003אפשר בפרנסה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 יפרנסנה, \u0003ואי לא\u0004 \u0005[ואם אי\u0006 אפשר\u0005]\u0006 בפרנסה — \u0003מביא כרים וכסתות ומניח תחתיה.\u0004","ומקשים: \u0003והא קא\u0004 \u0005[והרי הוא]\u0006 \u0003מבטל\u0004 בהנחת הכרים והכסתות \u0003כלי\u0004 הראוי לשימוש \u0003מהיכנו\u0004 (מן השימוש לו הוא מיועד ומוכן) בשבת, ודומה הדבר למלאכת סתירה! ומשיבים: \u0003סבר\u0004 \u0005[סבור]\u0006 חכם זה כי האיסור ב\u0003מבטל כלי מהיכנו\u0004 הוא רק \u0003דרבנן\u0004 \u0005[מדברי סופרים],\u0006 ואילו איסור \u0003צער בעלי חיים\u0004 הוא \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003ואתי דאורייתא ודחי דרבנן\u0004 \u0005[ובאה\u0006 מצוה \u0005מן התורה ודוחה\u0006 מצוה \u0005מדברי סופרים].\u0006","שנינו במשנה ש\u0003תרנגולת שברחה\u0004 דוחים אותה למקומה. ומכאן נדייק: \u0003דוחין\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 ואולם \u0003מדדין,\u0004 לסייע לה בהליכתה — \u0003לא.\u0004 ומעירים: \u0003תנינא להא, דתנו רבנן\u0004 \u0005[שנינו לזו, ש\u0006כן \u0005שנו חכמים]:\u0006 \u0003מדדין\u0004 בשבת \u0003בהמה חיה ועוף בחצר, אבל לא את התרנגולת.\u0004","ושואלים: \u0003תרנגולת מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא\u0004 ידדה אותה? \u0003אמר אביי: משום דמקפיא נפשה\u0004 \u0005[שמגביהה\u0006 את \u0005עצמה]\u0006 ונמצא שבכך הוא נושא אותה ממש ולא רק מסייע לה בהילוכה.","\u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003מדדין בהמה וחיה ועוף בחצר אבל לא ברשות הרבים, והאשה מדדה את בנה ברשות הרבים, ואין צריך לומר\u0004 שמותר \u0003בחצר. ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003אין עוקרין\u0004 רגלי \u0003בהמה וחיה ועוף\u0004 להרימם לגמרי \u0003בחצר, אבל דוחין בהן שיכנסו.\u0004","ותחילה מבררים ברייתא אחרונה זו: \u0003הא גופא קשיא\u0004 \u0005[היא עצמה קשה]:\u0006 שהרי \u0003אמרת\u0004 ש\u0003אין עוקרין,\u0004 ומשמע: \u0003אבל דדויי\u0004 \u0005[לדדות]\u0006 — \u0003מדדינן\u0004 \u0005[מדדים],\u0006 ואחר כך \u0003הדר\u0004 \u0005[חזרת]\u0006 ו\u0003אמרת\u0004 ש\u0003דוחין,\u0004 ומשמעו: \u0003דוחין\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 ואולם \u0003מדדין\u0004 — \u0003לא! אמר אביי: סיפא\u0004 \u0005[בסוף]\u0006 שמשתמע ממנו שאין מדדים \u0003אתאן\u0004 \u0005[באנו,\u0006 מדובר בו\u0005],\u0006 בדין \u0003תרנגולת,\u0004 שאותה, כאמור, אין לדדות.","וכיון שדובר בצד המיוחד שיש בנשיאת תרנגולת, מביאים את מה ש\u0003אמר אביי: האי מאן דשחיט\u0004 \u0005[מי ששוחט]\u0006 \u0003תרנגולת\u0004 — \u0003לכבשינהו לכרעיה בארעא, אי נמי נידל להו מידל\u0004 \u0005[שיכבוש\u0006 היטב \u0005רגליה בקרקע, או גם כן ירים אותן לגמרי\u0006 באויר\u0005],\u0006 שאם לא יעשה כן, יש לחשוש \u0003דדילמא מנח להו לטופריה בארעא, ועקר להו\u0004 \u0005[שמא יניח\u0006 התרנגול \u0005את צפרניו בקרקע\u0006 ויוכל לפרכס \u0005ו\u0006בתוך שחיטה \u0005יעקור אותם]\u0006 את ה\u0003סימנים,\u0004 הקנה והוושט, ממקומם, ואז תהא השחיטה פסולה והתרנגולת נבילה.","\u0003אין מילדין את הבהמה\u0004 אפילו \u0003ביום טוב,\u0004 וכל שכן בשבת, \u0003אבל מסעדין\u0004 (עוזרים) לה ללדת. \u0003ומילדין את האשה\u0004 אפילו \u0003בשבת, וקורין לה\u0004 (בשבילה) \u0003חכמה\u0004 (מיילדת) \u0003ממקום למקום\u0004 אפילו כשיש בכך חילול שבת, \u0003ומחללין עליה,\u0004 על האשה היולדת, \u0003את השבת, וקושרין את הטיבור\u0004 של הולד הנולד בשבת. \u0003ר' יוסי אומר: אף חותכין\u0004 את הטבור. \u0003וכל צרכי מילה\u0004 לתינוק שצריך \u0003למולו בו ביום, עושין בשבת.\u0004","שואלים: \u0003כיצד מסעדין\u0004 בלידת בהמה? \u0003רב יהודה אמר: אוחז את הולד\u0004 כדי \u0003שלא יפול לארץ, רב נחמן אמר: דוחק בבשר\u0004 מסביב לבית הרחם \u0003כדי שיצא הולד.\u0004","\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב יהודה: כיצד מסעדין\u0004 בלידת בהמה? \u0003אוחזין את הולד שלא יפול לארץ, ונופח לו בחוטמו\u0004 שייצא הריר החוסם את דרכי הנשימה ויתחיל לנשום, \u0003ונותן לו דד\u0004 אמו \u0003לתוך פיו כדי שינק.\u0004","\u0003אמר רבן שמעון בן גמליאל: מרחמין היינו על בהמה טהורה ביום טוב\u0004 לסייע לולד. ושואלים: \u0003היכי עביד\u0004 \u0005[איך\u0006 הוא \u0005עושה]?\u0006 כלומר, מה פירוש \"מרחמים\"? \u0003אמר אביי:\u0004 אם אין האם מקרבת את ילדה ומטפלת בו \u0003מביא בול\u0004 (גוש) \u0003של מלח, ומניח לה\u0004 אותו לבהמה \u0003בתוך הרחם, כדי ש\u0004תצטער ובתוך כך \u0003תזכור צערה\u0004 בלידה \u0003ותרחם עליו.\u0004 וכן \u0003מזלפין מי שליא על גבי\u0004 ה\u0003ולד, כדי שתריח ריחו ותרחם עליו. ודוקא\u0004 בהמה \u0003טהורה, אבל טמאה\u0004 — \u0003לא.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 בהמה טמאה לא התירו לעשות כן? ומשיבים: בהמה \u0003טמאה לא מרחקא ולדא\u0004 \u0005[מרחקת\u0006 את \u0005הולד],\u0006 \u0003ואי מרחקא ולדא\u0004 — \u0003לא מקרבא\u0004 \u0005[ואם מרחקת את ולדה\u0006 — שוב \u0005אינה מקרבת\u0006 אותו\u0005]\u0006 ואין תועלת באמצעים אלה.","שנינו במשנה ש\u0003מילדין את האשה,\u0004 ומחללים עליה אפילו את השבת. ושואלים: \u0003מכדי תנא ליה\u0004 \u0005[הרי שנה לו\u0006 במשנה\u0005]\u0006 במפורש: \u0003מילדין את האשה וקורין לה חכמה\u0004 (קוראים בשבילה מיילדת) \u0003ממקום למקום, ו\u0004המילים \u0003\"מחללין עליה את השבת\" לאתויי מאי\u0004 \u0005[להביא,\u0006 להוסיף, את \u0005מה]\u0006 הן מובאות כאן? והלא לכאורה כל מעשה של חילול השבת הבא בחשבון לצורך הלידה כבר שנינו!","ומשיבים: \u0003לאתויי הא דתנו רבנן\u0004 \u0005[להביא\u0006 את \u0005מה ששנו חכמים]\u0006 עוד בענין זה: \u0003אם היתה צריכה\u0004 היולדת \u0003לנר\u0004 — \u0003חבירתה מדלקת לה את הנר\u0004 בשבת. \u0003ואם היתה צריכה לשמן\u0004 — \u0003חבירתה מביאה לה שמן\u0004 דרך רשות הרבים \u0003ביד\u0004 בתוך כף ידה, ולא בכלי, כרגיל, כדי לעשות בשינוי, \u0003ואם אינו ספק\u0004 (מספיק) \u0003ביד\u0004 — \u0003מביאה בשערה, ואם אינו ספק בשערה\u0004 — \u0003מביאה לה בכלי\u0004 כרגיל.","שנינו קודם ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003אם היתה צריכה\u0004 היולדת בשבת \u0003לנר\u0004 — \u0003חבירתה\u0004 היתה \u0003מדלקת לה את הנר.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו להיאמר אלא \u0003ב\u0004יולדת \u0003סומא\u0004 (עיוורת), \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003כיון דלא חזיא\u0004 \u0005[שאינה רואה]\u0006 אפילו באור — \u0003אסור\u0004 להביא לה נר כלל, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 כי מאחר ו\u0003איתובי מיתבא\u0004 \u0005[ומתיישבת]\u0006 \u0003דעתה\u0004 בכך והדבר מרגיע אותה, \u0003מותר.\u0004 שכן היא \u0003סברא\u0004 \u0005[סבורה]:\u0006 \u0003אי איכא מידי\u0004 \u0005[אם יש דבר]\u0006 שיש לעשותו במהלך הלידה — \u0003חזיא\u0004 \u0005[רואה]\u0006 \u0003חבירתה\u0004 באמצעות הנר \u0003ועבדה\u0004 \u0005[ועושה]\u0006 \u0003לי.\u0004","עוד שנינו ש\u0003אם היתה צריכה\u0004 היולדת בשבת \u0003לשמן\u0004 — מביאה לה חבירתה שמן בשערותיה. ומקשים: מה הועילו בכך? \u0003תיפוק ליה\u0004 \u0005[תצא לו]\u0006 שאסור להביא בשיער \u0003משום\u0004 איסור \u0003סחיטה!\u0004 שהרי תצטרך לסחוט את השיער כדי להוציא ממנו את השמן, ואסור לסחוט בשבת!","\u0003רבה ורב יוסף דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003אין\u0004 דין \u0003סחיטה בשיער,\u0004 כי אין השיער סופג כשאר דברים הסופגים. \u0003רב אשי אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 ש\u0003יש\u0004 דין \u0003סחיטה בשיער,\u0004 אלא כאן אין הכוונה שמביאה לה ממש בשערה, אלא ש\u0003מביאה לה בכלי דרך\u0004 הקשור לה ב\u0003שערה,\u0004 שכל \u0003כמה\u0004 ש\u0003אפשר לשנויי\u0004 \u0005[לשנות]\u0006 בדבר שאינו הכרחי לפיקוח נפש — \u0003משנינן\u0004 \u0005[משנים אנו].\u0006","\u0003אמר רב יהודה\u0004 שכך \u0003אמר שמואל: חיה\u0004 (יולדת) \u0003כל זמן שהקבר\u0004 (בית הרחם) \u0003פתוח, בין\u0004 אם \u0003אמרה \"צריכה אני\u0004 שיחללו עלי את השבת\"\u0003, בין לא אמרה \"צריכה אני\u0004 שיחללו עלי את השבת\" — \u0003מחללין עליה את השבת,\u0004 שבדרך כלל יולדת היא במצב מסוכן ולצורך פיקוח נפש הותרה בשבת מלאכת איסור.","\u0003נסתם הקבר\u0004 (נסגר בית הרחם לאחר הלידה), \u0003בין\u0004 אם \u0003אמרה\u0004 היולדת"],["\u0003\"צריכה אני\", בין לא אמרה \"צריכה אני\"\u0004 — \u0003אין מחללין עליה את השבת.\u0004","\u0003רב אשי מתני הכי\u0004 \u0005[היה שונה כך]\u0006 כמו שאמרנו. ואילו \u0003מר זוטרא מתני הכי\u0004 \u0005[היה שונה כך],\u0006 בגירסה אחרת: \u0003אמר רב יהודה\u0004 שכך \u0003אמר שמואל: חיה כל זמן שהקבר פתוח, בין\u0004 אם \u0003אמרה \"צריכה אני\" ובין אמרה \"אין צריכה אני\"\u0004 — \u0003מחללין עליה את השבת.\u0004 ואולם גם כש\u0003נסתם הקבר,\u0004 אם \u0003אמרה \"צריכה אני\"\u0004 — \u0003מחללין עליה את השבת. לא אמרה \"צריכה אני\"\u0004 — \u0003אין מחללין עליה את השבת,\u0004 וכל שכן אם אמרה \"אין צריכה אני\".","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא למרימר:\u0004 מאחר שרואים אנו ש\u0003מר זוטרא מתני לקולא\u0004 \u0005[שונה\u0006 כאן \u0005להקל],\u0006 \u0003ורב אשי מתני לחומרא\u0004 \u0005[שונה להחמיר],\u0006 \u0003הלכתא כמאן\u0004 \u0005[הלכה כמי]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 מרימר: \u0003הלכה כמר זוטרא,\u0004 כיון שכלל בידינו בכל מקרה שיש חשש סכנה \u0003ספק נפשות להקל.\u0004 וכיון שכך יש להקל ככל האפשר גם בענין זה.","כיון שדובר בפתיחת הקבר שואלים: \u0003מאימתי\u0004 נחשבת תחילת \u0003פתיחת הקבר? אמר אביי: משעה שתשב\u0004 האשה \u0003על המשבר.\u0004 ואילו \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע אמר: משעה שהדם שותת ויורד, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 \u0003משעה שחברותיה נושאות אותה באגפיה\u0004 (בזרועותיה), שאין היא יכולה עוד ללכת בעצמה.","ושואלים עוד: \u0003עד מתי\u0004 נחשב זמן \u0003פתיחת הקבר? אמר אביי: שלשה ימים\u0004 אחר תחילת פתיחתו. \u0003רבא אמר משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב יהודה: שבעה, ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 כל \u0003שלשים\u0004 יום.","\u0003אמרי נהרדעי\u0004 \u0005[אמרו\u0006 חכמי \u0005נהרדעא]:\u0006 \u0003חיה\u0004 יש בה חילוקי דינים בין \u0003שלשה\u0004 ו\u0003שבעה ושלשים\u0004 יום לאחר לידתה. ומפרט: \u0003שלשה\u0004 ימים ראשונים מגמר הלידה, \u0003בין\u0004 אם \u0003אמרה \"צריכה אני\u0004 שיחללו עלי את השבת \u0003\", ובין\u0004 אם \u0003אמרה \"לא צריכה אני\"\u0004 — \u0003מחללין עליה את השבת.\u0004 כל \u0003שבעה\u0004 ימים, אם \u0003אמרה \"צריכה אני\"\u0004 — \u0003מחללין עליה את השבת,\u0004 אבל אם \u0003אמרה \"לא צריכה אני\"\u0004 — \u0003אין מחללין עליה את השבת.\u0004 תוך \u0003שלשים\u0004 ימים \u0003אפילו\u0004 אם \u0003אמרה \"צריכה אני\"\u0004 — \u0003אין מחללין עליה את השבת, אבל עושין על ידי ארמאי\u0004 (גוי).","ו\u0003כ\u0004דברי \u0003רב עולא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב עילאי,\u0004 ש\u0003אמר : כל צרכי חולה\u0004 שאינו מסוכן \u0003נעשין על ידי ארמאי בשבת, וכ\u0004דברי \u0003רב המנונא.\u0004 ש\u0003אמר רב המנונא: דבר שאין בו סכנה\u0004 ויש בו רק חשש חולי — \u0003אומר לגוי ועושה.\u0004","\u0003אמר רב יהודה\u0004 שכך \u0003אמר שמואל: לחיה\u0004 יש הלכה של \u0003שלשים יום.\u0004 ושואלים: \u0003למאי הלכתא\u0004 \u0005[ל\u0006ענין \u0005מה,\u0006 איזו \u0005הלכה]\u0006 נאמר דבר זה? \u0003אמרי נהרדעי\u0004 \u0005[אמרו\u0006 חכמי \u0005נהרדעא]:\u0006 \u0003ל\u0004ענין \u0003טבילה,\u0004 שאין האשה טובלת לטהרה תוך שלושים יום ללידתה, שמאחר ובתוך זמן זה היא חלושה, עלולה היא להצטנן.","\u0003אמר רבא: לא אמרן\u0004 \u0005[אמרנו]\u0006 שאין אשה טובלת \u0003אלא\u0004 כ\u0003שאין בעלה עמה, אבל\u0004 אם \u0003בעלה עמה\u0004 — הרי \u0003בעלה מחממה\u0004 בתשמיש, ואין לחוש שתצטנן מפני החולשה. \u0003כי הא דברתיה\u0004 \u0005[כמו\u0006 מעשה \u0005זה בבתו]\u0006 של \u0003רב חסדא\u0004 אשת רבא ש\u0003טבלה בגו תלתין יומין\u0004 \u0005[בתוך שלושים יום]\u0006 ללידתה \u0003שלא בפני בעלה ואצטניאת\u0004 \u0005[והצטננה],\u0006 \u0003ואמטוי לערסה בתריה\u0004 \u0005[והביאו את מיטתה אחרי,\u0006 אל\u0005]\u0006 \u0003רבא לפומבדיתא.\u0004","\u0003אמר רב יהודה\u0004 שכך \u0003אמר שמואל: עושין מדורה לחיה בשבת בימות הגשמים. סבור מינה\u0004 \u0005[סברו מכאן]\u0006 כי דווקא \u0003לחיה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 אבל \u0003ל\u0004שאר \u0003חולה\u0004 — \u0003לא,\u0004 וכן \u0003בימות הגשמים\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003בימות החמה\u0004 — \u0003לא.\u0004 ואולם מסכמים: \u0003ולא היא,\u0004 אין הדבר כן, אלא \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 \u0003חיה ולא שנא\u0004 \u0005[ואינו שונה]\u0006 \u0003חולה, לא שנא\u0004 \u0005[אינו שונה]\u0006 \u0003בימות הגשמים ולא שנא\u0004 \u0005[ואינו שונה]\u0006 \u0003בימות החמה,\u0004 שבכל האופנים האמורים עושים מדורה אף בשבת. \u0003מדאתמר\u0004 \u0005[ממה ש\u0006כבר \u0005נאמר]\u0006 ש\u0003אמר רב חייא בר אבין\u0004 שכך \u0003אמר שמואל:\u0004 מי ש\u0003הקיז דם ונצטנן\u0004 — \u0003עושין לו מדורה אפילו בתקופת תמוז,\u0004 שאילולא כן סכנה היא לו, שמא יחלה במחלה קשה.","ומסופר כי במקרה כזה, \u0003שמואל צלחו ליה תכתקא דשאגא\u0004 \u0005[שברו לו,\u0006 לצורכו \u0005כורסא של עץ יקר]\u0006 כדי להשתמש בעצים למדורה. וכן \u0003רב יהודה צלחו ליה פתורא דיונה\u0004 \u0005[שברו לו שולחן של עץ הבנה],\u0006 \u0003לרבה צלחו ליה שרשיפא\u0004 \u0005[שברו לו ספסל].\u0006 שהיו צריכים להסיק, ולא מצאו עצים והסיקו באלה מפני הסכנה.","\u0003ואמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרבה: והא קעבר מר\u0004 \u0005[והרי אדוני עובר]\u0006 בשבירת הספסל \u0003משום\u0004 איסור \u0003\"בל תשחית \"!\u0004 שאסור לאבד דברים שיש בהם תועלת וערך: \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה: \u0003\"בל תשחית\" דגופאי\u0004 \u0005[של גופי]\u0006 שמא אחלה ואסתכן — \u0003עדיף לי\u0004 בעיני.","כיון שדובר כאן בסכנה שבהקזת הדם דנים עוד בנושא זה. \u0003אמר רב יהודה\u0004 שכך \u0003אמר רב: לעולם ימכור אדם קורות ביתו, ויקח\u0004 (יקנה) בתמורה \u0003מנעלים לרגליו,\u0004 שעל ידי כך יישמר מן המכשולים ומן ההצטננות. \u0003הקיז דם ואין לו מה יאכל\u0004 לאחר ההקזה — \u0003ימכור\u0004 אפילו \u0003מנעלים שברגליו ויספיק מהן צרכי סעודה.\u0004 שהדבר חשוב אף ממנעלים.","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 הם \u0003צרכי סעודה\u0004 מיוחדים אלה? \u0003רב אמר: בשר, ושמואל אמר: יין.\u0004 ומפרשים: \u0003רב אמר: בשר,\u0004 ותועלתו — משום שהוא \u0003נפשא חלף נפשא\u0004 \u0005[נפש תחת נפש],\u0006 ויש בכך תוספת כח לו. \u0003ושמואל אמר: יין,\u0004 ותועלתו — \u0003סומקא חלף סומקא\u0004 \u0005[אדום תחת אדום]\u0006 ובכך מעין השלמה לדם שיצא בהקזה.","(ה\u0003סימן\u0004 לחכמים המוזכרים להלן בסוגיית הגמרא הוא \u0003\"שנמסר\"\u0004 — \u0003ש\u0004מואל, ר' יוח\u0003נ\u0004ן, רב נח\u0003מ\u0004ן, רב יו\u0003ס\u0004ף, \u0003ר\u0004בה).","מסופר כי \u0003שמואל ביומא דעבד מילתא, עבדי ליה תבשילא דטחלי\u0004 \u0005[ביום\u0006 שבו \u0005עשה דבר,\u0006 הקזה, \u0005עשו לו תבשיל של טחול].\u0006 \u0003ר' יוחנן שתי\u0004 \u0005[היה שותה]\u0006 יין לאחר הקזת דם \u0003עד דנפיק תיהיא מאוניה\u0004 \u0005[שיצא הריח מאזנו].\u0006 \u0003ורב נחמן שתי\u0004 \u0005[היה שותה]\u0006 \u0003עד דקפי טחליה\u0004 \u0005[צף טחולו\u0006 ביין\u0005].\u0006 \u0003רב יוסף שתי\u0004 \u0005[היה שותה]\u0006 \u0003עד דנפיק מריבדא דכוסילתא\u0004 \u0005[שהיה\u0006 יין \u0005יוצא מחור ההקזה].\u0006 \u0003רבא מהדר אחמרא בר תלתא טרפי\u0004 \u0005[היה מחזר\u0006 בזמן זה על \u0005יין בשלושה עלים],\u0006 כלומר, יין ישן שכבר צמחו בגפן שלושה עלים שנה אחר שנה (רש\"ש).","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב נחמן בר יצחק לרבנן\u0004 \u0005[לחכמים]:\u0006 \u0003במטותא מינייכו, ביומא\u0004 \u0005[בבקשה מכם, ביום]\u0006 של \u0003הקזה אמרו לביתייכו\u0004 \u0005[לביתכם,\u0006 נשותיכם\u0005]:\u0006 \u0003נחמן\u0004 בר יצחק \u0003אקלע לגבן\u0004 \u0005[הזדמן אצלנו],\u0006 כדי שיחשבו שיאכל אף הוא אצלן, ויכינו הנשים סעודה גדולה, ובעליהן לא יסתכנו אחר ההקזה.","ועוד אמר: \u0003וכולהו אערומי אסירי, בר מהאי ערמה דשרי\u0004 \u0005[וכל מיני הערמה\u0006 שיש בהם משום קיפוח הזולת \u0005אסורים, חוץ מעורמה זו המותרת].\u0006 ומהי אותה עורמה? \u0003מאן דעביד מילתא ולא אפשר ליה\u0004 \u0005[מי שעשה דבר\u0006 של הקזה \u0005ואין ביכולתו]\u0006 לקנות מזונות, \u0003לישקול זוזא מכא וליזיל לשב חנותא\u0004 \u0005[שיקח זוז שחוק וילך לשבע חנויות],\u0006 ובכל חנות יטעם מן היין כמתכוון לקנות ויתן זוז זה, וכיון שלא יקבלנו החנוני ילך לחנות אחרת, \u0003עד דטעים\u0004 \u0005[שיטעם]\u0006 \u0003שיעור רביעתא\u0004 \u0005[רביעית].\u0006 \u0003ואי לא\u0004 \u0005[ואם אינו\u0006 יכול לעשות כך\u0005]\u0006 — \u0003ליכול שב תמרי אוכמתא, ולישוף מישחא בצידעיה, וניגני בשמשא\u0004 \u0005[שיאכל שבעה תמרים שחורים, ויסוך שמן על רקותיו ויישן בשמש].\u0006","ומסופר כי החכם הגוי \u0003אבלט אשכחיה\u0004 \u0005[מצאו]\u0006 \u0003לשמואל דגני בשמשא\u0004 \u0005[\u0006הוא \u0005ישן בשמש].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אבלט לשמואל: \u0003חכימא דיהודאי, בישא מי הוי טבא\u0004 \u0005[חכם היהודים, רע האם הוא נעשה טוב]?!\u0006 כלומר, החום הרב של השמש, שהוא מזיק, היכול הוא להיות מועיל במקרה מסויים? \u0003אמר ליה\u0004 \u0005[לו]\u0006 שמואל: \u0003יומא\u0004 \u0005[יום]\u0006 של \u0003הקזה הוא,\u0004 ומועיל אז חום השמש.","ולאמיתו של דבר מעירים: \u0003ולא היא,\u0004 לא כך היה מעשה, \u0003אלא איכא יומא דמעלי בה שמשא בכוליה שתא\u0004 \u0005[יש יום שמועילה בו השמש מכל השנה]\u0006 — והוא \u0003יומא\u0004 \u0005[היום]\u0006 ש\u0003נפלה\u0004 \u0005[חלה]\u0006 \u0003ביה\u0004 \u0005[בו]\u0006 בדיוק \u0003תקופת תמוז\u0004 (היום הארוך ביותר). \u0003וסבר\u0004 \u0005[וסבור היה]\u0006 שמואל: \u0003לא איגלי ליה\u0004 \u0005[אגלה לו]\u0006 סגולה זו.","\u0003(היקל ברוח טעמא שהה\u0004 — \u0003סימן\u0004 לעניינים הבאים\u0003): רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003כל המקיל\u0004 ואינו מקפיד לאכול \u0003בסעודת הקזת דם\u0004 — \u0003מקילין לו\u0004 את \u0003מזונותיו מן השמים, ואומרים: הוא על חייו לא חס,\u0004 ו\u0003אני אחוס עליו?!\u0004","וכן \u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003האי מאן דעביד מילתא\u0004 \u0005[מי שעושה דבר\u0006 הקזה\u0005]\u0006 — \u0003לא ליתיב היכא דכריך זיקא\u0004 \u0005[יישב במקום שנושבת בו הרוח],\u0006 שיש לחשוש \u0003דילמא שפי ליה אומנא ומוקים ליה ארביעתא\u0004 \u0005[שמא שאב לו,\u0006 ממנו, \u0005האומן\u0006 דם הרבה \u0005ויעמידם על רביעית\u0006 דם בלבד\u0005],\u0006 \u0003ואתי זיקא ושאיף מיניה, ואתי\u0004 \u0005[ויבוא הרוח וישאף ממנו\u0006 מעט דם, \u0005ויבוא]\u0006 \u0003לידי סכנה.\u0004","מסופר: \u0003שמואל הוה\u0004 \u0005[היה]\u0006 \u0003רגיל ועבד מילתא בביתא דשב לביניא ואריחא\u0004 \u0005[והיה עושה\u0006 את \u0005דבר\u0006 ההקזה \u0005בבית\u0006 שקירותיו היו עבים ועשויים \u0005משבע לבנים ואריח].\u0006 \u0003יומא חדא עבד, וארגיש בנפשיה\u0004 \u0005[יום אחד עשה\u0006 הקזה, \u0005והרגיש בעצמו\u0006 חולשה\u0005].\u0006 \u0003בדק ו\u0004מצא ש\u0003חסר חד אריכא\u0004 \u0005[אריח אחד]\u0006 מעובי הבית, ומשום כך חש בחולשה משום צינה.","\u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003האי מאן דעביד מילתא\u0004 \u0005[מי שעושה\u0006 דבר הקזה\u0005]\u0006 — \u0003ליטעום מידי והדר ליפוק\u0004 \u0005[שיטעם משהו ואחר כך יצא החוצה].\u0006 \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא טעים מידי\u0004 \u0005[יטעם דבר],\u0006 \u0003אי פגע בשכבא\u0004 \u0005[אם יפגוש במת]\u0006 — \u0003ירקא אפיה\u0004 \u0005[יוריקו פניו].\u0006 \u0003אי פגע במאן דקטל נפשא\u0004 \u0005[אם יפגוש במי שהרג נפש]\u0006 — \u0003מית\u0004 \u0005[ימות].\u0006 \u0003אי פגע\u0004 \u0005[אם יפגוש]\u0006"],["\u0003בדבר אחר\u0004 (בחזיר) — \u0003קשה לדבר אחר\u0004 (לצרעת).","\u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003האי מאן דעביד מילתא\u0004 — \u0003לישהי פורתא והדר ליקום\u0004 \u0005[מי שעושה דבר\u0006 הקזה — \u0005ישהה מעט ואחר כך יקום]\u0006 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003חמישה דברים\u0004 אם עושה אותם \u0003קרובין למיתה יותר מן החיים, ואלו הן: אכל ועמד\u0004 מיד, \u0003שתה ועמד, ישן ועמד\u0004 מיד, \u0003הקיז דם ועמד, שימש מטתו ועמד.\u0004","\u0003אמר שמואל: פורסא דדמא\u0004 \u0005[זמני הקזת הדם]\u0006 — \u0003כל תלתין יומין\u0004 \u0005[שלשים יום].\u0006 \u0003ובין הפרקים\u0004 פרקי השנים כשמתחיל להזדקן מעט — \u0003ימעט\u0004 בהקזה, \u0003ובין הפרקים\u0004 המאוחרים יותר \u0003יחזור וימעט.\u0004","\u0003ואמר שמואל: פורסא דדמא\u0004 \u0005[זמני הקזת הדם]\u0006 — \u0003חד בשבתא, ארבעה, ומעלי שבתא\u0004 \u0005[\u0006ביום \u0005ראשון בשבת, רביעי\u0006 בשבת, \u0005וערב שבת],\u0006 \u0003אבל\u0004 ב\u0003שני וחמישי\u0004 — \u0003לא\u0004 יקיז. ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 רק \u0003מי שיש לו זכות אבות\u0004 וסומך עליה \u0003יקיז דם בשני ובחמישי, ש\u0004כן \u0003בית דין של מעלה ושל מטה שוין כאחד.\u0004 וכיון שבית דין של מטה יושב בשני ובחמישי, אף בית דין של מעלה דן אז, ומסוכן הוא בימי הדין, שמא יצא כל דמו.","ומסבירים: \u0003בתלתא בשבתא מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא\u0004 יקיז? \u0003משום דקיימא ליה\u0004 \u0005[שעומד לו]\u0006 כוכב \u0003מאדים בזווי\u0004 \u0005[ב\u0006שעות \u0005זוגיות],\u0006 וכיון שהוא כוכב של דם, וכיון ששעות זוגיות יש בהן סימן רע, הרי כשמצטרפים הדברים יחד יש לחוש. ושואלים: והרי \u0003מעלי שבתא נמי קיימא בזווי\u0004 \u0005[\u0006ב\u0005ערב שבת גם כן עומד\u0006 מאדים \u0005ב\u0006שעות \u0005זוגיות]!\u0006 ומשיבים: \u0003כיון דדשו ביה\u0004 \u0005[שהתרגלו בו]\u0006 כבר \u0003רבים\u0004 לעשות כן הרי \u0003\"שמר פתאים ה'\"\u0004 (תהלים קטז, ו). וכן \u0003אמר שמואל: ארבעה\u0004 (רביעי בשבת) ש\u0003הוא ארבעה\u0004 בחודש, \u0003ארבעה\u0004 בשבת ש\u0003הוא ארביסר\u0004 \u0005[ארבעה עשר],\u0006 \u0003ארבעה\u0004 ש\u0003הוא עשרים וארבעה,\u0004 ו\u0003ארבעה דליכא ארבע בתריה\u0004 \u0005[שאין ארבעה\u0006 ימים \u0005אחריו]\u0006 עוד באותו חודש — \u0003סכנתא\u0004 \u0005[סכנה]\u0006 להקיז בו דם. הקזת דם ב\u0003ראש חודש ו\u0004ביום ה\u0003שני לו\u0004 אם מקיז בהם — גורם ל\u0003חולשא.\u0004 ביום \u0003השלישי לו\u0004 — מביא ל\u0003סכנה.\u0004 הקזת דם ב\u0003מעלי יומא טבא\u0004 \u0005[ערב יום טוב]\u0006 — גורם ל\u0003חולשא.\u0004 ב\u0003מעלי יומא דעצרתא\u0004 \u0005[ערב יום העצרת,\u0006 חג השבועות\u0005]\u0006 — \u0003סכנתא\u0004 \u0005[סכנה].\u0006 \u0003וגזרו רבנן אכולהו מעלי יומא טבא\u0004 \u0005[חכמים\u0006 שלא להקיז דם \u0005בכל ערבי יום טוב]\u0006 \u0003משום יומא טבא\u0004 \u0005[יום טוב]\u0006 של \u0003עצרת, דנפיק ביה זיקא, ושמיה\u0004 \u0005[שיוצאת בו רוח\u0006 רעה, \u0005ושמה]\u0006 \u0003\"טבוח\", דאי\u0004 \u0005[שאם]\u0006 \u0003לא קבלו ישראל\u0004 את ה\u0003תורה\u0004 בחג השבועות — \u0003הוה טבח להו לבשרייהו ולדמייהו\u0004 \u0005[היה טובח אותם לבשרם ודמם],\u0006 וכיון שכך נשאר יום זה יום של סכנה.","","","\u0003אמר שמואל: אכל חטה, והקיז\u0004 לאחר מכן \u0003דם\u0004 — \u0003לא הקיז אלא לאותה חטה,\u0004 כלומר, אין הדבר מועיל, שכן החיטה מילאה את מקום הדם שהקיז. \u0003והני מילי\u0004 \u0005[ודברים אלה]\u0006 שאינו מועיל, הרי זה רק אם הקיז \u0003לרפואה, אבל לאוקולי\u0004 \u0005[לגבי הקלה]\u0006 — \u0003מיקיל,\u0004 ומועיל להקיז אפילו לאחר אכילה. \u0003המקיז דם, שתיה\u0004 ראויה להיות — \u0003לאלתר\u0004 \u0005[מיד].\u0006 \u0003אכילה\u0004 — לא יאכל \u0003עד\u0004 כדי שיעור זמן הליכת \u0003חצי מיל.\u0004","","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 מה שאמרו \u0003שתייה לאלתר,\u0004 האם הכוונה שאם היא מיד \u0003הריהי מעלי\u0004 \u0005[מעולה,\u0006 טובה\u0005],\u0006 \u0003אבל בתר הכי קשי\u0004 \u0005[אחר כך קשה],\u0006 \u0003או דילמא לא קשי ולא מעלי\u0004 \u0005[שמא אינה קשה ואינה מועילה]?\u0006 שאלה זו לא נפתרה, ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה. וכן \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 מה שאמרו \u0003אכילה עד חצי מיל\u0004 האם נפרש שעד חצי מיל \u0003הוא דקמעלי\u0004 \u0005[שמועיל]\u0006 \u0003הא בתר הכי ומקמי הכי\u0004 — \u0003קשי\u0004 \u0005[הרי\u0006 אם \u0005היה זה\u0006 \u0005אחר כך ולפני כן\u0006 — \u0005קשה],\u0006 \u0003או דילמא לא קשי ולא מעלי\u0004 \u0005[או שמא אינו קשה ואינו מועיל]?\u0006 אף שאלה זו לא נפתרה ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 אף היא במקומה.","","היה \u0003מכריז רב\u0004 ואומר: \u0003מאה קרי בזוזא\u0004 \u0005[הקזות בזוז],\u0006 תספורת \u0003מאה רישי בזוזא\u0004 \u0005[ראשים בזוז],\u0006 ואולם לתקן \u0003מאה שפמי\u0004 אינו שווה \u0003ולא כלום\u0004 (גאונים). כי נהוג שהאומן מקיז הדם, שהיה כרגיל גם ספר, לא נטל כסף בעד תיקון השפם, כך שאם אירע שבאו מאה אנשים ביום אחד רק לתקן שפמם היה עובד כל היום ולא קיבל שכר כלל. \u0003אמר רב יוסף: כי הוינן בי\u0004 \u0005[כאשר היינו\u0006 \u0003בבית] רב הונא\u0004 כתלמידים, \u0003יומא דמפגרי ביה רבנן אמרי\u0004 \u0005[\u0006ב\u0005יום שהיו מתעצלים בו חכמים\u0006 ולא היו לומדים כראוי \u0005היו אומרים]:\u0006 \u0003האידנא יומא דשפמי\u0004 [עכשיו זמן של שפמים] \u0003הוא, ולא ידענא מאי קאמרי\u0004 \u0005[ידעתי מה היו אומרים]\u0006 ועכשיו לאחר שמיעת דברי רב מבין הוא שהתכוונו לומר שהוא יום ללא תועלת. \u0003ו\u0004עוד שנינו במשנה ש\u0003קושרין\u0004 את \u0003הטבור\u0004 של התינוק הנולד בשבת. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא כמו כן ואף הוסיפו. ששנינו: \u0003קושרין\u0004 בשבת את \u0003הטבור.\u0004 ו\u0003ר' יוסי אומר: אף חותכין\u0004 אותו בשבת. \u0003וטומנין השליא\u0004 כסגולה ורפואה \u0003כדי שיחם הולד. אמר רבן שמעון בן גמליאל: בנות מלכים\u0004 — \u0003טומנות\u0004 את השליא \u0003בספלים של שמן, בנות עשירים\u0004 — \u0003בספוגים של צמר, בנות עניים במוכין\u0004 (סמרטוטים).","","\u0003אמר רב נחמן\u0004 שכך \u0003אמר רבה בר אבוה\u0004 שכך \u0003אמר רב: הלכה כ\u0004שיטת \u0003ר' יוסי\u0004 שאף מותר לחתוך את הטבור בשבת.","\u0003ואמר רב נחמן\u0004 שכך \u0003אמר רבה בר אבוה\u0004 שכך \u0003אמר רב: מודים חכמים לר' יוסי בטבור של שני תינוקות\u0004 תאומים שהוא מחובר לשניהם יחד, \u0003שחותכין\u0004 אותו בשבת. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? לפי שהם שניים מסוכן להם אם לא יחתכו \u0003דמנתחי אהדדי\u0004 \u0005[ש\u0006הם \u0005מתנתקים זה מזה]\u0006 ובאים לידי סכנה. \u0003ואמר רב נחמן\u0004 שכך \u0003אמר רבה בר אבוה\u0004 שכך \u0003אמר רב: כל האמור בפרשת תוכחה\u0004 (פרק ט\"ז בספר יחזקאל) \u0003עושין לחיה\u0004 (יולדת) \u0003בשבת.\u0004 שהרי שם מדובר על לידה מסוכנת של ילד עזוב, ומכאן שלשאר ילדים יש לדאוג בכל הענינים הללו. \u0003שנאמר\u0004 שם: \u0003\"ומולדותיך ביום הולדת אותך לא כרת שרך ובמים לא רחצת למשעי והמלח לא המלחת והחתל לא חתלת\"\u0004 (יחזקאל טז, ד).","ומפרשים: \u0003\"ומולדותיך ביום הולדת\"\u0004 — \u0003מכאן שמיילדים את הולד בשבת. \"לא כרת שרך\"\u0004 — \u0003מכאן שחותכין\u0004 את \u0003הטבור בשבת. \"ובמים לא רחצת למשעי\"\u0004 — \u0003מכאן שרוחצין\u0004 את \u0003הולד בשבת. \"והמלח לא המלחת\"\u0004 — \u0003מכאן שמולחין\u0004 את \u0003הולד בשבת. \"והחתל לא חתלת\"\u0004 — \u0003מכאן שמלפפין\u0004 (מחתלים) את \u0003הולד בשבת.\u0004","",""],["בהמשך להלכות הנידונות בסוף הפרק הקודם בענין לידה בשבת, ונזכר אף ענין מילה, מביאים גופי הלכות בנושא זה. \u0003ר' אליעזר אומר: אם לא הביא כלי\u0004 למול בו את הילד \u0003מערב שבת\u0004 — \u0003מביאו\u0004 אף \u0003ב\u0004יום ה\u0003שבת\u0004 עצמו. ומביא אותו \u0003מגולה\u0004 שיראו שהוא מביא סכין של מילה. \u0003ובסכנה\u0004 שגזרו גזירת שמד ואסרו על היהודים למול את ילדיהם — \u0003מכסהו על פי עדים\u0004 שיוכלו להעיד כי הוביל את הסכין לצורך מצוה.","\u0003ועוד אמר ר' אליעזר\u0004 בענין זה: אף \u0003כורתים עצים לעשות פחמין\u0004 כדי \u0003לעשות\u0004 באמצעותם \u0003כלי ברזל\u0004 לצורך מילה.","שיטת ר' אליעזר לא היתה מקובלת על כל החכמים ו\u0003כלל אמר ר' עקיבא: כל מלאכה שאפשר לעשותה מערב שבת\u0004 — \u0003אינה דוחה את השבת,\u0004 ובכלל זה הכנסת סכין המילה והבאתה. אבל מלאכה של מצוה \u0003שאי אפשר לעשותה מערב שבת\u0004 כמו המילה עצמה — \u0003דוחה את השבת.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 האם \u0003טעמא\u0004 \u0005[הטעם]\u0006 של \u0003ר' אליעזר\u0004 שיש לגלות את הסכין הוא \u0003משום חבובי\u0004 \u0005[חיבוב]\u0006 \u0003מצוה\u0004 ופרסומה, \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003משום\u0004 מניעת \u0003חשדא\u0004 \u0005[חשד].\u0006 ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה\u0006 להלכה\u0005],\u0006 אם טעם הדבר הוא זה או אחר? ומשיבים: \u0003לאתויי\u0004 \u0005[ל\u0006ענין אפשרות \u0005הבאתו]\u0006 כשהוא \u0003מכוסה על פי עדים\u0004 היודעים שמביא סכין לצורך מילה. \u0003אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שהטעם הוא \u0003משום חבובי\u0004 \u0005[חיבוב]\u0006 \u0003מצוה,\u0004 הרי אם הוא \u0003מגולה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 יש בכך משום חיבוב מצוה, ואולם אם הוא \u0003מכוסה\u0004 — \u0003לא. אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שהטעם \u0003הוא משום\u0004 מניעת \u0003חשדא\u0004 \u0005[חשד]\u0006 — אם כן \u0003אפילו\u0004 הוא \u0003מכוסה,\u0004 כיון שהדבר נעשה \u0003בידיעת עדים שפיר דמי\u0004 \u0005[יפה,\u0006 ראוי \u0005נחשב\u0006 הדבר\u0005].\u0006 ואם כן \u0003מאי\u0004 \u0005[מה]\u0006 המסקנה בענין זה?","\u0003איתמר\u0004 \u0005[נאמר]\u0006 \u0003אמר ר' לוי: לא אמרה ר' אליעזר\u0004 להלכה זו \u0003אלא לחבובי\u0004 \u0005[לחיבוב]\u0006 \u0003מצוה. תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 ילד הצריך להימול בשבת ולא הביאו את הסכין מערב \u0003שבת — מביאו\u0004 אף בשבת כשהוא \u0003מגולה\u0004 דווקא \u0003ואין מביאו\u0004 כשהוא \u0003מכוסה,\u0004 אלו \u0003דברי ר' אליעזר. אמר רב אשי: מתניתין נמי דיקא\u0004 \u0005[משנתנו גם כן מדוייקת]\u0006 כשיטה זו, \u0003דקתני\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בה\u0005]:\u0006 \u0003ובשעת הסכנה מכסהו על פי עדים,\u0004 ומכאן נסיק דווקא \u0003ב\u0004שעת ה\u0003סכנה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 מכסה, ואולם \u0003שלא ב\u0004שעת ה\u0003סכנה\u0004 — \u0003לא, שמע מינה\u0004 \u0005[למד ממנה]\u0006 שהטעם \u0003משום חבובי\u0004 \u0005[חיבוב]\u0006 \u0003מצוה.\u0004 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה].\u0006","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003מביאו\u0004 לסכין כשהוא \u0003מגולה ואין מביאו\u0004 כשהוא \u0003מכוסה,\u0004 אלו \u0003דברי ר' אליעזר, ר' יהודה אומר משום\u0004 (בשם) \u0003ר' אליעזר: נוהגין היו בשעת הסכנה שהיו מביאין\u0004 את הסכין כשהוא \u0003מכוסה על פי עדים.\u0004","על עדים אלה שדובר בהם \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 ה\u0003עדים דקאמר\u0004 \u0005[שאמר]\u0006 האם הכוונה: \u0003איהו וחד\u0004 \u0005[הוא,\u0006 המביא, \u0005ואחד\u0006 נוסף\u0005],\u0006 \u0003או דילמא\u0004 \u0005[שמא]:\u0006 \u0003הוא\u0004 המביא \u0003ותרי\u0004 \u0005[ושנים]\u0006 מלבדו שיעידו.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה ממה ששנינו: \u0003וב\u0004שעת ה\u0003סכנה מכסהו על פי עדים.\u0004 ומעתה \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 כי הכוונה ל\u0003הוא ותרי\u0004 \u0005[ושנים]\u0006 — \u0003שפיר\u0004 \u0005[יפה]\u0006 ומובן הסגנון, \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי הכוונה ל\u0003הוא וחד\u0004 \u0005[ואחד],\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 אם כן פירוש \u0003\"עדים\"\u0004 בלשון רבים, והלא יש רק עד אחד! ודוחים: אין זו ראיה, שעדיין נקראים הם \"עדים\" כיון \u0003שראויים\u0004 הם, כלומר הוא ועוד אחד, \u0003להעיד במקום אחר.\u0004","\u0003ועוד\u0004 שנינו במשנתנו ש\u0003אמר ר' אליעזר\u0004 שאף כורתים עצים לעשות פחמים לצורך המילה בשבת, ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003במקומו של ר' אליעזר\u0004 שהיו נוהגים שם על פיו \u0003היו\u0004 אף \u0003כורתין עצים\u0004 בשבת כדי \u0003לעשות\u0004 מהם \u0003פחמין\u0004 כדי \u0003לעשות\u0004 באמצעותם \u0003ברזל\u0004 למול בו תינוק \u0003בשבת,\u0004 ואגב כך סיפרו כי \u0003במקומו של ר' יוסי הגלילי היו אוכלין בשר עוף בחלב.\u0004 שסבר ר' יוסי הגלילי שאיסור בשר בחלב אינו כולל את העוף.","ומסופר: \u0003לוי איקלע לבי\u0004 \u0005[הזדמן לבית]\u0006 \u0003יוסף רישבא\u0004 \u0005[הצייד].\u0006 \u0003קריבו ליה רישא דטוותא בחלבא\u0004 \u0005[הגישו לו ראש טווס בחלב]\u0006 ו\u0003לא אכל. כי אתא לקמיה\u0004 \u0005[כאשר בא\u0006 לוי \u0005לפני]\u0006 \u0003רבי אמר ליה\u0004 \u0005[לו]\u0006 רבי ללוי: \u0003אמאי לא תשמתינהו\u0004 \u0005[מדוע לא תחרימם]\u0006 לאנשים אלה האוכלים עוף בחלב שלא כדברי חכמים! \u0003אמר ליה\u0004 \u0005[לו]\u0006 לוי: \u0003אתריה\u0004 \u0005[מקומו]\u0006 של \u0003ר' יהודה בן בתירה הוה\u0004 \u0005[היה],\u0006 \u0003ואמינא\u0004 \u0005[ואמרתי]:\u0006 \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003דרש להו\u0004 \u0005[להם]\u0006 שהלכה \u0003כ\u0004שיטת \u0003ר' יוסי הגלילי\u0004 המתיר אכילת בשר עוף בחלב. וכיון שהתיר להם רבם אין מקום לבוא ולאסור עליהם, וודאי שאין להחרימם בשל כך.","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' יוסי הגלילי אומר: נאמר \"לא תאכלו כל נבלה\u0004 לגר אשר בשעריך תתננה ואכלה או מכור לנכרי כי עם קדוש אתה לה' אלהיך \u0003\", ונאמר\u0004 בהמשך הפסוק: \u0003\"לא תבשל גדי בחלב אמו\"\u0004 (דברים יד, כא), ומסמיכות הדברים נלמד: \u0003את שאסור משום נבלה\u0004 — \u0003אסור לבשל בחלב\u0004 ולא רק גדי בחלב אמו. ואולם אם כך תאמר ב\u0003עוף\u0004 מאחר \u0003שאסור\u0004 גם כן \u0003משום נבלה, יכול\u0004 אף הוא \u0003יהא אסור לבשל בחלב\u0004 — \u0003תלמוד לומר: \"בחלב אמו\",\u0004 הרי \u0003יצא עוף שאין לו חלב אם\u0004 ולא נכלל באיסור זה.","\u0003אמר ר' יצחק: עיר אחת היתה בארץ ישראל שהיו עושין כר' אליעזר\u0004 בענין מילה \u0003והיו מתים בזמנן,\u0004 ולא לפני זמנם, בשכר חיבוב מצוה זו. \u0003ולא עוד, אלא שפעם אחת גזרה מלכות הרשעה\u0004 (רומי) \u0003גזרה על ישראל על המילה\u0004 (שלא ימולו), \u0003ועל אותה העיר לא גזרה.\u0004","כיון שדובר בענין מצות מילה וחיבובה, מביאים, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003רבן שמעון בן גמליאל אומר: כל מצוה שקיבלו עליהם\u0004 ישראל מראשיתה \u0003בשמחה, כגון מילה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"שש אנכי על אמרתך כמוצא שלל רב\"\u0004 (תהילים קיט, קסב), ופירשו חכמים ש\"אמרה\" זו היא מצות מילה שששו עליה — \u0003עדיין עושין אותה בשמחה. וכל מצוה שקבלו עליהם\u0004 ישראל מראשיתה \u0003בקטטה\u0004 ובצער \u0003כגון עריות, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"וישמע משה את העם בכה למשפחותיו\"\u0004 (במדבר יא, י), ודרשו חכמים שהיו בוכים \u0003על עסקי משפחותיו,\u0004 שנאסר להם אז לשאת את קרובות המשפחה — \u0003עדיין עושין אותה בקטטה.\u0004 וסימנו של דבר: \u0003דליכא\u0004 \u0005[שאין]\u0006 \u0003כתובה\u0004 וחתונה \u0003דלא רמו\u0004 \u0005[שאין משליכים,\u0006 מתעוררת\u0005]\u0006 \u0003בה תיגרא\u0004 \u0005[קטטה]\u0006 בין הצדדים. ולענייננו, שמתחילה לא קיבלו עליהם ישראל מצוות הקשורות בנישואין ברצון.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 אחרת: \u0003ר' שמעון בן אלעזר אומר\u0004 שבח אחר למצות מילה: \u0003כל מצוה שמסרו ישראל עצמן עליהם למיתה בשעת גזרת המלכות, כגון\u0004 הימנעות מ\u0003עבודה זרה ו\u0004שמירת מצות \u0003מילה\u0004 — \u0003עדיין היא מוחזקת בידם\u0004 בכל תוקף, \u0003וכל מצוה שלא מסרו ישראל עצמן עליה למיתה בשעת גזרת המלכות, כגון תפילין\u0004 — \u0003עדיין היא מרופה בידם\u0004 ואינם נזהרים בה כראוי.","וראיה לדבר שלא קיימו מצוה זו כראוי בשעת הגזירה ממה שמובא בענין תפילין. ש\u0003אמר ר' ינאי: תפילין צריכין גוף נקי כאלישע בעל כנפים.\u0004 ושאלו: \u0003מאי היא\u0004 \u0005[מהו]\u0006 ענין גוף נקי זה? \u0003אמר אביי: שלא יפיח בהם, רבא אמר: שלא יישן בהם.\u0004","ואגב מסבירים: \u0003ואמאי קרו ליה\u0004 \u0005[ומדוע קראו לו]\u0006 \u0003\"אלישע בעל כנפים\"? שפעם אחת גזרה מלכות הרשעה גזרה על ישראל שכל המניח תפילין על ראשו\u0004 — \u0003יקרו\u0004 (ינקרו) \u0003את מוחו, והיה אלישע מניח תפילין ויצא לשוק, וראהו קסדור\u0004 (פקיד) \u0003אחד. רץ\u0004 אלישע \u0003מלפניו ורץ\u0004 הקסדור \u0003אחריו. כיון שהגיע\u0004 הקסדור \u0003אצלו, נטלן\u0004 אלישע \u0003מראשו ואחזן בידו. אמר לו\u0004 הקסדור: \u0003מה בידך? אמר לו\u0004 אלישע: \u0003כנפי יונה,\u0004 ובתוך כך \u0003פשט את ידו ונמצאו בה כנפי יונה. לפיכך היו קוראין אותו\u0004 על שם נס זה \u0003\"בעל כנפים\".\u0004","ושואלים: \u0003מאי שנא\u0004 \u0005[במה שונות]\u0006 \u0003כנפי יונה\u0004 דווקא ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 אלישע לקסדור, \u0003ולא אמר ליה\u0004 \u0005[לו]\u0006 כנפי אחד מ\u0003שאר עופות?\u0004 ומשיבים: \u0003משום דדמיא\u0004 \u0005[שדומה,\u0006 משולה\u0005]\u0006 \u0003כנסת ישראל ליונה,\u0004 וכפי \u0003שנאמר: \"כנפי יונה נחפה בכסף ואברותיה בירקרק חרוץ\"\u0004 (תהלים סח, יד). והסבר המשל: \u0003מה יונה זו\u0004 רק \u0003כנפיה מגינות עליה, אף ישראל\u0004 רק \u0003מצו‍ת מגינות עליהן.\u0004 ובכל אופן למדנו שרק אלישע בעל כנפיים לבדו הוא שנזהר במצוות תפילין, ולא שאר כל העם.","\u0003אמר ר' אבא בר רב אדא\u0004 שכך \u0003אמר ר' יצחק: פעם אחת\u0004 היו צריכים למול תינוק בשבת ו\u0003שכחו ולא הביאו איזמל\u0004 למול בו \u0003מערב שבת, והביאוהו בשבת דרך גגות ודרך חצירות\u0004"],["\u0003שלא ברצון ר' אליעזר,\u0004 שאף על פי שלא היו הגגות והחצרות מעורבים זו עם זו ויש בכך איסור, חכמים לא חששו כדבר.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב יוסף: שלא ברצון ר' אליעזר! אדרבה\u0004 (להיפך), \u0003ר' אליעזר הוא דשרי\u0004 \u0005[שהתיר],\u0006 והרי היתרו מרובה מהיתר זה, שאפילו ברשות הרבים התיר! \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שהכוונה היא \u0003שלא ברצון ר' אליעזר דשרי\u0004 \u0005[שהתיר]\u0006 \u0003אפילו ברשות הרבים, אלא ברצון רבנן\u0004 ש\u0003אסרו דרך רשות הרבים, ושרו\u0004 \u0005[והתירו]\u0006 רק \u0003דרך גגות דרך חצירות וקרפיפות\u0004 — והלא לשיטת חכמים יש לשאול: \u0003ו\u0004כי אפילו באופן זה \u0003מי שרי\u0004 \u0005[האם מותר]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כשם שאין מביאין אותו\u0004 את סכין המילה \u0003דרך רשות הרבים, כך אין מביאין אותו לא דרך גגות ולא דרך קרפיפות ולא דרך חצירות!\u0004","\u0003אלא אמר רב אשי:\u0004 הכוונה היא \u0003שלא ברצון ר' אליעזר ו\u0004בני \u0003מחלוקתו, אלא ברצון ר' שמעון. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' שמעון אומר: אחד גגות ואחד קרפיפות ואחד חצירות\u0004 — \u0003כולן\u0004 ל\u0003רשות אחד הן\u0004 נחשבים \u0003ל\u0004גבי \u0003כלים ששבתו\u0004 בתחילת השבת \u0003בתוכן,\u0004 שמותר לטלטלן בהם מזה לזה. \u0003ו\u0004אולם \u0003לא\u0004 נחשבים הם רשות אחת \u0003ל\u0004גבי \u0003כלים ששבתו בתוך הבית.\u0004 שאם לא עירבו בעלי הבתים את כל החצירות — אסור להוציא את כליהם לחצר, ואם עירבו בעלי הבית עם החצר — אסור להוציא חפץ מן הבית אל הקרפף אם החצר אינה מעורבת עם הקרפף. ומכל מקום למדנו מדברי ר' שמעון שבשעת הדחק אפשר לטלטל דרך גגות וחצירות וקרפיפות.","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003ר' זירא מר' אסי: מבוי שלא נשתתפו בו\u0004 הדיירים, \u0003מהו\u0004 דינו האם מותר \u0003לטלטל\u0004 חפצים \u0003בכולו\u0004 לשיטת ר' שמעון? והסבר השאלה: \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 כי \u0003כחצר דמי\u0004 \u0005[נחשב],\u0006 ונאמר כי \u0003מה חצר, אף על גב\u0004 ש\u0003לא ערבו\u0004 את הבתים שבתוכה — בכל זאת \u0003מותר לטלטל בכולו,\u0004 אף על פי שאסור להוציא חפצים מהבית לחצר, \u0003האי נמי\u0004 \u0005[זה גם כן],\u0006 \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא נשתתפו בו\u0004 — \u0003מותר לטלטל בכולו\u0004 אף שאסור להוציא חפצים למבוי, \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003לא דמי\u0004 \u0005[דומה]\u0006 בענין זה המבוי \u0003לחצר,\u0004 כי ה\u0003חצר אית ליה\u0004 \u0005[יש לו]\u0006 \u0003ארבע מחיצות,\u0004 ואילו \u0003האי לית ליה\u0004 \u0005[זה,\u0006 המבוי \u0005אין לו]\u0006 \u0003ארבע מחיצות\u0004 אלא שלוש בלבד. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 נימוק אחר לגריעות המבוי: \u0003חצר אית ליה דיורין\u0004 \u0005[יש לה,\u0006 בה \u0005דיירים],\u0006 ונמצא שהיא נחשבת כבית, ואולם \u0003האי לית ביה דיורין\u0004 \u0005[זה\u0006 המבוי \u0005אין בו דיירים].\u0006 והשאלה אם כן מה דין המבוי לענין זה? \u0003שתיק\u0004 \u0005[שתק]\u0006 ר' אסי \u0003ולא אמר ליה\u0004 \u0005[לו]\u0006 \u0003ולא מידי\u0004 \u0005[דבר].\u0006 שלא ידע להשיבו תשובה ברורה.","\u0003זימנין אשכחיה דיתיב וקא אמר\u0004 \u0005[פעם אחרת מצאו\u0006 ר' זירא לר' אסי \u0005שיושב ואומר],\u0006 \u0003אמר ר' שמעון בן לקיש משום\u0004 (בשם) \u0003ר' יהודה הנשיא: פעם אחת שכחו ולא הביאו איזמל מערב שבת\u0004 לצורך מילת תינוק בשבת, \u0003והביאוהו בשבת, והיה הדבר קשה לחכמים: היאך מניחין\u0004 את \u0003דברי חכמים\u0004 האוסרים \u0003ועושין כ\u0004דברי \u0003ר' אליעזר.\u0004 ומדוע היה הדבר קשה להם — \u0003חדא\u0004 \u0005[\u0006סיבה \u0005אחת]:\u0006 ש\u0003ר' אליעזר שמותי הוא,\u0004 שהיה נוטה לשיטת בית שמאי (ירושלמי) והלכה ברוב הדברים שנחלקו עם בית הלל כדברי בית הלל! \u0003ועוד,\u0004 שהרי כלל הוא שבכל דבר שנחלקו בו \u0003יחיד ורבים\u0004 — \u0003הלכה כרבים,\u0004 ואף כאן ודאי הלכה היא כדברי חכמים החולקים על ר' אליעזר!","\u0003ואמר ר' אושעיא: שאילית\u0004 \u0005[שאלתי]\u0006 \u0003את ר' יהודה הגוזר\u0004 (המוהל) \u0003ואמר לי\u0004 הסבר לענין זה: ב\u0003מבוי שלא נשתתפו בו הוה\u0004 \u0005[היה]\u0006 מעשה זה שהביא ר' אסי בשם ר' יהודה הנשיא, \u0003ואייתוהו מהאי רישא להאי רישא\u0004 \u0005[והביאוהו\u0006 לאותו איזמל \u0005מראש,\u0006 קצה, \u0005זה\u0006 של המבוי \u0005לראש,\u0006 קצה, \u0005זה]\u0006 שבו היה התינוק. עד כאן אמר ר' אסי באותו ענין. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' זירא לר' אסי: מתוך זה שהבאת מעשה זה בלא הסתייגות נראה כי ודאי \u0003סבירא ליה למר\u0004 \u0005[סבור הוא אדוני]\u0006 כי \u0003מבוי שלא נשתתפו\u0004 בו \u0003מותר לטלטל בכולו? ואמר ליה\u0004 \u0005[לו]\u0006 ר' אסי: \u0003אין\u0004 \u0005[כן],\u0006 וכן הלכה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' זירא: \u0003והא זימנין בעאי מינך\u0004 \u0005[והרי פעם\u0006 אחרת \u0005שאלתי ממך]\u0006 דבר זה \u0003ולא אמרת לי הכי\u0004 \u0005[כך]!\u0006 \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003אגב שיטפך\u0004 \u0005[שטף]\u0006 לימודך \u0003רהיט\u0004 \u0005[הושב]\u0006 \u0003לך גמרך\u0004 \u0005[תלמודך]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 \u0003אגב שיטפא רהיטא\u0004 \u0005[שטף\u0006 לימודי \u0005הושב]\u0006 \u0003לי גמרי\u0004 \u0005[תלמודי]\u0006 ונזכרתי בהלכה זו.","באותה הלכה עצמה ובאופן כללי \u0003איתמר\u0004 \u0005[נאמר]\u0006 ש\u0003אמר ר' זירא\u0004 שכך \u0003אמר רב: מבוי שלא נשתתפו בו\u0004 בני החצירות הפתוחות אליו — \u0003אין מטלטלין בו אלא ב\u0004תוך \u0003ארבע אמות.\u0004","\u0003אמר אביי: הא מילתא\u0004 \u0005[דבר\u0006 הלכה \u0005זה]\u0006 \u0003אמרה ר' זירא ולא פירשה עד דאתא\u0004 \u0005[שבא]\u0006 \u0003רבה בר אבוה ופירשה.\u0004 ש\u0003אמר רב נחמן\u0004 שכך \u0003אמר רבה בר אבוה\u0004 שכך \u0003אמר רב : מבוי שלא נשתתפו בו\u0004 דיירי החצרות הפתוחות אליו, אם \u0003עירבו\u0004 ה\u0003חצירות עם\u0004 ה\u0003בתים,\u0004 כלומר בעלי הבתים שבתוך כל חצר עירבו ביניהם כל חצר לעצמה ובכך התירו לעצמם את הטלטול בוך החצר עצמה — \u0003אין מטלטלין בו אלא ב\u0004תוך \u0003ארבע אמות\u0004 כמו בכרמלית. אולם אם \u0003לא עירבו חצירות עם\u0004 ה\u0003בתים\u0004 ובכגון זה אסור לטלטל בתוך החצרות — \u0003מותר לטלטל בכולו,\u0004 בכל המבוי.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חנינא חוזאה לרבה: מאי שנא\u0004 \u0005[במה שונה]\u0006 הדבר \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003עירבו חצירות עם בתים\u0004 — שאנו אומרים אז ש\u0003ניתקו\u0004 ה\u0003חצירות ונעשו\u0004 כעין \u0003בתים, ורב לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר רב: אין המבוי ניתר\u0004 בטלטול \u0003בלחי וקורה\u0004 כדין מבוי שאינו מפולש שעל ידי כך הוא כסתום על פי תקנת חכמים, \u0003עד שיהו\u0004"],["\u0003בתים וחצרות פתוחין לתוכו,\u0004 שיש שני בתים לפחות בכל חצר, ושתי חצרות לפחות במבוי, \u0003ו\u0004אולם \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003בתים\u0004 — \u0003איכא\u0004 \u0005[יש],\u0006 ואולם \u0003חצרות\u0004 — \u0003ליכא\u0004 \u0005[אין],\u0006 ולכן אין דיני מבוי חלים כאן. ומקשים: \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003לא עירבו נמי ליחזינהו להני\u0004 \u0005[גם כן שיראו אותם]\u0006 \u0003בתים כמאן דסתימי דמו\u0004 \u0005[כמי שהיו סתומים ייחשבו],\u0006 שכיון שאין עירוב במקום, אין יושבי הבתים רשאים להוציא את כליהם לחצר, ואין הבתים נחשבים, \u0003ו\u0004נמצא כי אף כאן \u0003חצרות — איכא\u0004 \u0005[יש]\u0006 \u0003ובתים\u0004 — \u0003ליכא\u0004 \u0005[אין]!\u0006","ומשיבים: במקרה זה \u0003אפשר דמבטלי ליה רשותא דכולהו\u0004 \u0005[שיבטלו רשות של כולם]\u0006 \u0003לגבי חד\u0004 \u0005[אחד],\u0006 שכשם שאפשר להתיר טלטול על ידי עירוב, כמו כן אפשר שיבטלו כל בעלי הבתים את רשותם וזכותם לטלטל לגבי אחד מהם, ויהא נחשב כאילו כולם בית אחד, ואפשר יהיה לטלטל את כלי החצר והבתים. ודוחים: \u0003סוף סוף\u0004 גם במקרה כזה אמנם \u0003בית\u0004 אחד \u0003איכא\u0004 \u0005[יש]\u0006 ואולם \u0003בתים ליכא\u0004 \u0005[אין],\u0006 שאי אפשר לבטל רשות אלא לגבי בית אחד ולא שנים!","ומשיבים: אף לכך \u0003אפשר\u0004 למצוא תקנה, \u0003דמצפרא\u0004 \u0005[שמן הבוקר]\u0006 \u0003ועד פלגא דיומא\u0004 \u0005[חצי היום]\u0006 יבטלו \u0003לגבי חד\u0004 \u0005[אחד],\u0006 ו\u0003מפלגיה דיומא ולפניא\u0004 \u0005[ומחציו של היום עד הערב]\u0006 יבטלו \u0003לגבי חד\u0004 \u0005[אחד],\u0006 ונמצאים כאן איפוא שני בתים! ודוחים: \u0003סוף סוף בעידנא דאיתיה להאי, ליתיה להאי\u0004 \u0005[בזמן שישנו\u0006 הבית \u0005לזה, אינו לזה].\u0006 שבכל שעה יש רק בית אחד בלבד שיש לו רשות לטלטל. \u0003אלא אמר רב אשי:\u0004 עלינו לדחות את שיטת ההסבר שאין כאן \"חצרות ובתים\", ולומר כך: \u0003מי גרם לחצרות שיאסרו\u0004 — ה\u0003בתים,\u0004 שהרי אילו לא היו בתים מותר היה לטלטל מן החצרות למבוי, שהם כרשות אחת לדעת ר' שמעון, \u0003ו\u0004כאן \u0003ליכא\u0004 \u0005[אין]\u0006 בתים, וממילא אפשר לטלטל במבוי.","\u0003אמר ר' חייא בר אבא\u0004 שכך \u0003אמר ר' יוחנן: לא לכל\u0004 דבר \u0003אמר ר' אליעזר\u0004 ש\u0003מכשירי מצוה דוחין את השבת,\u0004 שאין זה כלל קבוע לגבי כל מכשירי המצוות, אלא בכל מקרה ומקרה יש לדון לגופו, ולהוכיח שקיימת הלכה זו בו. \u0003שהרי שתי הלחם\u0004 שמקריבים בחג השבועות \u0003חובת היום הן, ולא למדן ר' אליעזר\u0004 שמכשיריהן דוחים או השבת \u0003אלא מגזירה שוה\u0004 מיוחדת, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: מניין למכשירי שתי הלחם שדוחין את השבת?\u0004 — \u0003נאמרה\u0004 לשון \u0003הבאה בעומר, ונאמרה\u0004 לשון \u0003הבאה בשתי הלחם,\u0004 ומן הדמיון נלמד כי \u0003מה הבאה האמורה בעומר\u0004 — כל ה\u0003מכשירין דוחין את השבת,\u0004 שלא רק הקרבת מנחת העומר למזבח דוחה שבת, אלא אף קצירת העומר שהיא בבחינת מכשירי מצוה אף היא דוחה את השבת. \u0003אף הבאה האמורה בשתי הלחם\u0004 — ה\u0003מכשירין דוחין את השבת.\u0004","על גזירה שווה זו מעירים: \u0003מופני\u0004 \u0005[מופנה,\u0006 מיותר\u0005],\u0006 כלומר, שני הפסוקים המשמשים לגזירה שווה זו בהכרח שהם מיותרים ומופנים לשמש רק לצורך השוואה וגזירה שווה. \u0003דאי לא מופני, איכא למיפרך\u0004 \u0005[שאם אינו מופנה, יש\u0006 מקום \u0005לפרוך,\u0006 לשבור\u0005]\u0006 את ההשוואה מבחינה הגיונית, שכן אפשר לומר: \u0003מה לעומר\u0004 שאתה מביא ממנו ראיה שיתכן ורק בו הותרו המכשירים, \u0003שכן\u0004 דין מיוחד בו, שאף \u0003אם מצא\u0004 עומר \u0003קצור\u0004 — הריהו חוזר ו\u0003קוצר\u0004 לשם מצוה, וכי \u0003תאמר\u0004 אם כן שהוא הדין \u0003אף בשתי הלחם\u0004 שאין בהם דין מיוחד זה, \u0003ש\u0004הרי \u0003אם מצא קצור\u0004 — \u0003אינו קוצר,\u0004 שאין שתי הלחם צריכות קצירה לשמה, ולכאורה אם כן אין הדברים דומים. אלא \u0003לאי אפנויי מופני\u0004 \u0005[באמת מופנה\u0006 הכתוב\u0005].\u0006 וכן מסבירים אנו: \u0003מכדי כתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"\u0004כי תבואו אל הארץ אשר אני נותן לכם וקצרתם את קצירה \u0003והבאתם את עמר ראשית קצירכם אל הכהן\"\u0004 (ויקרא כג, י), ומאחר שכן הפסוק המזכיר שנית \"וספרתם לכם ממחרת השבת \u0003ביום הביאכם\u0004 את עומר התנופה שבע שבתות תמימות תהיינה\" (ויקרא כג, טו), ולכאורה \u0003למה לי\u0004 חזרה זו? \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 מחזרה יתירה זו שבאה \u0003לאפנויי\u0004 \u0005[להפנות,\u0006 לייתר\u0005],\u0006 שפסוק זה ישמש לצורך גזירה שווה.","\u0003ואכתי\u0004 \u0005[ועדיין]\u0006 יש מקום להקשות: והלא גזירה שווה זו \u0003מופנה מצד אחד\u0004 בלבד \u0003הוא,\u0004 שפסוק אחד בלבד מיותר, אבל לא הפסוק השני, \u0003ושמעינן ליה\u0004 \u0005[ושמענו אותו]\u0006 את \u0003ר' אליעזר\u0004 עצמו ש\u0003אמר\u0004 שכל גזירה שווה שיש בה פסוק ה\u0003מופנה מצד אחד\u0004 בלבד אמנם \u0003למידין\u0004 ממנה אך גם \u0003משיבין\u0004 ודוחים את הגזירה השווה, אם יש נימוק הגיוני לעשות זאת! ומשיבים: אף כאן יש מעין ייתור הכתובים אף בענין שתי הלחם, שכן החזרה \"ממושבותיכם תביאו לחם תנופה שתים שני עשרונים סולת תהיינה\" (ויקרא כג, יז) שהמלה \u0003\"תביאו\" רבויא הוא\u0004 \u0005[רבוי היא],\u0006 לפי שאיננה הכרחית, ואפשר היה לוותר עליה ולסמוך על הכתוב בפסוק הקודם, ונמצא שגזירה שווה זו מופנה משני צדדים.","לגופם של דברי ר' יוחנן שלא לכל דבר אמר ר' אליעזר שמכשירי מצוה דוחים את השבת שואלים: \u0003למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]\u0006 שלא אמר ר' אליעזר שמכשיריו דוחים את השבת, \u0003אילימא למעוטי\u0004 \u0005[אם תאמר למעט]\u0006 מצות \u0003לולב\u0004 — \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לולב וכל מכשיריו דוחין את השבת,\u0004 אלו \u0003דברי ר' אליעזר. ואלא\u0004 תאמר שבא \u0003למעוטי\u0004 \u0005[למעט]\u0006 מצות \u0003סוכה\u0004 — \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003סוכה וכל מכשיריה דוחין את השבת,\u0004 אלו \u0003דברי ר' אליעזר. ואלא\u0004 תאמר שבא \u0003למעוטי\u0004 \u0005[למעט]\u0006 מצות \u0003מצה\u0004 בפסח — \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מצה וכל מכשיריה דוחין את השבת,\u0004 אלו \u0003דברי ר' אליעזר. ואלא\u0004 תאמר שבא \u0003למעוטי\u0004 \u0005[למעט]\u0006 מצות \u0003שופר\u0004 בראש השנה — \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שופר וכל מכשיריו דוחין את השבת,\u0004 אלו \u0003דברי ר' אליעזר!\u0004","\u0003אמר רב אדא בר אהבה:\u0004 דברי ר' יוחנן שלא לכל דבר אמר ר' אליעזר שמכשירי מצוה דוחים את השבת באים \u0003למעוטי\u0004 \u0005[למעט]\u0006 עשיית \u0003ציצית לטליתו\u0004 או קביעת \u0003מזוזה לפתחו,\u0004 שאין עשייתם דוחה את השבת. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003ושוין\u0004 ר' אליעזר וחכמים \u0003שאם צייץ\u0004 (עשה ציצית) ב\u0003טליתו\u0004 בשבת, \u0003ו\u0004כן אם \u0003עשה מזוזה לפתחו\u0004 בשבת \u0003שהוא חייב.\u0004","ומעתה שואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הסכים ר' אליעזר שאין מצוות אלה דוחות את השבת? \u0003אמר רב יוסף: לפי שאין קבוע להם זמן\u0004 ויכול לעשותן גם לאחר השבת. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אדרבה\u0004 (להיפך), \u0003מדאין\u0004 \u0005[מ\u0006מה \u0005שאין]\u0006 \u0003קבוע להם זמן,\u0004"],["\u0003כל שעתא ושעתא זמניה\u0004 \u0005[שעה ושעה זמנו]\u0006 \u0003הוא,\u0004 וחלה חובת המצוה עליו בכל רגע, ואינו יכול להבטל ממנה, ומדוע יפטר בשבת מעשיית המצוה? \u0003אלא אמר רב נחמן\u0004 שכך \u0003אמר ר' יצחק, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת בשם \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: הואיל ובידו להפקירן,\u0004 כיון שמצוות אלה אין אדם חייב לעשותן אלא אם כן היו הדברים המחוייבים במצוה מצויים ברשותו, ומכיון שכן יכול הוא להפקירם, ושוב לא תחול עליו חובתה של מצוה זו.","מקודם שנינו ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: \u0003לולב וכל מכשיריו דוחין את השבת\u0004 ל\u0003דברי ר' אליעזר.\u0004 ושואלים: \u0003מנא ליה\u0004 \u0005[מנין לו]\u0006 \u0003לר' אליעזר הא\u0004 \u0005[\u0006דבר \u0005זה]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 תאמר שלמד זאת \u0003מעומר ושתי הלחם\u0004 שמכשיריהם דוחים את השבת, ואולם אפשר לדחות ולומר כי בהם הותרה עשיית המכשירים בשבת \u0003שכן\u0004 אלה \u0003צורך גבוה\u0004 (ה', המקדש) הם, וקשורים בעבודת הקרבנות, ועבודה זו הלא נמשכת כסדרה גם בשבת! \u0003אלא\u0004 יש לומר כי הוא לומד זאת ממה ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"ולקחתם לכם \u0003ביום\u0004 הראשון פרי עץ הדר כפות תמרים וענף עץ עבות וערבי נחל ושמחתם לפני ה' אלהיכם שבעת ימים\" (ויקרא כג, מ), והוא מדייק: \u0003\"ביום\"\u0004 משמעו — ביום הראשון חייבים אתם לקחתו ו\u0003אפילו\u0004 הוא חל \u0003בשבת.\u0004","\u0003ו\u0004מעתה נברר: \u0003למאי הלכתא\u0004 \u0005[ל\u0006צורך \u0005מה,\u0006 איזו \u0005הלכה]\u0006 נאמרה הדגשה זו? וכיצד תמנע קדושת השבת ממצות הלולב? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שבאה \u0003ל\u0004התיר את \u0003טלטול\u0004 הלולב על אף איסור מוקצה — וכי \u0003איצטריך קרא למישרי\u0004 \u0005[הוצרך הכתוב להתיר]\u0006 \u0003טלטול?!\u0004 והרי איסור זה אינו כתוב בתורה, ולא באה התורה להתיר דבר שאסרוהו חכמים בלבד. \u0003אלא\u0004 ודאי בא הכתוב להתיר לחלל שבת \u0003למכשיריו.\u0004","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 החולקים על ר' אליעזר מה מבינים הם בהדגשה זו? ומשיבים: הם סבורים כי הכתוב \u0003ההוא\u0004 \"ביום\" \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 ללמדנו שמצוה זו צריך שתיעשה \u0003ביום ולא בלילה.\u0004","ושואלים: \u0003ור' אליעזר\u0004 דין זה שצריך שתיעשה \u0003ביום ולא בלילה מנא ליה\u0004 \u0005[מניין לו]?\u0006 ומשיבים: הלכה זו \u0003נפקא ליה\u0004 \u0005[יוצאת,\u0006 נלמדת, \u0005לו]\u0006 \u0003מ\u0004האמור \u0003\"ושמחתם לפני ה' אלהיכם שבעת ימים\",\u0004 והוא מדקדק: ב\u0003ימים ולא\u0004 ב\u0003לילות.\u0004","ועדיין יש להבין \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה הם אומרים על כך — לדעתם פסוק זה \"ימים\" \u0003איצטריך\u0004 \u0005[צריך]\u0006 להוסיף ולהדגיש, כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 ש\u0003נילף\u0004 \u0005[נלמד]\u0006 \u0003שבעת ימים\u0004 האמורים כאן \u0003מ\u0004שבעת ימים האמורים ב\u0003סוכה,\u0004 ונאמר: \u0003מה להלן\u0004 בסוכה הכוונה שחובת המצוה היא ב\u0003ימים ואפילו\u0004 ב\u0003לילות, אף כאן\u0004 בלולב המצוה היא ב\u0003ימים ואפילו\u0004 ב\u0003לילות\u0004 — על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שוב \"שבעת ימים\" לומר שהמצוה היא בימים דווקא.","ושואלים: \u0003ו\u0004לשיטת ר' אליעזר, \u0003לכתוב רחמנא\u0004 \u0005[תכתוב התורה]\u0006 \u0003בלולב\u0004 בלבד, \u0003וניתו הנך ונילפו מיניה\u0004 \u0005[ויביאו אלה,\u0006 עומר וכיוצא בו, \u0005וילמדו ממנו]!\u0006 ומשיבים: \u0003משום דאיכא למיפרך\u0004 \u0005[שיש\u0006 מקום \u0005לפרוך,\u0006 לשבור\u0005]\u0006 את ההשוואה ולומר: \u0003מה ללולב\u0004 שחשוב הוא, \u0003שכן טעון ארבעה מינים,\u0004 שצריך שיהיו בנוסף ללולב עצמו עוד שלושה מינים ויהיו ביחד ארבעה, מה שאין כן בשאר המצוות.","מקודם שנינו ברייתא האומרת כי \u0003סוכה וכל מכשיריה דוחין את השבת,\u0004 אלו \u0003דברי ר' אליעזר.\u0004 ושואלים: \u0003מנא ליה\u0004 \u0005[מנין לו]\u0006 \u0003לר' אליעזר הא\u0004 \u0005[\u0006דבר \u0005זה]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 תאמר שהוא לומד זאת \u0003מעומר ושתי הלחם\u0004 — יש לדחות ולומר שבהם הותרה עשיית המכשירים בשבת \u0003שכן צורך גבוה הוא. אי\u0004 \u0005[\u0006ו\u0005אם]\u0006 תאמר שהוא למד זאת \u0003מלולב\u0004 — יש לדחות ולומר כי בו הותרו \u0003שכן טעון\u0004 הוא \u0003ארבעה מינים,\u0004 וחשוב הוא יותר.","\u0003אלא\u0004 יש לומר כי הוא \u0003גמר\u0004 \u0005[למד]\u0006 זאת בדרך גזירה שווה מן הכתוב \u0003\"שבעת ימים\"\u0004 גם בסוכה וגם ב\u0003לולב,\u0004 שלדעתו דמיון הכתובים בא לומר כי \u0003מה להלן\u0004 בלולב \u0003מכשיריו דוחין את השבת, אף כאן\u0004 בסוכה \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003מכשיריו דוחין את השבת.\u0004","ושואלים: \u0003וליכתוב רחמנא\u0004 \u0005[ושתכתוב התורה]\u0006 היתר עשיית המכשירים בשבת \u0003בסוכה\u0004 בלבד, \u0003וניתי הנך וניגמור מיניה\u0004 \u0005[\u0006\u0005ויבואו אלה,\u0006 שאר המצוות, \u0005וילמדו ממנה]!\u0006 ומשיבים: \u0003משום דאיכא למיפרך\u0004 \u0005[שיש\u0006 מקום \u0005לפרוך,\u0006 לשבור\u0005]\u0006 לימוד זה כך: \u0003מה לסוכה\u0004 שיש בה יתרון על כל המצוות האחרות שמנינו \u0003שכן\u0004 היא \u0003נוהגת בלילות כבימים\u0004 ואילו האחרות נוהגות רק ביום.","מקודם שנינו ברייתא האומרת כי \u0003מצה וכל מכשיריה דוחין את השבת,\u0004 אלו \u0003דברי ר' אליעזר.\u0004 ושואלים: \u0003מנא ליה\u0004 \u0005[מנין לו]\u0006 \u0003לר' אליעזר הא\u0004 \u0005[\u0006דבר \u0005זה]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 תאמר שהוא לומד זאת \u0003מעומר ושתי הלחם\u0004 — יש לדחות ולומר שבהם הותרה עשיית המכשירים בשבת \u0003שכן צורך גבוה\u0004 הוא. \u0003אי\u0004 \u0005[אם]\u0006 תאמר שהוא לומד זאת \u0003מלולב\u0004 — יש לדחות ולומר כי בו הותרה עשיית המכשירים \u0003שכן\u0004 הוא \u0003טעון ארבעה מינים. אי\u0004 \u0005[אם]\u0006 תאמר שהוא לומד זאת \u0003מסוכה\u0004 — יש לדחות ולומר כי בו הותרו \u0003שכן\u0004 היא \u0003נוהגת בלילות כבימים.\u0004","\u0003אלא\u0004 יש לומר שר' אליעזר \u0003גמר\u0004 \u0005[למד]\u0006 זאת גזירה שווה לשון \u0003\"חמשה עשר\"\u0004 שנאמר בענין מצה מלשון \u0003\"חמשה עשר\"\u0004 שנאמר ב\u0003חג הסוכות: מה להלן\u0004 בחג הסוכות החג הוא ביום החמשה עשר בחודש, ו\u0003מכשיריה\u0004 של הסוכה \u0003דוחין את השבת, אף כאן\u0004 במצה מצוותה בחמשה עשר בחודש ו\u0003מכשיריה דוחין את השבת.\u0004","ושואלים: \u0003וליכתוב רחמנא\u0004 \u0005[ושתכתוב התורה]\u0006 היתר זה \u0003במצה, וניתו הנך וליגמור מיניה\u0004 \u0005[ויבואו אלה,\u0006 השאר, \u0005וילמדו ממנה]!\u0006 ומשיבים: אי אפשר לומר כך, \u0003משום דאיכא למיפרך\u0004 \u0005[שיש\u0006 מקום \u0005לפרוך,\u0006 לשבור\u0005]\u0006 את ההשוואה כך: \u0003מה למצה שכן נוהגת בנשים כבאנשים,\u0004 בעוד שהמצוות האחרות שמנינו מיוחדות לגברים.","עוד שנינו ברייתא האומרת כי \u0003שופר וכל מכשיריו דוחין את השבת,\u0004 אלו \u0003דברי ר' אליעזר.\u0004 ושואלים: ושואלים: \u0003מנא ליה\u0004 \u0005[מנין לו]\u0006 \u0003לר' אליעזר הא\u0004 \u0005[\u0006דבר \u0005זה]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 תאמר שהוא לומד זאת \u0003מעומר ושתי הלחם\u0004 — יש לדחות ולומר שבהם הותרה עשיית המכשירים בשבת \u0003שכן צורך גבוה\u0004 הוא. \u0003אי\u0004 \u0005[אם]\u0006 תאמר שהוא לומד זאת \u0003מלולב\u0004 — יש לדחות ולומר כי בו הותרה עשיית המכשירים \u0003שכן\u0004 הוא \u0003טעון ארבעה מינים. אי\u0004 \u0005[אם]\u0006 תאמר שהוא לומד זאת \u0003מסוכה\u0004 — יש לדחות ולומר כי בו הותרו \u0003שכן\u0004 היא \u0003נוהגת בלילות כבימים. אי\u0004 \u0005[אם]\u0006 תאמר שהוא לומד זאת \u0003ממצה\u0004 — יש לדחות ולומר כי בה הותרו המכשירים \u0003שכן\u0004 היא \u0003נוהגת\u0004 אף \u0003בנשים כבאנשים. אלא\u0004 יש לומר שר' אליעזר למד זאת ממה ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"\u0004ובחודש השביעי באחד לחודש מקרא קודש יהיה לכם כל מלאכת עבודה לא תעשו \u0003יום תרועה יהיה לכם\"\u0004 (במדבר כט, א), שהדגשת הכתוב \u0003\"ביום\"\u0004 באה ללמד: \u0003אפילו בשבת.\u0004","\u0003ולמאי\u0004 \u0005[ולמה],\u0006 לאיזה צורך, הודגש הדבר? \u0003אילימא\u0004 \u0005[אם לומר]\u0006 כדי \u0003ל\u0004התיר \u0003תקיעה,\u0004 ואולם \u0003הא תנא\u0004 \u0005[הרי\u0006 כבר \u0005שנה]\u0006 זאת החכם \u0003דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003שמואל\u0004 על הכתוב בשבת \u0003\"כל מלאכת עבודה לא תעשו\"\u0004 — \u0003יצתה\u0004 (יצאה) \u0003תקיעת שופר ורדיית הפת\u0004 מן התנור \u0003שהיא חכמה ואינה מלאכה,\u0004 שדברים אלה אינם כלולים בגדר מלאכות שיש בהן מעשה האסורות בשבת. ובוודאי לא בא הכתוב להתיר דבר שאינו אסור מן התורה. \u0003אלא\u0004 הוצרך \u0003למכשירין.\u0004","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 כיצד מבינים הם את ההדגשה של \"ביום\"? ומשיבים: הכתוב \u0003ההוא מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 ללמד שדווקא \u0003ביום ולא בלילה.\u0004 ושואלים: \u0003ור' אליעזר\u0004 הלכה זו של תקיעת שופר \u0003ביום ולא בלילה מנא ליה\u0004 \u0005[מניין לו]?\u0006 ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצאת,\u0006 נלמדת, \u0005לו]\u0006 \u0003מ\u0004הכתוב בדיני שנת היובל \u0003\"\u0004והעברת שופר תרועה בחודש השביעי בעשור לחודש \u0003ביום הכפרים תעבירו שופר בכל ארצכם\"\u0004 (ויקרא כה, ט), \u0003וגמרי מהדדי\u0004 \u0005[ולמדים\u0006 הם \u0005זה מזה]\u0006 שכל התקיעות של החודש השביעי תהיינה ביום דווקא ולא בלילה.","ושואלים: \u0003ו\u0004לשיטת ר' אליעזר, \u0003לכתוב רחמנא\u0004 \u0005[תכתוב התורה]\u0006 \u0003בשופר\u0004 בלבד \u0003וליתו הנך וליגמרו מיניה\u0004 \u0005[ויבואו אלה,\u0006 שאר מצוות, \u0005וילמדו ממנו]!\u0006 ומשיבים: \u0003מתקיעת שופר\u0004 של \u0003ראש השנה ליכא למיגמר\u0004 \u0005[אין ללמוד]\u0006 מפני שחשובה היא ביותר, \u0003שכן\u0004 היא \u0003מכנסת זכרונות של ישראל לאביהן שבשמים\u0004 ויש אם כן להקל בה. וכן \u0003מתקיעות שופר\u0004 של \u0003יום הכפורים ליכא למיגמרי\u0004 \u0005[אין ללמוד],\u0006 שאף תקיעה זו חשובה ביותר, שכן \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003תקעו בית דין שופר\u0004 ביום הכיפורים שבשנת היובל, חלה מיד קריאת הדרור שביובל, ו\u0003נפטרו עבדים\u0004 מאדוניהם והולכים \u0003לבתיהם, ושדות\u0004 שנמכרו \u0003חוזרות לבעליהן\u0004 הראשונים, ואין ללמוד מכאן לשאר מצוות שבתורה.","שנינו מקודם ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: ה\u0003מילה וכל מכשיריה דוחין את השבת,\u0004 אלו \u0003דברי ר' אליעזר.\u0004 ושואלים: \u0003מנא ליה\u0004 \u0005[מנין\u0006 \u0003לו] לר' אליעזר הא\u0004 \u0005[\u0006הלכה \u0005זו]?\u0006 \u0003אי מכולהו גמר\u0004 \u0005[אם מכולם למד]\u0006 — יש אם כן לפרוך \u0003כדאמרינן\u0004 \u0005[כפי שאמרנו]\u0006 שבכל אחת מאלו יש צד מיוחד של חומרה. \u0003ועוד\u0004 יש להקשות: \u0003מה להנך\u0004 \u0005[לאלו]\u0006"],["\u0003שכן אם עבר זמנה בטלה,\u0004 ולא כן מצות מילה שגם אם לא נימול הילד בשמיני עדיין אפשר לקיים בו מצוות מילה לאחר מכן. \u0003אלא היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 של \u0003ר' אליעזר,\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"וביום השמיני ימול בשר ערלתו\"\u0004 (ויקרא יב, ג), ומלשון זו משמע שהוא נימול ביום השמיני מכל מקום, \u0003ואפילו\u0004 הוא חל \u0003בשבת.\u0004","ושואלים: \u0003וליכתוב רחמנא\u0004 \u0005[ושתכתוב התורה]\u0006 היתר זה \u0003במילה, וליתו הנך וליגמור מיניה\u0004 \u0005[ויבואו\u0006 שאר המצוות \u0005וילמדו ממנה]!\u0006 ומשיבים: אי אפשר ללמוד את שאר המצוות ממילה \u0003משום דאיכא למיפרך\u0004 \u0005[שיש\u0006 מקום \u0005לפרוך,\u0006 לשבור\u0005]\u0006 לימוד זה כך: \u0003מה למילה\u0004 הקילו בה \u0003שכן נכרתו עליה שלש עשרה בריתות,\u0004 ששלש עשרה פעמים נזכרה המלה \"ברית\" בפרשת המילה שנאמרה לאברהם (בראשית פרק יז), ומשום כך חשובה היא ביותר, ואין ללמוד ממנה לשאר מצוות.","לעיקרי של דין המילה שואלים: \u0003עד כאן לא\u0004 שמענו כי \u0003פליגי רבנן עליה\u0004 \u0005[נחלקו חכמים עליו]\u0006 על ר' אליעזר \u0003אלא ב\u0004ענין \u0003מכשירי מילה\u0004 שלדעתם אינם דוחים את השבת, \u0003אבל מילה גופה\u0004 \u0005[עצמה]\u0006 ל\u0003דברי הכל\u0004 היא \u0003דוחה\u0004 את ה\u0003שבת,\u0004 ודבר זה \u0003מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003אמר עולא: הלכה\u0004 למשה מסיני שכן הוא, אך אין לה רמז במקרא. \u0003וכן אמר ר' יצחק\u0004 שהיא \u0003הלכה\u0004 למשה מסיני.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו בתוספתא: \u0003מניין לפיקוח נפש שדוחה את השבת?\u0004 — \u0003ר' אלעזר בן עזריה אומר:\u0004 הדבר נלמד ממצות מילה, \u0003מה מילה שהיא\u0004 קשורה רק ל\u0003אחת מאיבריו של אדם\u0004 ובכל זאת היא \u0003דוחה את השבת\u0004 — \u0003קל וחומר לפיקוח נפש\u0004 שהיא מצוה הקשורה לכל האדם כולו \u0003שדוחה את השבת.\u0004","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר כי המילה בשבת \u0003הלכה\u0004 למשה מסיני היא — \u0003קל וחומר מהלכה\u0004 למשה מסיני \u0003מי אתי\u0004 \u0005[האם\u0006 הוא \u0005בא,\u0006 נלמד\u0005]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 מפורשת האומרת שאין ללמוד קל וחומר מהלכה למשה מסיני. ששנינו שרצה ר' עקיבא ללמד שייטמא הנזיר ויצטרך לגלח את שערו משום מגע ברביעית דם מן המת, בקל וחומר מעצם מת שגודלה כשעורה, שהלכה בידו שהנזיר מגלח על מגע בה. ו\u0003אמר לו ר' אלעזר בן עזריה: עקיבא, עצם כשעורה מטמא\u0004 משום שיש \u0003הלכה\u0004 למשה מסיני בענין זה, \u0003ורביעית דם\u0004 שאתה לומד ממנה טומאתה נלמדת מ\u0003קל וחומר, ואין דנין\u0004 (למדים) \u0003קל וחומר מהלכה\u0004 למשה מסיני. ומאחר ומפורש בתוספתא שלמד ר' אלעזר בן עזריה קל וחומר מדין מילה בשבת הרי זו הוכחה שדין זה כתוב בתורה, ואינו רק הלכה למשה מסיני.","\u0003אלא אמר ר' אלעזר: אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 הלכה זו בגזירה שווה מהשוואת המילים \u0003\"אות\" \"אות\"\u0004 הכתובות גם במילה וגם בשבת, שנאמר במילה \"ונמלתם את בשר ערלתם והיה לאות ברית ביני ובינכם\" (בראשית יז, יא), ונאמר בשבת \"אך את שבתותי תשמורו כי אות היא ביני וביניכם לדורותיכם\" (שמות לא, יג), ללמד שאות המילה מותר לעשותו אף בשבת, שגם היא אות.","ושואלים: \u0003אלא מעתה תפילין דכתיב\u0004 \u0005[שנאמר]\u0006 אף \u0003בהן \"אות\"\u0004 (\"והיו לאות על ידך ולטוטפות בין עיניך\". שמות יג, טז), אף הן \u0003לידחי\u0004 \u0005[שידחו]\u0006 את ה\u0003שבת\u0004 ויניחום \u0003אף בה!\u0004","\u0003אלא\u0004 יש לומר כי \u0003אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 הלכה זו בגזירה שווה אחרת מן המילים \u0003\"ברית\" \"ברית\"\u0004 שנאמרו במצות מילה (\"ונמלתם את בשר ערלתכם והיה לאות ברית ביני וביניכם\". בראשית יז, יא), ובשבת (\"ושמרו בני ישראל את השבת לעשות את השבת לדורותם ברית עולם\". שמות לא, טז).","ומקשים: אם כן אף \u0003גדול,\u0004 כלומר לא רק תינוק הנימול לשמונה ימים, אלא גם אדם מבוגר שלא מל עדיין, \u0003דכתיב ביה\u0004 \u0005[שנאמר\u0006 אף \u0005בו]\u0006 לשון \u0003\"ברית\"\u0004 כבכל אדם מישראל שעדיין לא נימול, \u0003לידחי\u0004 \u0005[שתדחה]\u0006 אם כן מילתו את ה\u0003שבת,\u0004 ואילו אנו יודעים שלא ניתנה שבת להידחות אלא מפני מילה בזמנה!","\u0003אלא\u0004 יש לומר \u0003כי אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 הלכה זו בגזירה שווה מן המלה \u0003\"דרות\"\u0004 הכתובה בשבת (\"לדורותם ברית עולם\" שמות לא, טז) וכתובה גם במילה (\"והקימותי את בריתי ביני ובינך ובין זרעך אחריך לדורותם לברית עולם\". בראשית יז, ז).","ושואלים: אם כן אף \u0003ציצית דכתיב ביה\u0004 \u0005[שנאמר\u0006 אף \u0005בה]\u0006 \u0003\"דורות\" לידחי\u0004 \u0005[שתדחה]\u0006 את ה\u0003שבת,\u0004 ויוכלו להטיל ציצית בשבת!","\u0003אלא אמר רב נחמן בר יצחק:\u0004 לא ממלה אחת בלבד אנו למדים, אלא \u0003דנין\u0004 משלוש המילים \u0003\"אות\" \"ברית\" ו\"דורות\" מ\"אות\" \"ברית\" ו\"דורות\" לאפוקי הנך דחד חד\u0004 \u0005[להוציא\u0006 את \u0005אלו,\u0006 ציצית תפילין \u0005ש\u0006מלה \u0005אחת אחת]\u0006 \u0003הוא דכתיב\u0004 \u0005[שנאמרה]\u0006 \u0003בהן,\u0004 ולא שלוש המלים יחד.","\u0003ור' יוחנן אמר: אמר קרא\u0004 \u0005[הכתוב]\u0006 \"ו \u0003ביום\u0004 השמיני ימול\" (ויקרא יב, ג), והכוונה היא, מכל מקום צריך הוא להימול \u0003ביום\u0004 השמיני, בכל עת, ו\u0003אפילו בשבת.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ריש לקיש לר' יוחנן: אלא מעתה מחוסרי כפרה\u0004 כגון זב ומצורע הצריכים לאחר שטבלו עוד להביא קרבן לטהרתם, \u0003דכתיב בהו\u0004 \u0005[שנאמר\u0006 אף \u0005בהם]\u0006 \u0003\"ביום\",\u0004 כגון \"וביום השמיני יקח שני כבשים תמימים וכבשה אחת בת שנתה תמימה\" (ויקרא יד, י), ואם כן \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר \u0003דדחו\u0004 \u0005[ש\u0006הם \u0005דוחים]\u0006 את ה\u0003שבת?!\u0004 השיב לו: הכתוב \u0003ההוא מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 ללמד שהבאת הקרבן תהיה \u0003ביום ולא בלילה.\u0004","והקשה: \u0003האי נמי מיבעי ליה\u0004 \u0005[זה גם כן\u0006 הפסוק במצות מילה \u0005צריך לו]\u0006 ללמדנו שתהא המילה \u0003ביום ולא בלילה!\u0004 השיב לו: \u0003ההוא\u0004 \u0005[\u0006דבר \u0005זה]\u0006 \u0003מ\u0004פסוק אחר אנו למדים, שנאמר: \"ו\u0003בן שמנת ימים\u0004 ימול לכם כל זכר לדורותיכם\" (בראשית יז, יב), ומכאן נלמד ימים ולא לילות.","ושוב מקשה ריש לקיש: \u0003האי נמי\u0004 \u0005[\u0006דבר \u0005זה,\u0006 שקרבנות הכפרה יהיו ביום \u0005גם כן]\u0006 אפשר ללמוד \u0003מ\u0004פסוק אחר, שנאמר \"זאת התורה לעולה למנחה ולחטאת ולאשם ולמילואים ולזבח השלמים. אשר ציוה ה' את משה בהר סיני \u0003ביום צותו\u0004 את בני ישראל להקריב את קרבניהם לה' במדבר סיני\" (ויקרא ז, לז–לח) ומכאן \u0003נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005]\u0006 שכל הקרבנות אינם אלא ביום ולא בלילה!","ומשיבים: \u0003אף על גב דנפקא\u0004 \u0005[אף על פי שיוצאת,\u0006 נלמדת\u0005]\u0006 הלכה זו \u0003מ\"ביום צותו\",\u0004 מכל מקום \u0003אצטריכא\u0004 \u0005[נצרכה]\u0006 חזרה נוספת לגבי מחוסרי כפרה. כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל וחס רחמנא עליה, לאתויי\u0004 \u0005[וחסה התורה עליו\u0006 על מחוסר הכפרה, \u0005להביא]\u0006 \u0003בדלות,\u0004 שבקרבנות אלה אם אין ידו של האיש משגת להביא את הקרבן הרגיל, נתנה לו התורה אפשרות שיביא קרבן זול יותר, היינו אומרים כי \u0003בלילה נמי ליתי\u0004 \u0005[גם כן יביא\u0006 קרבן\u0005]\u0006 שחסה התורה עליו לזרז כפרתו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 כי אף הוא מביא קרבנו רק ביום ולא בלילה.","\u0003מתקיף לה\u0004 \u0005[מקשה עליה\u0006 על סברה זו\u0005]\u0006 \u0003רבינא: אלא מעתה\u0004 שסבור אתה שלפי שחסה התורה על מחוסר הכפרה, והקילה הרבה בדינו, \u0003יהא\u0004 אם כן \u0003זר\u0004 (שאינו כהן) \u0003כשר\u0004 להקרבה \u0003בהן, ו\u0004כן \u0003יהא אונן\u0004 (אבל ביום הראשון למות קרובו) יהא \u0003כשר בהן!\u0004 ומשיבים: \u0003הא אהדריה קרא\u0004 \u0005[הרי החזירו הכתוב],\u0006 שכיון שבא הכתוב הנוסף והדגיש שאף מחוסר כיפורים אינו מקריב אלא ביום, מכך למדנו שלא הקלה בו התורה יתר על המפורש בו.","\u0003רב אחא בר יעקב אמר:\u0004 ראיה אחרת יש מן התורה למילה שתיעשה אפילו בשבת, שכן \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"\u0004ביום ה\u0003שמיני\",\u0004 ומהדגשת הכתוב \u0003\"שמיני\"\u0004 למדים: \u0003אפילו בשבת.\u0004","ומקשים: והלא \u0003האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 \u0003\"שמיני\" מיבעי ליה למעוטי\u0004 \u0005[נצרך לו למעט]\u0006 את היום ה\u0003שביעי,\u0004 שאין למול ילד לפני היום השמיני! ומשיבים: דבר זה שאין מלים ביום ה\u0003שביעי מ\u0004פסוק אחר, שנאמר: \"ו\u0003בן שמנת ימים\u0004 ימול לכם כל זכר\" (בראשית יז, יב) \u0003נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005].\u0006","ומקשים עוד: \u0003ואכתי מיבעי ליה, חד למעוטי\u0004 \u0005[ועדיין נצרך לו אותו כתוב, אחד למעט]\u0006 את היום ה\u0003שביעי, וחד למעוטי\u0004 \u0005[ואחד למעט]\u0006 את היום ה\u0003תשיעי. דאי מחד, הוה אמינא\u0004 \u0005[שאם\u0006 מפסוק \u0005אחד\u0006 בלבד למדתי, \u0005הייתי אומר]:\u0006 ביום ה\u0003שביעי הוא\u0004 שאין מלים בו משום \u0003שעדיין לא מטא זמניה\u0004 \u0005[הגיע זמנו]\u0006 של הילד להימול ועדיין לא חלה עליו חובת המילה, \u0003אבל מ\u0004יום ה\u0003שמיני ואילך\u0004 כיון ש\u0003זמניה\u0004 \u0005[זמנו]\u0006 \u0003הוא\u0004 ותהא אם כן המילה כשרה בו! לשאלה זו לא נמצאה תשובה, ומסכמים: \u0003אלא מחוורתא\u0004 \u0005[מחוורת,\u0006 ברורה\u0005]\u0006 הסברה \u0003כר' יוחנן.\u0004","\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' יוחנן ו\u0004ש\u0003לא כרב אחא בר יעקב.\u0004 שדורש התנא את המילים \u0003\"\u0004ה\u0003שמיני ימול\"\u0004 שכוונתן — \u0003אפילו בשבת. ומה אני מקיים\u0004 (איך אני מסביר) את איסור המלאכה המפורש במקרא \"ושמרתם את השבת כי קודש היא לכם \u0003מחלליה מות יומת\"\u0004 (שמות לא, יד) — \u0003בשאר מלאכות חוץ ממילה.\u0004 ומקשה אותו תנא עצמו על דבריו הראשונים: \u0003או אינו אלא\u0004 שאיסור השבת כולל \u0003אפילו מילה, ו\u0004להיפך: \u0003מה אני מקיים \"\u0004ה\u0003שמיני ימול\"\u0004 — בכל יום \u0003חוץ משבת? תלמוד לומר:\u0004 מאותו פסוק \u0003\"ביום\",\u0004 שכוונתו באותו היום בו הוא נעשה בן שמונה ימים, ו\u0003אפילו בשבת.\u0004 נמצא שאותו תנא דחה את ראייתו של רב אחא בר יעקב, וקיבל כראיה מכרעת את האמור \"ביום\" אפילו בשבת.","על ברייתא זו \u0003אמר רבא: האי תנא מעיקרא מאי קא ניחא ליה\u0004 \u0005[תנא זה מתחילה מה היה נוח לו],\u0006 \u0003ולבסוף מאי קא קשיא ליה\u0004 \u0005[מה היה קשה לו]?\u0006 שהרי מתחילה סבור היה ש\"השמיני ימול\" הוא לימוד מספק כדי לדחות מפניו את השבת, ולבסוף התקשה באותו דבר והיה נצרך ללימוד נוסף, ולכאורה לא לדבריו הראשונים ולא לדבריו האחרונים יש נימוק!","אלא יש לפרש כי \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003\"\u0004ה\u0003שמיני ימול\"\u0004 — \u0003אפילו בשבת. ומה אני מקיים \"מחלליה מות יומת\"\u0004 — \u0003בשאר מלאכות חוץ ממילה, אבל מילה דחיא\u0004 \u0005[דוחה]\u0006 את השבת,","\u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003קל וחומר הוא: ומה צרעת שדוחה את העבודה,\u0004 שהרי כהן מצורע אינו רשאי לעבוד במקדש, ואינו רשאי לקצוץ את נגע הצרעת, ובשל כך נדחית עבודת המקדש"],["\u0003ועבודה דוחה את השבת,\u0004 שכן מקריבים את קרבנות השבת בזמנם, ובכל זאת \u0003מילה דוחה אותה\u0004 את הצרעת, שאם היה נגע הצרעת במקום הערלה מותר למול את הילד, אף על פי שנעקר בזה האיסור שלא לקצוץ את נגע הצרעת, אם כן \u0003שבת שנדחית מפני העבודה, אינו דין שתהא\u0004 מצות \u0003מילה\u0004 החמורה כל כך \u0003דוחה\u0004 אף \u0003אותה?\u0004 זה היה נימוקו של התנא מתחילה.","\u0003ומאי\u0004 \u0005[ומהו]\u0006 לשון \u0003\"או אינו\" דקאמר\u0004 \u0005[שאמר]\u0006 התנא, ופקפק בדברי עצמו — שכן \u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר: וממאי\u0004 \u0005[וממה,\u0006 מנין\u0005]\u0006 אפשר להסיק ש\u0003צרעת חמורה\u0004 מן השבת? \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003שבת חמורה, שכן יש בה עונשין\u0004 חמורים של כרת ומיתת בית דין \u0003ואזהרות הרבה\u0004 פעמים רבות בתורה. \u0003אי נמי\u0004 \u0005[או גם כן]:\u0006 \u0003וממאי\u0004 \u0005[וממה,\u0006 מנין\u0005]\u0006 אתה יודע שדבר זה בא \u0003משום דחמירא\u0004 \u0005[שחמורה]\u0006 ה\u0003צרעת היא\u0004 שאף העבודה אינה דוחה אותה, \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003משום\u0004 ש\u0003גברא\u0004 \u0005[האיש]\u0006 \u0003הוא דלא חזי\u0004 \u0005[שאינו ראוי],\u0006 שלא מחמת חומרת האיסור שיש בצרעת אין העבודה דוחה אותה, אלא משום שאותו אדם אינו ראוי אז לעבודה ואין מקום לדחיה. \u0003ו\u0004לכן \u0003מה אני מקיים \"\u0004וביום ה\u0003שמיני ימול\"\u0004 (ויקרא יב, ג) — \u0003חוץ משבת.\u0004 על כן \u0003תלמוד לומר,\u0004 היה צריך להביא ראיה נוספת מן הכתוב \u0003\"ביום\"\u0004 — \u0003אפילו בשבת.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מילה דוחה את הצרעת\u0004 שחותכים את הערלה אף אם היה בה נגע צרעת, אף שכרגיל איסור תורה הוא לקצוץ נגעי צרעת, \u0003בין\u0004 שהיתה זו מילה \u0003בזמנה\u0004 לשמונה ימים \u0003בין שלא בזמנה,\u0004 אחרי שמונה ימים. ואולם המילה את \u0003יום טוב אינה דוחה אלא\u0004 כשהיא \u0003בזמנה\u0004 בלבד.","ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין דברים אלה]?\u0006 \u0003דתנו רבנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 נאמר \u0003\"\u0004וביום השמיני \u0003ימול בשר ערלתו\",\u0004 וכיון שדבר זה נאמר בהכללה, \u0003ואף על פי שיש שם בהרת,\u0004 שהיא אחד מנגעי הצרעת, \u0003יקוץ\u0004 (יקצוץ). \u0003ומה אני מקיים\u0004 (ואיך אני מסביר) את דברי הכתוב \u0003\"השמר בנגע הצרעת\u0004 לשמור מאוד ולעשות ככל אשר יורו אתכם הכהנים הלוים כאשר צויתים תשמרו לעשות\u0003\"\u0004 (דברים כד, ח), שממנו למדנו שיש מצות לא תעשה (\"השמר\" שמשמעו — להמנע מעשייה) האוסרת על קציצת סימני הצרעת — נקיים איסור זה \u0003בשאר מקומות, חוץ ממילה.\u0004","וחזר התנא ושאל: \u0003או אינו אלא\u0004 שאיסור זה כולל \u0003אפילו מילה, ומה אני מקיים \"ימול בשר ערלתו\"\u0004 — \u0003בזמן שאין בה בהרת.\u0004 על כן \u0003תלמוד לומר\u0004 מייתור הלשון: \u0003\"בשר\",\u0004 שלכאורה די היה לומר \"ימול ערלתו\" ואמר \"ימול בשר ערלתו\", ללמדנו שצריך להימול \u0003ואף על פי שיש שם\u0004 במקום המילה \u0003בהרת.\u0004","\u0003אמר רבא: האי תנא מעיקרא מאי ניחא ליה\u0004 \u0005[תנא זה מתחילה מה היה נוח לו]\u0006 \u0003ולבסוף מאי קשיא ליה\u0004 \u0005[מה היה קשה לו]?\u0006","שקודם קיבל את ההנחה האחת שמצות המילה חשובה יותר, ואחר כך חזר ודחה הנחה זו ללא טעם, אלא יש לבאר, כי \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך סבור היה מתחילה: \u0003\"ימול בשר ערלתו\"\u0004 — שמותר למול \u0003ואף על פי שיש\u0004 שם \u0003בהרת,\u0004 ומילה דוחה את הצרעת. \u0003ומה אני מקיים\u0004 את דברי הכתוב \u0003\"השמר בנגע הצרעת\"\u0004 — \u0003בשאר מקומות חוץ ממילה. אבל מילה דוחה את הצרעת. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003דאתיא\u0004 \u0005[שבאה,\u0006 נלמדת\u0005]\u0006 סברה זו \u0003מ\u0004תוך \u0003קל וחומר: ומה שבת\u0004 שהיא \u0003חמורה,\u0004 ובכל זאת \u0003מילה דוחה אותה, צרעת\u0004 שאינה חמורה כל כך \u0003לא כל שכן\u0004 שתדחה אותה המילה.","\u0003ומאי\u0004 \u0005[ומהו]\u0006 \u0003\"או אינו\" דקאמר\u0004 \u0005[שאמר]\u0006 — \u0003הדר קאמר\u0004 \u0005[חזר\u0006 ו\u0005אמר]\u0006 והעלה ספק זה: \u0003ממאי\u0004 \u0005[ממה,\u0006 מנין\u0005]\u0006 יודע אתה ש\u0003שבת חמירא\u0004 \u0005[חמורה]\u0006 יותר, \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003צרעת חמירא\u0004 \u0005[חמורה]\u0006 יותר, \u0003שכן\u0004 הצרעת \u0003דוחה את העבודה\u0004 כאמור, \u0003ועבודה דוחה את השבת!\u0004 על כן \u0003תלמוד לומר\u0004 לימוד מיוחד מהמלה המיותרת \u0003\"בשר\"\u0004 ללמד: \u0003ואף על פי שיש שם בהרת\u0004 מכל מקום מלים.","דברי רבא נאמרו גם ב\u0003לישנא אחרינא\u0004 \u0005[לשון אחרת].\u0006 תחילה סבר התנא ש\u0003מילה דוחה את הצרעת. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — בהסתמך על הכלל \u0003דאתי\u0004 \u0005[שבאה]\u0006 מצות \u0003עשה ודחי\u0004 \u0005[ודוחה]\u0006 את מצות \u0003לא תעשה. ומאי\u0004 \u0005[ומהו]\u0006 \u0003\"או אינו\" דקאמר\u0004 \u0005[שאמר]\u0006 — \u0003הדר קאמר\u0004 \u0005[חזר\u0006 ו\u0005אמר]\u0006 והעלה ספק זה: \u0003אימר דאמרינן דאתי\u0004 \u0005[אמור שאנו אומרים ש\u0006כרגיל \u0005באה]\u0006 מצות \u0003עשה ודחי\u0004 \u0005[ודוחה]\u0006 \u0003את\u0004 מצות \u0003לא תעשה\u0004 — הרי זה במצות \u0003לא תעשה גרידא\u0004 \u0005[בלבד],\u0006 ואולם \u0003האי\u0004 \u0005[\u0006איסור \u0005זה]\u0006 קציצת הצרעת גם מצות \u0003עשה ו\u0004גם \u0003לא תעשה הוא, ומה אני מקיים\u0004 את הנאמר \u0003\"ימול בשר ערלתו\"\u0004 — רק \u0003בזמן שאין שם בהרת,\u0004 על כן \u0003תלמוד לומר\u0004 המלה המיותרת \u0003\"בשר\",\u0004 לומר: \u0003ואף על פי שיש שם בהרת.\u0004","על עצם הלימוד מן המלה \"בשר\" שואלים: \u0003תינח\u0004 \u0005[נניח]\u0006 במילת אדם \u0003גדול\u0004 שעדיין לא נימול, \u0003דכתיב בהו\u0004 \u0005[שנאמר בהם,\u0006 בו\u0005]\u0006 \u0003\"בשר\",\u0004 כאמור \"וערל זכר אשר לא ימול את בשר ערלתו ונכרתה הנפש ההיא מעמיה את בריתי הפר\" (בראשית יז, יד). \u0003קטן\u0004 הנימול ביום השמיני \u0003נמי כתיב ביה\u0004 \u0005[גם כן נאמר בו]\u0006 \u0003\"בשר\",\u0004 ואולם \u0003בינוני,\u0004 ילד שלא נימול בזמנו ועדיין לא הגיע למצוות, \u0003מנא לן\u0004 \u0005[מנין לו]\u0006 שמילתו דוחה את הצרעת? שהרי ודאי הוא צריך להימול, שכן נאמר במפורש במקרא \"המול לכם כל זכר\" (בראשית י\"ז, י) ולא נאמר בו \"בשר\",","\u0003אמר אביי: אתיא מביניא\u0004 \u0005[באה,\u0006 נלמדת \u0005מביניהם],\u0006 כלומר, מצירוף שתי ההלכות יחד למדים אנו גם לגבי בינוני. ובאופן זה: \u0003מגדול\u0004 בלבד \u0003לא אתיא\u0004 \u0005[אין\u0006 הדבר \u0005בא,\u0006 נלמד\u0005],\u0006 \u0003שכן\u0004 אפשר לטעון שהוא \u0003ענוש כרת\u0004 אם לא ימול, וכן \u0003מקטן לא אתיא\u0004 \u0005[אינה באה,\u0006 נלמדת\u0005],\u0006 \u0003שכן\u0004 זוהי \u0003מילה בזמנה,\u0004 ואם שבת היא דוחה — דוחה גם צרעת. ואולם \u0003הצד השוה שבהן\u0004 — \u0003שכן נימולין ודוחין את הצרעת, אף כל\u0004 אלה \u0003שנימולין\u0004 — \u0003דוחין את הצרעת.\u0004","\u0003רבא אמר:\u0004 ש\u0003מילה בזמנה דוחה\u0004 את הצרעת \u0003לא צריכא קרא\u0004 \u0005[צריך פסוק]\u0006 ללמד על כך, שכן \u0003מקל וחומר אתיא\u0004 \u0005[\u0006היא \u0005נלמדת]:\u0006 \u0003ומה שבת דחמירא\u0004 \u0005[ש\u0006היא \u0005חמורה]\u0006 \u0003דוחה\u0004 אותה המילה — \u0003צרעת לא כל שכן\u0004 שדוחה אותה המילה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב ספרא לרבא: ממאי\u0004 \u0005[ממה,\u0006 מנין\u0005]\u0006 אתה למד ש\u0003שבת חמירא\u0004 \u0005[חמורה]\u0006 יותר, \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003צרעת חמירא\u0004 \u0005[חמורה]\u0006 יותר, \u0003שכן\u0004 הצרעת \u0003דוחה את העבודה\u0004 במקדש, \u0003ועבודה דוחה את השבת!\u0004 ענה לו רבא: \u0003התם, לאו\u0004 \u0005[שם, לא]\u0006 \u0003משום דחמירא\u0004 \u0005[שחמורה]\u0006 ה\u0003צרעת\u0004 יותר הוא, \u0003אלא משום דגברא\u0004 \u0005[שהאדם]\u0006 \u0003הוא דלא חזי\u0004 \u0005[שאינו ראוי].\u0006 ושאל רב ספרא: \u0003אמאי\u0004 \u0005[מדוע]\u0006 אינו ראוי: \u0003ויקוץ בהרתו\u0004 ויהא מיד ראוי \u0003ויעבוד!\u0004 ענה לו רבא: עדיין אינו ראוי לעבודה שכן \u0003מחוסר טבילה הוא,\u0004 שכדי להטהר לעבודה במקדש חייב הוא לטבול ולחכות עד למחרת, ונמצא שבינתיים אינו ראוי.","והקשה רב ספרא: \u0003תינח\u0004 \u0005[נניח]\u0006 שתירוץ זה מספיק כשמדובר ב\u0003נגעים טמאים,\u0004 שאף מי שנטהר מהם צריך לטבול אחר כך, ואולם \u0003נגעים טהורים\u0004 שאף הם נאסרו בקציצה, ואולם אינם בגדר צרעת המטמאה, אלא בגדר מום בלבד הפוסל את הכהן, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שהרי בהם אפשר היה שיקוץ בהרתו ויעבוד מיד במקדש!","\u0003אלא אמר רב אשי:\u0004 לא זה הטעם, אלא \u0003היכא אמרינן דאתי\u0004 \u0005[היכן אנו אומרים שבאה]\u0006 מצות \u0003עשה ודחי\u0004 \u0005[ודוחה]\u0006 את מצות \u0003לא תעשה\u0004 — \u0003כגון מילה בצרעת, אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003ציצית וכלאים\u0004 שמטיל ציציות צמר בבגד פשתן, \u0003דבעידנא דמתעקר לאו קא מוקים\u0004 \u0005[שבזמן שנעקר\u0006 איסור \u0005לא\u0006 תעשה, \u0005מתקיימת]\u0006 על ידי אותה פעולה עצמה מצות ה\u0003עשה,\u0004 ואולם \u0003הכא, בעידנא דמתעקר ללאו לא קא מוקים\u0004 \u0005[כאן, בזמן שנעקר הלאו אינו מקיים]\u0006 את ה\u0003עשה,\u0004 שהרי אינו אלא מכשיר עצמו לעבודה, אבל ברגע הקציצה אינו מקיים מצוה כל שהיא. ובמקרה זה אין עשה דוחה את לא תעשה.","\u0003ו\u0004מעירים כי \u0003הא\u0004 \u0005[זה],\u0006 אותם חילוקי הדעות בין \u0003רבא ורב ספרא\u0004"],["\u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 לשון הכתוב \u0003\"בשר\"\u0004 בא ללמד כי \u0003ואף על פי שיש שם בהרת\u0004 — \u0003ימול,\u0004 אלו \u0003דברי ר' יאשיה. ר' יונתן אומר: אינו צריך\u0004 לריבוי זה במקרא, אלא ניתן הדבר ללימוד בדרך קל וחומר, שכן אם \u0003שבת\u0004 שהיא \u0003חמורה\u0004 — \u0003דוחה\u0004 אותה המילה, \u0003צרעת\u0004 — \u0003לא כל שכן.\u0004","קודם לכן שנינו ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 מה שנאמר \u0003\"בשר\"\u0004 בא ללמד ש\u0003אף על פי שיש שם בהרת\u0004 — \u0003ימול,\u0004 אלו \u0003דברי ר' יאשיה.\u0004 ואף ר' יונתן סובר כן מטעם אחר. ומתעוררת השאלה העקרונית: \u0003הא\u0004 \u0005[\u0006דבר \u0005זה]\u0006 \u0003למה לי קרא\u0004 \u0005[הכתוב]\u0006 לכותבו, והלא \u0003דבר שאין מתכוין הוא,\u0004 שהרי אין כוונתו לחתוך את נגע הצרעת אלא למול את התינוק, \u0003ו\u0004כלל הוא שכל \u0003דבר שאין מתכוין\u0004 לו — \u0003מותר,\u0004 ואם כן אין צורך בהוכחה מיוחדת במקרה זה!","\u0003אמר אביי: לא נצרכא\u0004 \u0005[נצרך]\u0006 לימוד זה לימוד זה \u0003אלא ל\u0004דברי \u0003ר' יהודה\u0004 ש\u0003אמר\u0004 ככלל: \u0003דבר שאין מתכוין\u0004 — \u0003אסור.\u0004 ואילו \u0003רבא אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שהלכה זו גם כ\u0003ר' שמעון\u0004 הסבור ש\"דבר שאין מתכוין — מותר\", ואולם \u0003מודה ר' שמעון ב\"פסיק רישיה\u0004 \u0005[חתוך ראשו]\u0006 \u0003ולא ימות\",\u0004 כלומר, שאם זו תוצאה הכרחית מן המעשה, אין העושה יכול לאמר שלא נתכוון לתוצאה זו. ובמילה במקום הצרעת, קציצת הנגע היא תוצאה הכרחית. ושואלים: \u0003ואביי, לית ליה האי סברא\u0004 \u0005[אין לו,\u0006 אינו מקבל \u0005סברה זו]?\u0006 \u0003והא\u0004 \u0005[והר\u0006 \u0005י]\u0006 \u0003אביי ורבא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 ש\u0003מודה ר' שמעון ב\"פסיק רישיה\u0004 \u0005[חתוך ראשו]\u0006 \u0003ולא ימות\"!\u0004 ומשיבים: \u0003בתר\u0004 \u0005[לאחר]\u0006 שאביי \u0003שמעה\u0004 להלכה זו \u0003מרבא סברה\u0004 \u0005[קיבל אותו].\u0006","\u0003איכא דמתני להא\u0004 \u0005[יש שהיה שונה את\u0006 דברים \u0005אלו]\u0006 של \u0003אביי ורבא אהא\u0004 \u0005[על\u0006 ברייתא \u0005זו]:\u0006 נאמר \u0003\"השמר בנגע הצרעת לשמר מאד ולעשות\u0004 ככל אשר יורו אתכם הכהנים הלויים כאשר צויתים תשמרו לעשות\u0003\"\u0004 (דברים כד, ח). ולמדו מכאן: \u0003לעשות\u0004 ולחתוך את הנגע \u0003אי\u0004 (אין) \u0003אתה עושה\u0004 מעשה במיוחד לצורך זה, \u0003אבל עושה אתה\u0004 שיסור הנגע בעקיפין \u0003בסיב\u0004 (חבל גס) \u0003שעל גבי רגלו, ובמוט שעל גבי כתיפו\u0004 אף שיש שם בהרת. \u0003ואם עברה\u0004 הבהרת — \u0003עברה.\u0004","ושואלים: \u0003והא\u0004 \u0005[ו\u0006דבר \u0005זה]\u0006 \u0003למה לי קרא\u0004 \u0005[פסוק]\u0006 ללמדני אותו, והרי \u0003דבר שאין מתכוין הוא, ודבר שאין מתכוין\u0004 — \u0003מותר!\u0004 ועל ברייתא זו \u0003אמר אביי: לא נצרכא\u0004 \u0005[נצרכה]\u0006 הלכה זו להיאמר \u0003אלא ל\u0004שיטת \u0003ר' יהודה,\u0004 ש\u0003אמר: דבר שאין מתכוין\u0004 — \u0003אסור. ורבא אמר\u0004 ששיטה זו \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהיא כשיטת ר' \u0003שמעון, ו\u0004אולם \u0003מודה ר' שמעון ב\"פסיק רישיה\u0004 \u0005[חתוך\u0006 ראשו] \u0003ולא ימות\",\u0004 שהוא מודה בתוצאה המחוייבת מן הדברים שהעושה חייב. ושואלים: \u0003ו\u0004כי \u0003אביי, לית ליה האי סברא\u0004 \u0005[אין לו,\u0006 אינו מקבל \u0005סברה זו]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אביי ורבא דאמרי תרווייהו\u0004 \u0005[שאמרו שניהם]\u0006 ש\u0003מודה ר' שמעון ב\"פסיק רישיה\u0004 \u0005[חתוך\u0006 ראשו] \u0003ולא ימות \"!\u0004 ומשיבים: אף אביי \u0003לבתר דשמעיה\u0004 \u0005[לאחר ששמעה]\u0006 לסברה זו \u0003מרבא סברה\u0004 \u0005[קיבלה]\u0006 אף הוא.","ועוד מבררים: \u0003ואביי\u0004 לסברתו הראשונה \u0003אליבא\u0004 \u0005[לפי שיטת]\u0006 \u0003ר' שמעון,\u0004 שהבינה אביי שאם אינו מתכוון לדבר, אפילו התוצאה מחוייבת ממנו אין בכך איסור, \u0003האי\u0004 \u0005[\u0006פסוק \u0005זה]\u0006 בענין מילה שנאמר בו \u0003\"בשר\" מאי עביד ליה\u0004 \u0005[מה\u0006 הוא \u0005עושה בו]?\u0006 \u0003אמר רב עמרם:\u0004 לימוד זה בא לומר שאפילו \u0003ב\u0004מקרה ש\u0003אומר\u0004 אותו אדם המל את עצמו במפורש ש\u0003לקוץ\u0004 את \u0003בהרתו הוא מתכוין\u0004 — אף על פי כן מילה דוחה את הצרעת.","ושואלים: \u0003תינח\u0004 \u0005[נניח]\u0006 ב\u0003גדול\u0004 שמתכוון לעשות דבר אסור, אבל במילת \u0003קטן מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שהרי הקטן איננו מתכוון כלל! \u0003אמר רב משרשיא: באומר אבי הבן\u0004 כי \u0003לקוץ\u0004 את ה\u0003בהרת\u0004 של \u0003בנו הוא קא מתכוין.\u0004","ושואלים: אף במקרה זה, \u0003אי איכא\u0004 \u0005[אם יש]\u0006 אדם \u0003אחר\u0004 המסוגל למול את הילד \u0003ליעביד\u0004 \u0005[שיעשה]\u0006 \u0003אחר!\u0004 ואותו אדם מן הסתם אינו מתכוון לקציצת הבהרת אלא לקיום מצות מילה, ולא תיעשה כאן עבירה כלל. שכן \u0003אמר ר' שמעון בן לקיש: כל מקום שאתה מוצא\u0004 מצוות \u0003עשה ולא תעשה\u0004 המתנגשות זו בזו — \u0003אם אתה יכול לקיים\u0004 את \u0003שניהם\u0004 בדרך כלשהי, \u0003מוטב, ואם לאו\u0004 \u0005[לא],\u0006 שאינך יכול — \u0003יבא עשה וידחה\u0004 את \u0003לא תעשה.\u0004 ואף כאן אפשר לקיים גם עשה וגם לא תעשה על ידי אחר! ומשיבים: מדובר באופן \u0003דליכא\u0004 \u0005[שאין]\u0006 \u0003אחר,\u0004 אלא אבי הבן לבדו הוא המסוגל למול אותו, ומשום כך היה צורך לכתוב מפורש שילמדנו שהמילה דוחה את הצרעת.","קודם שנינו ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 שב\u0003יום טוב\u0004 המילה \u0003אינה דוחה\u0004 אותו \u0003אלא\u0004 כשהיא נעשית \u0003בזמנה\u0004 (ביום השמיני ללידתו) \u0003בלבד.\u0004 ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין דברים אלו]?\u0006","\u0003אמר חזקיה, וכן תנא דבי\u0004 \u0005[\u0006שנה \u0005החכם מבית\u0006 מדרשו\u0005]\u0006 של \u0003חזקיה אמר קרא\u0004 \u0005[הכתוב]\u0006 בענין קרבן הפסח \u0003\"לא תותירו ממנו עד בקר\u0004 והנותר ממנו עד בוקר באש תשרופו\u0003\"\u0004 (שמות יב, י), ודקדקו: \u0003שאין תלמוד לומר \"עד בקר\"\u0004 פעמיים, ו\u0003מה תלמוד לומר \"עד בקר\"\u0004 השני — \u0003בא הכתוב ליתן לו בקר שני לשריפתו,\u0004 שהנותר עד בוקר החג אין שורפים אותו בו ביום, אלא דוחים את שריפתו עד היום שלאחר החג, שאין שורפים את פסולי הקדשים ביום טוב. ומכאן למדים שאף שמלאכת הבערת אש לא נאסרה כליל ביום טוב ומותר לבשל ולאפות, מכל מקום לא הותרה הבערה שלא לצורך אוכל נפש. וכן המילה, כיון שיש בה מלאכה לא הותרה אלא ביום השמיני, שאין אפשרות לדחותה.","\u0003אביי אמר\u0004 ראיה אחרת, שכן \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"עלת שבת בשבתו\u0004 על עולת התמיד ונסכה\u0003\"\u0004 (במדבר כח, י), \u0003ו\u0004מכאן אנו למדים ש\u0003לא\u0004 מקריבים \u0003עולת חול בשבת ו\u0004אף \u0003לא עולת חול ביום טוב.\u0004 נמצא שאף שמותרת השחיטה ביום טוב לצורך אוכל נפש, מכל מקום אסורה היא בקרבנות, ואף במילה לא הותר חיתוך זה כיון שאיננו הכרחי בו ביום.","\u0003רבא אמר\u0004 ראיה אחרת: כי בענין יום טוב \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"\u0004מקרא קודש יהיה לכם כל מלאכה לא ייעשה בהם אך אשר ייאכל לכל נפש \u0003הוא לבדו יעשה לכם\"\u0004 (שמות יב, טז), ומן ההדגשות היתירות למדים אנו כי \u0003\"הוא\"\u0004 כוונתו שמותרים אף דברים לצורך החג — \u0003ו\u0004אולם \u0003לא מכשירין\u0004 וכלים לצורך אכילה שהם אסורים. \u0003\"לבדו\"\u0004 — \u0003ולא מילה שלא בזמנה, דאתיא\u0004 \u0005[\u0006שאף על פי \u0005ש\u0006היא \u0005באה,\u0006 נלמדת\u0005]\u0006 \u0003מקל וחומר\u0004 שמילה שלא בזמנה תדחה יום טוב, הרי הדגיש הכתוב \"הוא לבדו\" — ולא דברים אחרים.","\u0003רב אשי אמר:\u0004 כיון שיש במצוות החג לא רק מצות לא תעשה כי אם גם מצות עשה, שכן \u0003\"שבתון\"\u0004 שנאמר — \u0003עשה הוא, והוה ליה\u0004 \u0005[ונהיה,\u0006 נעשה \u0005לו]\u0006 \u0003יום טוב\u0004 גם \u0003עשה ו\u0004גם \u0003לא תעשה, ו\u0004כלל הוא ש\u0003אין עשה דוחה את לא תעשה ועשה\u0004 המצויים במצוה אחרת.","שנינו במשנה ש\u0003כלל אמר ר' עקיבא:\u0004 כל דבר שאי אפשר לעשותו מבעוד יום — מותר לעשותו בשבת, אבל מכשירי המצוה שניתן לעשותם מערב שבת אסור לעשות בשבת. \u0003אמר רב יהודה\u0004 שכך \u0003אמר רב: הלכה כ\u0004שיטת \u0003ר' עקיבא\u0004 בענין זה.","\u0003ותנן נמי גבי\u0004 \u0005[ושנינו\u0006 במשנה \u0005גם כן אצל]\u0006 ענין \u0003פסח כי האי גוונא\u0004 \u0005[כעין זה]:\u0006 \u0003כלל אמר ר' עקיבא: כל מלאכה שאפשר לה לעשותה מערב שבת\u0004 — \u0003אינה דוחה את השבת.\u0004 ולעומת זאת \u0003שחיטה\u0004 של הקרבן \u0003שאי אפשר לעשותה מערב שבת,\u0004 שהרי קבוע לה זמן מן התורה — \u0003דוחה את השבת. ואמר רב יהודה\u0004 שכך \u0003אמר רב: הלכה כר' עקיבא.\u0004","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 להודיענו פעמים שהלכה כר' עקיבא. \u0003דאי אשמעינן גבי\u0004 \u0005[שאם היה משמיע לנו\u0006 שהלכה כר' עקיבא \u0005אצל]\u0006 \u0003מילה,\u0004 היינו אומרים: \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא\u0004 ש\u0003מכשירין\u0004 ש\u0003אפשר לעשות מאתמול לא דחו\u0004 \u0005[דוחים]\u0006 את ה\u0003שבת\u0004 משום \u0003דליכא\u0004 \u0005[שאין]\u0006 עונש \u0003כרת\u0004 גם אם ידחו את המילה, שהרי אין חיוב כרת אלא לכשיגדל הילד ויגיע לחיוב במצוות. \u0003אבל פסח דאיכא\u0004 \u0005[שיש]\u0006 בו \u0003כרת\u0004 — \u0003אימא לידחו\u0004 \u0005[אמור\u0006 אם כן \u0005שידחו]\u0006 המכשירין את ה\u0003שבת,\u0004 על כן היה צורך להשמיע גם בהלכות פסח.","\u0003ואי אשמעינן גבי\u0004 \u0005[ואם היה משמיע לנו אצל]\u0006 \u0003פסח\u0004 בלבד, הייתי אומר שכך הדין \u0003משום\u0004 ש\u0003לא נכרתו עליה,\u0004 על מצות הפסח \u0003שלש עשרה בריתות,\u0004 ואינה חשובה כל כך. \u0003אבל מילה\u0004 ש\u0003נכרתו עליה שלש עשרה בריתות\u0004 — \u0003אימא לידחו\u0004 \u0005[אמור שידחו]\u0006 את ה\u0003שבת,\u0004 על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 היה להודיענו הלכה זו בשני המקרים.","תינוק שהיום השמיני ללידתו חל בשבת וצריך להימול בו ביום, \u0003עושין\u0004 את \u0003כל צרכי\u0004 ה\u0003מילה\u0004 אף \u0003בשבת: מוהלין\u0004 את הערלה \u0003ופורעין\u0004 מסירים את העור החופה את הערלה \u0003ומוצצין\u0004 את הדם משם \u0003ונותנין עליה איספלנית\u0004 (תחבושת) \u0003וכמון\u0004 לרפואה.","ו\u0003אם לא שחק\u0004 את הכמון \u0003מערב שבת\u0004 — \u0003לועס\u0004 אותו \u0003בשיניו ונותן\u0004 אותו על מקום המילה לרפואה. \u0003אם לא טרף\u0004 \u0005[עירב]\u0006 \u0003יין ושמן מערב שבת\u0004 שהיו עושין תערובת זו לרפואה ולחיזוק — \u0003ינתן זה\u0004 היין \u0003בעצמו וזה\u0004 השמן \u0003בעצמו.\u0004","\u0003ואין עושין לה\u0004 למילה \u0003חלוק\u0004 (כעין כיס לתחבושת) \u0003לכתחילה\u0004 בשבת, \u0003אבל כורך עליה סמרטוט\u0004 לחבישה. \u0003אם לא התקין\u0004 (הכין) את התחבושת \u0003מערב שבת\u0004 שתהא במקום שנעשית בו המילה — \u0003כורך על אצבעו\u0004 את התחבושת \u0003ומביא\u0004 אותה בשבת, \u0003ואפילו מחצר אחרת.\u0004 שאף שהתירו את ההבאה, מכל מקום הצריכו לעשות בה שינוי להביאה כדרך מלבוש."],["ושואלים על המשנה \u0003מכדי קתני כולהו\u0004 \u0005[הלא שנה\u0006 את \u0005כולם]\u0006 שאת כל הדברים הנצרכים למילה פירט במשנה, ואם כן מה שהוסיף אחר כך \u0003\"\u0004ועושים בשבת \u0003כל צורכי מילה\" לאתויי מאי\u0004 \u0005[להביא,\u0006 להוסיף את \u0005מה]\u0006 בא?","ומשיבים: \u0003לאתויי הא\u0004 \u0005[להביא,\u0006 להוסיף דבר \u0005זה]\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 \u0003המל\u0004 בשבת \u0003כל זמן שהוא עוסק במילה\u0004 — \u0003חוזר\u0004 ומתקן חתיכות עור שלא חתך כראוי, \u0003בין\u0004 כשהיו אלה \u0003על הציצין\u0004 (חתיכות עור ובשר) \u0003המעכבין את המילה,\u0004 שאין הילד נחשב נימול אם הושארו, \u0003בין על הציצין שאין מעכבין את המילה.\u0004 ואולם אם \u0003פירש\u0004 מן המילה הרי \u0003על ציצין המעכבין את המילה\u0004 — \u0003חוזר,\u0004 שהרי עדיין לא נעשתה המצווה כתיקונה, ואולם \u0003על ציצין שאין מעכבין את המילה\u0004 — שוב \u0003אינו חוזר.\u0004 ואם כן, \"כל צרכי מילה\" פירושו לפי הסבר זה תיקון המילה אפילו בציצין שאינן מעכבין כשהוא עדיין עוסק במילה.","ולעיקר דין זה שואלים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 הסבור כי כאשר כבר \u0003פירש\u0004 אדם מן העיסוק במצוה שוב \u0003אינו חוזר?\u0004 כלומר, מיהו המעלה את הסברה שכל עוד אדם עסוק במצוה שהותר לו לעשותה בשבת יכול הוא להשלימה, אבל כרגיל אין עושים בשבת אפילו מצוה מעבר לשיעורה ההכרחי אם יש בכך חילול שבת. \u0003אמר רבה בר בר חנה\u0004 שכך \u0003אמר ר' יוחנן:\u0004 דעה זו שיטת \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקה היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ארבעה עשר\u0004 בניסן שהוא יום הקרבת קרבן הפסח \u0003שחל להיות בשבת\u0004 — \u0003מפשיט אדם\u0004 את \u0003הפסח עד החזה\u0004 כדי להוציא מתוכו את החלקים הבאים למזבח, ואינו מפשיט יותר, כיון שאין הדבר הכרחי למצות היום, אלו \u0003דברי ר' ישמעאל בנו של ר' יוחנן בן ברוקה. וחכמים אומרים: מפשיטין\u0004 אף \u0003את כולו.\u0004","על השוואה זו מקשים: \u0003ממאי\u0004 \u0005[ממה]\u0006 בא אתה להשוות? שמא \u0003עד כאן לא\u0004 שמענו \u0003כי קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקה התם\u0004 \u0005[שם]\u0006 שאינו עושה יותר מכדי הצורך אלא \u0003משום דלא בעינן\u0004 \u0005[שאין אנו צריכים]\u0006 בענין זה לקיים \u0003\"זה אלי ואנוהו\",\u0004 שאיננו צריכים להדר בהפשטה, שהרי לצורך מצות ההקרבה אין הבדל באופן ההפשטה. \u0003אבל הכא דבעינן\u0004 \u0005[אבל כאן\u0006 במילה \u0005שאנו צריכים]\u0006 לקיים \u0003\"זה אלי ואנוהו\",\u0004 לעשות את מצות המילה בהידור יתר, אם כן \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 יודה ר' ישמעאל שיש לעשות את המצווה בדרך המהודרת ביותר.","ומהי מקור הלכה זו של \"זה אלי ואנוהו\" — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 ממה שנאמר \u0003\"זה אלי ואנוהו\u0004 אלהי אבי וארוממנהו\u0003\"\u0004 (שמות טו, ג) דרשו חכמים: \"אנווהו\" מלשון נוי, ולמעשה: \u0003התנאה לפניו במצות,\u0004 שאף שהמצווה כשרה גם באופן אחר, מכל מקום ראוי לעשותה נאה ככל האפשר. וכגון: \u0003עשה לפניו סוכה נאה, ולולב נאה, ושופר נאה, ציצית נאה,\u0004 ו\u0003ספר תורה נאה\u0004 בקלפו, \u0003וכתוב בו לשמו בדיו נאה, בקולמוס נאה, בלבלר אומן וכורכו\u0004 את הספר \u0003בשיראין\u0004 (אריג משי) \u0003נאין.\u0004","\u0003אבא שאול אומר: \"ואנוהו\"\u0004 — יש לפרש כמו \"אני והוא\", לאמור \u0003הוי דומה\u0004 כביכול \u0003לו\u0004 לקדוש ברוך הוא, \u0003מה הוא חנון ורחום\u0004 — \u0003אף אתה היה חנון ורחום.\u0004 ומכל מקום לענייננו אין להוכיח מדברי ר' ישמעאל, שייכן שבמצות מילה מודה אף הוא.","\u0003אלא אמר רב אשי:\u0004 יש לראות את הדברים בשיטה אחרת, ו\u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 שבענין מילה \u0005של מי היא]\u0006 —כשיטת \u0003ר' יוסי היא, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003בין שנראה\u0004 הירח החדש \u0003בעליל\u0004 (בגלוי, לעיני כל), \u0003ובין שלא נראה בעליל\u0004 — \u0003מחללין עליו את השבת,\u0004 שעדי הראייה שראו את מולד הירח מחללים את השבת אם צריכים הם לכך כדי להגיע למקום מושב בית הדין ולהעיד. \u0003ר' יוסי אומר:\u0004 אם \u0003נראה\u0004 הירח \u0003בעליל\u0004 — \u0003אין מחללין עליו את השבת,\u0004 שבוודאי כבר העידו עדים אחרים שמקומם קרוב יותר למושב הסנהדרין, ונמצא שאם יבואו אלו הרחוקים להעיד יחללו את השבת שלא לצורך. ואם כן הרי שסבור ר' יוסי אם נעשה כבר עיקרה של המצווה — שוב אין מחללין את השבת.","ודוחים את ההשוואה: \u0003ממאי\u0004 \u0005[ממה]\u0006 אתה מסיק זאת? \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003עד כאן לא\u0004 \u0005[שמענו]\u0006 כי \u0003קאמר ר' יוסי התם\u0004 \u0005[שם]\u0006 בעדות החודש כך אלא משום ש\u0003לא ניתנה שבת לידחות,\u0004 שכיון שנראה הירח בעליל והעידו עליו שוב אין כל צורך בעדים נוספים שיבואו ויחללו את השבת ולא ניתנה רשות לחללה. \u0003אבל הכא\u0004 \u0005[כאן\u0006 במילה\u0005]\u0006 ש\u0003ניתנה שבת לידחות,\u0004 שהרי מותר אפילו להתחיל במילה בשבת — \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 יהא מותר אף לדעת ר' יוסי לגמור את המילה.","\u0003אלא אמרי נהרדעי\u0004 \u0005[אמרו\u0006 חכמי \u0005נהרדעא]:\u0006 דעה זו כשיטת \u0003רבנן דפליגי עליה\u0004 \u0005[החלוקים עליו]\u0006 על \u0003ר' יוסי\u0004 במקום אחר \u0003היא. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003ארבעה כהנים נכנסין\u0004 אל ההיכל בכל שבת לסדר את לחם הפנים, \u0003שנים\u0004 מהם \u0003בידם שני סדרים\u0004 (מערכות) של לחם, ביד כל אחד שש חלות. \u0003ושנים בידם שני בזיכין\u0004 (כלים המלאים לבונה). \u0003וארבעה\u0004 כהנים \u0003מקדימין\u0004 ונכנסים \u0003לפניהם, שנים\u0004 הבאים \u0003ליטול\u0004 את \u0003שני\u0004 ה\u0003סדרים\u0004 המונחים על השולחן מהשבוע הקודם, \u0003ושנים\u0004 הבאים \u0003ליטול\u0004 את \u0003שני\u0004 ה\u0003בזיכין.\u0004 ואז \u0003המכניסין עומדים בצפון ופניהם לדרום, והמוציאין עומדים בדרום ופניהם לצפון, אלו מושכים\u0004 את הלחם הישן, \u0003ואלו מניחין,\u0004 וכך יוצא ש\u0003טפחו של זה בצד טפחו של זה\u0004 ותמיד יש לחם במידה הראוייה על השלחן, \u0003משום שנאמר \"\u0004ונתת על השולחן לחם פנים \u0003לפני תמיד\"\u0004 (שמות כה, ל).","\u0003ר' יוסי אומר: אפילו אלו נוטלין\u0004 לגמרי את הלחם הקודם \u0003ו\u0004רק אחר כך \u0003אלו מניחין\u0004 את החדש, \u0003אף זה היה בכלל \"תמיד\",\u0004 ואין צורך לעשות את הדברים בלא הפסקה כלל. נמצא שסבורים חכמים שאם מפסיק רגע קטן בעשיית מצווה הרי זה כאילו בטל לגמרי מעשייתה, ולאותה שיטה הרי גם בענין מילה, שהפסיק בעשייתה — הרי זה כאילו סיים את המצווה ושוב אין לו רשות לחזור עליה, ששוב אינו נחשב כעוסק בה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מהלקטין\u0004 (גומרים לחתוך) \u0003את המילה, ואם לא הילקט\u0004 — \u0003ענוש כרת.\u0004 ושואלים: \u0003מני\u0004 \u0005[\u0006דין כרת זה \u0005מיהו\u0006 הענוש בו\u0005]?\u0006 \u0003אמר ר' כהנא: אומן\u0004 (המוהל). שאם לא גמר האומן את המילה בשבת הרי הוא ענוש כרת שעשה פצע בלא לעשות מצווה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב פפא:\u0004 מדוע יתחייב ה\u0003אומן? לימא להו\u0004 \u0005[יאמר להם]:\u0006 \u0003אנא עבדי פלגא\u0004 \u0005[אני עשיתי מחצית]\u0006 ה\u0003מצוה\u0004 — \u0003אתון עבדיתו פלגא\u0004 \u0005[אתם תעשו מחצית]\u0006 ה\u0003מצוה\u0004 האחר, ואיני חייב — משום שהתעסקתי בפעולה של מצוה, אף שלא גמרתיה. \u0003אלא אמר רב פפא:\u0004 אין מדובר כאן במילה בשבת אלא במצות מילה בכללה, ומיהו החייב בכרת — אדם \u0003גדול\u0004 שנימול בזמנו, אבל לא הילקטו את מילתו, שעדיין לא נימול כהילכתו — חייב כרת כמי שלא נימול.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אשי:\u0004 אם כן, מה חידוש בדבר? והלא \u0003גדול בהדיא כתיב ביה\u0004 \u0005[במפורש נאמר בו]\u0006 \u0003\"וערל זכר אשר לא ימול\u0004 את בשר ערלתו ונכרתה הנפש ההיא מעמיה את בריתי הפר\u0003\"\u0004 (בראשית יז, יד)! \u0003אלא אמר רב אשי: לעולם\u0004 מדובר ב\u0003אומן\u0004 ובשבת, \u0003וכגון דאתא\u0004 \u0005[שבא,\u0006 המוהל\u0005]\u0006 למול \u0003בין השמשות\u0004 של יום ה\u0003שבת\u0004 קרוב למוצאי שבת, \u0003ואמרו ליה\u0004 \u0005[לו]:\u0006 \u0003לא מספקת\u0004 \u0005[תספיק]\u0006 לגמור את המילה, \u0003ואמר להו\u0004 \u0005[להם]:\u0006 \u0003מספקינא\u0004 \u0005[מספיק אני]\u0006 ואמול בו ביום, \u0003ועבד\u0004 \u0005[ועשה]\u0006 \u0003ולא איסתפק\u0004 \u0005[הספיק]\u0006 לגמור את המילה לפני צאת השבת, \u0003ואישתכח\u0004 \u0005[ונמצא]\u0006 ש\u0003חבורה הוא דעבד\u0004 \u0005[שעשה]\u0006 בילד, אבל לא קיים עדיין מצווה, \u0003ו\u0004לכן הוא \u0003ענוש כרת\u0004 כמי שעשה חבורה שלא לצורך מצווה, שהרי הזהירוהו מתחילה שלא יעשה זאת.","שנינו במשנה ש\u0003מוצצין\u0004 את המילה בשבת. \u0003אמר רב פפא: האי אומנא דלא מייץ\u0004 \u0005[אומן,\u0006 מוהל \u0005שאינן מוצץ]\u0006 בכל מילה — \u0003סכנה הוא\u0004 לילד הנימול \u0003ועברינן ליה\u0004 \u0005[\u0006\u0005ומעבירים אותו]\u0006 מתפקידו כמוהל.","ומעירים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 שהרי \u0003מדקא מחללי עליה שבתא\u0004 \u0005[מכיון שמחללים על כך\u0006 את \u0005השבת]\u0006 ודאי אם שבלא זה \u0003סכנה הוא,\u0004 שהרי לא היו מחללים את השבת על דבר שאיננו סכנת נפשות! ומשיבים: אין זו הוכחה גמורה, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 ותוכל לחשוב כי \u0003האי דם מיפקד פקיד\u0004 \u0005[דם זה\u0006 רק \u0005כנוס וצרור\u0006 במקום\u0005]\u0006 והמוציא דבר הכנוס במקומו אין בו איסור מלאכת דישה מן התורה, ולכן הותר הדבר ולא משום סכנה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 כי דם זה \u0003חבורי מיחבר\u0004 \u0005[מחובר\u0006 הוא\u0005]\u0006 והמוציאו עושה דבר האסור מן התורה בשבת, ואולם בכל זאת הותר הדבר משום סכנה.","ו\u0003דומיא\u0004 \u0005[בדומה]\u0006 לדין \u0003איספלנית וכמון\u0004 השנויים במשנה, \u0003מה איספלנית וכמון כי לא עביד\u0004 \u0005[כאשר אינו עושה]\u0006 אותם \u0003סכנה הוא\u0004 לילד, \u0003אף הכי נמי כי לא עביד\u0004 \u0005[כאן גם כן כאשר אינו עושה]\u0006 מציצה לילד לאחר המילה \u0003סכנה הוא\u0004 לילד וניתנת שבת להידחות מפני הסכנה.","שנינו במשנה: \u0003ונותנין עליה\u0004 (על המילה) \u0003איספלנית\u0004 בשבת. \u0003אמר אביי, אמרה לי אם\u0004 \u0005[אומנתי]:\u0006 \u0003איספלניתא דכולהון כיבי שב מינאי תרבא וחדא קירא\u0004 \u0005[האיספלנית של כל הפצעים\u0006 יש לעשותה \u0005שבע מנות חלב ומנה אחת של שעוה].\u0006 \u0003רבא אמר:\u0004 איספלנית יש לעשותה \u0003קירא וקלבא רישינא\u0004 \u0005[שעוה ושרף אילן].\u0006","\u0003דרשה רבא\u0004 לרפואה זו \u0003במחוזא, קרעינהו\u0004 \u0005[קרעו]\u0006 \u0003בני מניומי אסיא למנייהו\u0004 \u0005[הרופא\u0006 את \u0005את בגדיהם]\u0006 מרוב צער שנודע לכל כיצד לעשות האיספלנית ולא יזדקקו להם. \u0003אמר להו\u0004 \u0005[להם]\u0006 רבא: \u0003שבקי לכו חדא\u0004 \u0005[הינחתי לכם\u0006 רפואה \u0005אחת]\u0006 שלא גיליתי, ותוכלו להשתמש בדבר ולהרוויח. וכפי ש\u0003אמר שמואל: האי מאן דמשי אפיה ולא נגיב טובא\u0004 \u0005[מי שרוחץ את פניו ואינו מתנגב הרבה]\u0006 — \u0003נקטרו ליה\u0004 \u0005[נעשים לו]\u0006 בבשרו"]]};
